def _prepare_documents_config_path(legacy_config_dir: str, filename: str) -> str:
    target_dir = get_netmon_documents_subdir("Config")
    clean_filename = str(filename or "").strip()
    target_path = os.path.join(target_dir, clean_filename)
    legacy_path = os.path.join(str(legacy_config_dir or "").strip(), clean_filename)
    if legacy_path and os.path.isfile(legacy_path) and not os.path.exists(target_path):
        try:
            os.makedirs(os.path.dirname(target_path), exist_ok=True)
            with open(legacy_path, "rb") as src_handle, open(
                target_path, "wb"
            ) as dst_handle:
                dst_handle.write(src_handle.read())
        except Exception:
            pass
    return target_path


def _prepare_documents_data_path(
    subdir: str, legacy_dir: str, filename: str
) -> str:
    target_dir = get_netmon_documents_subdir(subdir)
    clean_filename = str(filename or "").strip()
    target_path = os.path.join(target_dir, clean_filename)
    legacy_path = os.path.join(str(legacy_dir or "").strip(), clean_filename)
    if legacy_path and os.path.isfile(legacy_path) and not os.path.exists(target_path):
        try:
            os.makedirs(os.path.dirname(target_path), exist_ok=True)
            with open(legacy_path, "rb") as src_handle, open(
                target_path, "wb"
            ) as dst_handle:
                dst_handle.write(src_handle.read())
        except Exception:
            pass
    return target_path

