    def on_close(self):
        if bool(self.__dict__.get("_netmon_closing", False)):
            try:
                self.destroy()
            except Exception:
                pass
            return
        self._netmon_closing = True
        try:
            guided_tour = self.__dict__.get("guided_tour")
            if guided_tour is not None:
                guided_tour.stop(log_message=False)
        except Exception:
            pass
        try:
            self.withdraw()
            self.update_idletasks()
        except Exception:
            pass

        def _finish_close():
            try:
                self.system_monitor_active = False
                self.process_guard_monitoring = False
                detached_radio = False
                standalone_transition = False
                if netmon_radio_core is not None:
                    try:
                        detached_radio = bool(netmon_radio_core.radio_is_detached())
                    except Exception:
                        detached_radio = False
                    try:
                        standalone_transition = bool(
                            netmon_radio_core.radio_transition_in_progress("standalone")
                        )
                    except Exception:
                        standalone_transition = False
                panel = self.__dict__.get("radio_embedded_panel")
                if panel is not None and not (detached_radio or standalone_transition):
                    try:
                        panel.close_projectm_visualizer_test()
                    except Exception:
                        pass
                    try:
                        panel.stop_radio_playback(async_mode=False)
                    except Exception:
                        pass
                if netmon_radio_core is not None:
                    try:
                        netmon_radio_core.clear_netmon_host_state(os.getpid())
                    except Exception:
                        pass
                clock_after_id = self.__dict__.get("_clock_after_id")
                if clock_after_id:
                    try:
                        self.after_cancel(clock_after_id)
                    except Exception:
                        pass
                    self._clock_after_id = None
                if not (detached_radio or standalone_transition):
                    try:
                        self.stop_radio()
                    except Exception:
                        pass
                try:
                    self.stop_running_fun_game()
                except Exception:
                    pass
            finally:
                try:
                    self.destroy()
                except Exception:
                    pass

        try:
            self.after(10, _finish_close)
        except Exception:
            _finish_close()

    def report_callback_exception(self, exc, val, tb):
        diagnostic_path = _append_crash_dump(
            "tk.report_callback_exception",
            exc,
            val,
            tb,
            context={
                "area": "gui-callback",
                "ui_state": self._diagnostic_ui_state(),
            },
        )
        self._remember_diagnostic_report_path(diagnostic_path)
        try:
            message = f"Unerwarteter GUI-Fehler. Crash-Dump: {CRASH_LOG_PATH}"
            if diagnostic_path:
                message += f" | Diagnose: {diagnostic_path}"
            self.log(message)
            if diagnostic_path:
                self._append_diagnostic_log_links()
        except Exception:
            pass
        try:
            traceback.print_exception(exc, val, tb, file=sys.stderr)
        except Exception:
            pass

    def _remember_diagnostic_report_path(self, path):
        normalized = os.path.abspath(os.path.expanduser(str(path or "").strip()))
        if normalized and os.path.isfile(normalized):
            self._latest_diagnostic_report_path = normalized
            return normalized
        return ""

    def _get_latest_diagnostic_report_path(self):
        remembered = str(
            getattr(self, "_latest_diagnostic_report_path", "") or ""
        ).strip()
        if remembered and os.path.isfile(remembered):
            return remembered
        latest = str(latest_diagnostic_report_path() or "").strip()
        return self._remember_diagnostic_report_path(latest)

    def _open_path_with_xdg_open(self, path, *, label="Datei"):
        target = os.path.abspath(os.path.expanduser(str(path or "").strip()))
        if not target:
            return False
        if not shutil.which("xdg-open"):
            self.log_safe(f"{label} öffnen nicht verfügbar: xdg-open fehlt.")
            return False
        try:
            subprocess.Popen(
                ["xdg-open", target],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
            return True
        except Exception as exc:
            self.log_safe(f"{label} konnte nicht geöffnet werden: {exc}")
            return False

    def _open_latest_diagnostic_report(self):
        path = self._get_latest_diagnostic_report_path()
        if not path:
            self.log_safe("Kein Diagnosebericht gefunden.")
            return False
        return self._open_path_with_xdg_open(path, label="Diagnosebericht")

    def _open_diagnostics_folder(self):
        return self._open_path_with_xdg_open(
            diagnostic_reports_dir(),
            label="Diagnoseordner",
        )

    def _append_diagnostic_log_links(self):
        opened_report = self._append_log_link(
            "Letzten Diagnosebericht öffnen",
            self._open_latest_diagnostic_report,
        )
        opened_folder = self._append_log_link(
            "Diagnoseordner öffnen",
            self._open_diagnostics_folder,
        )
        return bool(opened_report or opened_folder)

    def _remember_support_package_path(self, path):
        normalized = os.path.abspath(os.path.expanduser(str(path or "").strip()))
        if normalized and os.path.isfile(normalized):
            self._latest_support_package_path = normalized
            return normalized
        return ""

    def _get_latest_support_package_path(self):
        remembered = str(getattr(self, "_latest_support_package_path", "") or "").strip()
        if remembered and os.path.isfile(remembered):
            return remembered
        try:
            candidates = []
            for name in os.listdir(support_packages_dir()):
                if not name.startswith("netmon-support-") or not name.endswith(".zip"):
                    continue
                path = os.path.join(support_packages_dir(), name)
                if os.path.isfile(path):
                    candidates.append(path)
            if not candidates:
                return ""
            candidates.sort(key=lambda path: os.path.getmtime(path), reverse=True)
            return self._remember_support_package_path(candidates[0])
        except Exception:
            return ""

    def _support_form_placeholders(self):
        return {
            "contact_name": "Platzhalter: Name oder Kürzel (optional)",
            "contact_email": "Platzhalter: E-Mail-Adresse (optional)",
            "last_step": "Platzhalter: letzter Schritt vor dem Fehler",
            "repro": "Platzhalter: z. B. immer / manchmal / noch unklar",
            "details": (
                "Platzhalter: kurze Fehlerbeschreibung, Beobachtungen, "
                "gewünschtes Verhalten"
            ),
        }

    def _support_form_clean_value(self, value, placeholder=""):
        text = str(value or "").strip()
        marker = str(placeholder or "").strip()
        if not text or text == marker:
            return ""
        return text

    def _build_about_support_form_metadata(
        self,
        *,
        contact_name="",
        contact_email="",
        last_step="",
        repro_status="",
        details="",
    ):
        placeholders = self._support_form_placeholders()
        return {
            "user_report": {
                "contact_name": self._support_form_clean_value(
                    contact_name,
                    placeholders["contact_name"],
                ),
                "contact_email": self._support_form_clean_value(
                    contact_email,
                    placeholders["contact_email"],
                ),
                "last_step": self._support_form_clean_value(
                    last_step,
                    placeholders["last_step"],
                ),
                "repro_status": self._support_form_clean_value(
                    repro_status,
                    placeholders["repro"],
                ),
                "details": self._support_form_clean_value(
                    details,
                    placeholders["details"],
                ),
            }
        }

    def create_support_package(self, extra_metadata=None):
        metadata = {
            "last_action": self._diagnostic_last_action_context(),
            "runtime_state": self._diagnostic_runtime_state(),
        }
        if isinstance(extra_metadata, dict):
            metadata.update(extra_metadata)
        try:
            path = create_support_package(metadata=metadata)
        except Exception as exc:
            self.log_safe(f"Supportpaket konnte nicht erzeugt werden: {exc}")
            return ""
        remembered = self._remember_support_package_path(path)
        if remembered:
            self.log_safe(f"Supportpaket erstellt: {remembered}")
        return remembered

    def open_support_packages_folder(self):
        return self._open_path_with_xdg_open(
            support_packages_dir(),
            label="Supportordner",
        )

    def open_latest_support_package(self):
        path = self._get_latest_support_package_path()
        if not path:
            self.log_safe("Kein Supportpaket gefunden.")
            return False
        return self._open_path_with_xdg_open(path, label="Supportpaket")

    def copy_latest_support_package_path(self):
        path = self._get_latest_support_package_path()
        if not path:
            self.log_safe("Kein Supportpaketpfad zum Kopieren vorhanden.")
            return False
        try:
            self.clipboard_clear()
            self.clipboard_append(path)
            self.log_safe(f"Supportpaketpfad kopiert: {path}")
            return True
        except Exception as exc:
            self.log_safe(f"Supportpaketpfad konnte nicht kopiert werden: {exc}")
            return False

