    def start_guided_tour(self, tour_name="quickstart"):
        manager = getattr(self, "guided_tour", None)
        if manager is None:
            return False
        definitions = self._guided_tour_definitions()
        selected = definitions.get(str(tour_name or "").strip().lower())
        if not isinstance(selected, dict):
            return False
        try:
            self._record_diagnostic_action(
                "guided-tour-start",
                "ui-tour",
                details={"tour": str(selected.get("id") or tour_name or "")},
            )
        except Exception:
            pass
        started = manager.start(
            selected.get("steps", []),
            title=str(selected.get("title") or "NetMon Tour"),
            tour_id=str(selected.get("id") or tour_name or ""),
        )
        if started:
            try:
                self.log_safe(
                    f"Geführte Tour gestartet: {str(selected.get('title') or tour_name)}"
                )
            except Exception:
                pass
        return started

    def maybe_offer_quickstart_tour(self):
        if bool(getattr(self, "_quickstart_tour_offer_done", False)):
            return False
        self._quickstart_tour_offer_done = True
        if bool(getattr(self, "_netmon_closing", False)):
            return False
        if not bool(self.settings.get("guided_tour_offer_on_startup", True)):
            return False
        if self.is_guided_tour_completed("quickstart"):
            return False
        manager = getattr(self, "guided_tour", None)
        if manager is not None and manager.is_active():
            return False
        try:
            start_now = messagebox.askyesno(
                "NetMon Schnellstart",
                (
                    "Möchtest du eine kurze Einführung durch die wichtigsten "
                    "Bereiche von NetMon starten?"
                ),
                parent=self,
            )
        except Exception:
            return False
        if start_now:
            return self.start_quickstart_tour()
        return False

    def on_guided_tour_offer_toggle(self):
        enabled = bool(self.var_guided_tour_offer_on_startup.get())
        self.settings["guided_tour_offer_on_startup"] = enabled
        self.save_settings(log_success=False)
        try:
            self.log_safe(
                "Schnellstart-Tour wird beim Start angeboten."
                if enabled
                else "Schnellstart-Tour wird beim Start nicht mehr angeboten."
            )
        except Exception:
            pass

    def _guided_tour_completed_settings(self) -> dict:
        raw = self.settings.get("guided_tour_completed", {})
        if not isinstance(raw, dict):
            return {}
        normalized = {}
        for key, value in raw.items():
            name = str(key or "").strip().lower()
            if name:
                normalized[name] = bool(value)
        return normalized

    def is_guided_tour_completed(self, tour_name) -> bool:
        tour_id = str(tour_name or "").strip().lower()
        if not tour_id:
            return False
        return bool(self._guided_tour_completed_settings().get(tour_id, False))

    def _guided_tour_status_text(self) -> str:
        labels = (
            ("quickstart", "Schnellstart"),
            ("dns", "DNS"),
            ("security", "Security"),
            ("download-scan", "D-Scan"),
            ("radio", "Radio"),
        )
        done = []
        open_items = []
        for key, label in labels:
            if self.is_guided_tour_completed(key):
                done.append(label)
            else:
                open_items.append(label)
        if done and open_items:
            return (
                "Tourstatus: abgeschlossen: "
                + ", ".join(done)
                + " | offen: "
                + ", ".join(open_items)
            )
        if done:
            return "Tourstatus: alle verfügbaren Touren abgeschlossen."
        return "Tourstatus: noch keine Tour abgeschlossen."

    def _guided_tour_button_text(self, _tour_name, _base_label) -> str:
        return "Start"

    def _guided_tour_status_symbol(self, tour_name) -> str:
        return "[x]" if self.is_guided_tour_completed(tour_name) else "[ ]"

    def _guided_tour_title_text(self, tour_name, base_label) -> str:
        label = str(base_label or "").strip()
        if not label:
            return ""
        if self.is_guided_tour_completed(tour_name):
            return f"{label} abgeschlossen"
        return label

