    def _guided_tour_security_tools_hint(self):
        parts = []
        parts.append("Lynis bereit." if has_cmd("lynis") else "Lynis fehlt.")
        try:
            rkh_ready = bool(is_rkhunter_installed())
        except Exception:
            rkh_ready = bool(has_cmd("rkhunter"))
        parts.append("rkhunter bereit." if rkh_ready else "rkhunter fehlt.")
        parts.append(
            "ClamAV bereit." if self._download_scan_clamav_available() else "ClamAV fehlt."
        )
        return " ".join(parts)

    def _guided_tour_packet_capture_hint(self):
        if self.wireshark_launch_blocked():
            return (
                "Wireshark-Start ist in NetMon aktuell gesperrt. Mitschnitte sind "
                "trotzdem möglich, aber das direkte Öffnen in Wireshark bleibt blockiert."
            )
        dep_status = self.get_dependency_status()
        if bool(dep_status.get("wireshark", False)):
            return "Wireshark ist verfügbar. Mitschnitte können nach dem Erfassen direkt weitergereicht werden."
        return (
            "Wireshark ist aktuell nicht verfügbar. Für Rohmitschnitte reichen die "
            "Capture-Funktionen, die GUI-Auswertung braucht aber Wireshark oder tshark."
        )

    def _guided_tour_security_summary_hint(self):
        recommendations = []
        if not has_cmd("lynis"):
            recommendations.append("Lynis nachrüsten")
        try:
            rkh_ready = bool(is_rkhunter_installed())
        except Exception:
            rkh_ready = bool(has_cmd("rkhunter"))
        if not rkh_ready:
            recommendations.append("rkhunter nachrüsten")
        if not self._download_scan_clamav_available():
            recommendations.append("ClamAV nachrüsten")
        if self.wireshark_launch_blocked():
            recommendations.append("Wireshark ist in NetMon bewusst gesperrt")
        if recommendations:
            return "Aktueller Zustand: " + ", ".join(recommendations) + "."
        return "Vor echten Analysen lohnt sich ein Blick auf Status, Rechte und verfügbare Werkzeuge."

    def _guided_tour_security_setup_action_label(self):
        try:
            rkh_ready = bool(is_rkhunter_installed())
        except Exception:
            rkh_ready = bool(has_cmd("rkhunter"))
        missing_any = (
            not has_cmd("lynis")
            or not self._download_scan_clamav_available()
            or not rkh_ready
        )
        return "Setup-Assistent öffnen" if missing_any else ""

