    def _write_root_text_file(self, path, content):
        tmp_path = ""
        try:
            parent_dir = os.path.dirname(path)
            if parent_dir:
                rc_dir, out_dir = run_cmd(
                    ["sudo", "-n", "mkdir", "-p", parent_dir], timeout=10
                )
                if rc_dir != 0:
                    return (
                        False,
                        (out_dir or "").strip()
                        or f"Verzeichnis konnte nicht erstellt werden: {parent_dir}",
                    )
            with tempfile.NamedTemporaryFile(
                mode="w", encoding="utf-8", delete=False
            ) as temp_file:
                temp_file.write(content)
                tmp_path = temp_file.name
            rc_install, out_install = run_cmd(
                ["sudo", "-n", "install", "-m", "644", tmp_path, path],
                timeout=12,
            )
            if rc_install != 0:
                return (
                    False,
                    (out_install or "").strip()
                    or f"Datei konnte nicht geschrieben werden: {path}",
                )
            return True, ""
        finally:
            if tmp_path:
                try:
                    os.remove(tmp_path)
                except Exception:
                    pass

    def _remove_root_text_file(self, path):
        rc_rm, out_rm = run_cmd(["sudo", "-n", "rm", "-f", path], timeout=10)
        if rc_rm != 0:
            return (
                False,
                (out_rm or "").strip() or f"Datei konnte nicht entfernt werden: {path}",
            )
        return True, ""

