    def _write_manual_dns_dropin(self, dns_choice):
        servers = self._dns_servers_for_choice(dns_choice)
        if not servers:
            return False, "Keine gültigen DNS-Server ausgewählt."
        dnssec_mode = "allow-downgrade"
        preferred_mode = getattr(self, "get_preferred_dnssec_mode", None)
        if callable(preferred_mode) and preferred_mode() == "strict":
            dnssec_mode = "yes"
        content = "\n".join(
            [
                "# Managed by NetMon",
                "[Resolve]",
                f"DNS={' '.join(servers)}",
                "DNSOverTLS=no",
                f"DNSSEC={dnssec_mode}",
                "Domains=~.",
                "",
            ]
        )
        return self._write_dot_dropin_text(content)

    def _write_dot_dropin_text(self, content):
        service = self._dns_control_service()
        if service is None:
            tmp_path = ""
            try:
                with tempfile.NamedTemporaryFile(
                    mode="w", encoding="utf-8", delete=False
                ) as temp_file:
                    temp_file.write(content)
                    tmp_path = temp_file.name
                rc_dir, out_dir = run_cmd(
                    ["sudo", "-n", "mkdir", "-p", DOT_DROPIN_DIR],
                    timeout=10,
                )
                if rc_dir != 0:
                    return (
                        False,
                        (out_dir or "").strip() or "Drop-in-Verzeichnis fehlt.",
                    )
                rc_install, out_install = run_cmd(
                    ["sudo", "-n", "install", "-m", "644", tmp_path, DOT_DROPIN_PATH],
                    timeout=12,
                )
                if rc_install != 0:
                    return (
                        False,
                        (out_install or "").strip()
                        or "DNS-Drop-in konnte nicht geschrieben werden.",
                    )
                return True, content
            finally:
                if tmp_path:
                    try:
                        os.remove(tmp_path)
                    except Exception:
                        pass

        ok, detail = service.write_dropin(content)
        return ok, content if ok else detail

    def _restore_dot_dropin_backup(self, previous_text):
        previous_text = previous_text if previous_text is not None else ""
        if not previous_text.strip():
            return self._remove_manual_dns_dropin()
        return self._write_dot_dropin_text(previous_text)

    def _remove_manual_dns_dropin(self):
        service = self._dns_control_service()
        if service is None:
            rc_rm, out_rm = run_cmd(
                ["sudo", "-n", "rm", "-f", DOT_DROPIN_PATH],
                timeout=10,
            )
            return rc_rm == 0, (out_rm or "").strip()
        return service.remove_dropin()

    def _restart_resolved_for_dns_policy(self):
        service = self._dns_control_service()
        if service is None:
            rc, out = run_cmd(
                ["sudo", "-n", "systemctl", "restart", "systemd-resolved"],
                timeout=15,
            )
            return rc == 0, (out or "").strip()
        return service.restart_resolved()

