    def confirm_chad_send(self, title: str, intro_text: str) -> bool:
        if tk is None or ttk is None:
            return messagebox.askyesno(title, intro_text, parent=self)

        result = {"ok": False}
        win = tk.Toplevel(self)
        win.title(title)
        win.geometry("560x220")
        win.resizable(False, False)
        win.transient(self)

        outer = ttk.Frame(win, padding=12)
        outer.pack(fill="both", expand=True)

        ttk.Label(
            outer,
            text=intro_text,
            justify="left",
            wraplength=520,
        ).pack(anchor="w")

        ttk.Label(
            outer,
            text=self.tr("chad_security_notice_title", "Sicherheitshinweis"),
            justify="left",
            font=("TkDefaultFont", 10, "bold"),
        ).pack(anchor="w", pady=(12, 4))

        ttk.Label(
            outer,
            text=self.tr(
                "chad_security_notice_body",
                "Bitte keine sensiblen Daten absenden.\n"
                "Dazu gehören z. B. Passwörter, API-Keys, Tokens, private Schlüssel, "
                "persönliche Daten oder interne Inhalte.\n\n"
                "Bitte vor dem Senden sorgfältig prüfen und nur notwendige Ausschnitte übertragen.",
            ),
            justify="left",
            wraplength=520,
        ).pack(anchor="w")

        btn_row = ttk.Frame(outer)
        btn_row.pack(fill="x", pady=(14, 0))

        def _close(ok: bool):
            result["ok"] = bool(ok)
            try:
                win.grab_release()
            except Exception:
                pass
            win.destroy()

        ttk.Button(
            btn_row,
            text=self.tr("btn_cancel", "Abbrechen"),
            command=lambda: _close(False),
        ).pack(side="right")
        ttk.Button(
            btn_row,
            text=self.tr("btn_continue", "Fortfahren"),
            command=lambda: _close(True),
        ).pack(side="right", padx=(0, 8))

        win.protocol("WM_DELETE_WINDOW", lambda: _close(False))
        try:
            win.grab_set()
            win.focus_force()
        except Exception:
            pass
        self.wait_window(win)
        return result["ok"]

    def _get_about_program_system_info(self):
        distro_name = "folgt"
        try:
            release_info = platform.freedesktop_os_release()
            pretty_name = str(release_info.get("PRETTY_NAME") or "").strip()
            if pretty_name:
                distro_name = pretty_name
        except Exception:
            pass
        return {
            "distribution": distro_name,
            "kernel": platform.release() or "folgt",
            "python": platform.python_version() or "folgt",
            "netmon": NETMON_APP_VERSION or "folgt",
        }

