    def _apply_settings_runtime_state(self):
        dns_guard_enabled = bool(self.settings.get("dns_guard_enabled", True))
        self.dns_guard_enabled = dns_guard_enabled
        self.debug_network_logging = bool(
            self.settings.get("debug_network_logging", False)
        )
        self.danger_guard_enabled = bool(self.settings.get("strict_protection", True))
        current_theme_name = (
            str(self.__dict__.get("_preferred_theme_name", "light") or "light")
            .strip()
            .lower()
            or "light"
        )
        self._preferred_theme_name = self._normalize_theme_name(
            self.settings.get("theme", current_theme_name)
        )

        guard_var = self.__dict__.get("dns_guard_enabled_var")
        if guard_var is not None:
            try:
                guard_var.set(dns_guard_enabled)
            except Exception:
                pass

        strict_var = self.__dict__.get("strict_protection_var")
        if strict_var is not None:
            try:
                strict_var.set(bool(self.settings.get("strict_protection", True)))
            except Exception:
                pass

        tooltips_var = self.__dict__.get("tooltips_enabled")
        if tooltips_var is not None:
            try:
                tooltips_var.set(bool(self.settings.get("tooltips_enabled", True)))
            except Exception:
                pass

        theme_choice_var = self.__dict__.get("var_theme_choice")
        if theme_choice_var is not None:
            try:
                theme_choice_var.set(
                    self._get_theme_display_name(self.settings.get("theme", "light"))
                )
            except Exception:
                pass

        self._sync_settings_vars_from_settings()
        self.refresh_wireshark_launch_controls()
        self.on_tooltip_toggle()

    def load_settings(self):
        try:
            if not os.path.isfile(self.netmon_config_path):
                return

            with open(self.netmon_config_path, "r", encoding="utf-8") as handle:
                data = json.load(handle)

            if isinstance(data, dict):
                self.settings.update(data)
                self.settings["start_network_mode"] = "system"
                self.settings["start_vpn_profile"] = ""
                self.settings["start_killswitch"] = False
                self.settings["start_dot"] = False

        except Exception as e:
            try:
                self.log(f"[WARN] Einstellungen konnten nicht geladen werden: {e}")
            except Exception:
                pass

    def save_settings(self, log_success: bool = True):
        try:
            os.makedirs(self.netmon_config_dir, exist_ok=True)

            ok, err = safe_write_json(
                self.netmon_config_path,
                self.settings,
                indent=2,
                ensure_ascii=False,
            )

            if ok:
                if log_success:
                    self.log("Einstellungen gespeichert.")
            else:
                self.log(
                    f"[WARN] Einstellungen konnten nicht gespeichert werden: {err}"
                )

        except Exception as e:
            self.log(f"[WARN] Einstellungen konnten nicht gespeichert werden: {e}")

