    def reset_settings_to_defaults(self):
        self.settings.update(self._default_settings_payload())
        self._apply_settings_runtime_state()
        autostart_var = self.__dict__.get("autostart_var")
        if autostart_var is not None:
            try:
                autostart_var.set(self.is_autostart_enabled())
            except Exception:
                pass
        radio_launcher_var = self.__dict__.get("radio_desktop_launcher_var")
        if radio_launcher_var is not None:
            try:
                radio_launcher_var.set(self.is_radio_desktop_launcher_enabled())
            except Exception:
                pass
        self.save_settings()

        if "privacy_config" in self.__dict__:
            self.save_privacy_config()

        if self.lang_service is not None:
            self.lang = self.lang_service.load(
                str(self.settings.get("language", "de") or "de")
            )
        if self.__dict__.get("tk") is not None:
            self.apply_theme(
                self._normalize_theme_name(self.settings.get("theme", "light")),
                log_change=False,
                persist=False,
            )
        self.log(self.tr("log_settings_reset", "Einstellungen zurückgesetzt."))

    def _update_download_scan_result_text(self, message: str):
        widget = self.__dict__.get("download_scan_result_text")
        if widget is None:
            return
        try:
            widget.configure(state="normal")
            widget.delete("1.0", "end")
            widget.insert(
                "1.0",
                str(message or "").strip() or "Noch kein Scan durchgeführt.",
            )
            widget.configure(state="disabled")
        except Exception:
            pass

    def _set_download_scan_status(
        self,
        *,
        status: str | None = None,
        result: str | None = None,
        filename: str | None = None,
        last_scan: str | None = None,
        log_message: str | None = None,
    ):
        if status is not None:
            try:
                self.download_scan_status_var.set(status)
            except Exception:
                pass
        if result is not None:
            try:
                self.download_scan_result_summary_var.set(result)
            except Exception:
                pass
        if filename is not None:
            try:
                self.download_scan_file_var.set(filename)
            except Exception:
                pass
        if last_scan is not None:
            try:
                self.download_scan_last_scan_var.set(last_scan)
            except Exception:
                pass
        if log_message:
            try:
                self.log_safe(log_message)
            except Exception:
                pass

    def _normalized_download_scan_temp_dir(self) -> str:
        raw = str(self.download_scan_temp_dir_var.get() or "").strip()
        return os.path.abspath(
            os.path.expanduser(raw or self._default_download_scan_temp_dir())
        )

    def _normalized_download_scan_target_dir(self) -> str:
        raw = str(self.download_scan_target_dir_var.get() or "").strip()
        return os.path.abspath(
            os.path.expanduser(raw or self._default_download_scan_target_dir())
        )

    def _refresh_download_scan_temp_security_status(self):
        path = self._normalized_download_scan_temp_dir()
        status, hint = self._describe_download_scan_temp_security(path)
        warning = ""
        success = ""
        if self._download_scan_secure_mount_ready(path):
            success = "Vor-Quarantäne sicher aktiv: tmpfs + noexec + nosuid + nodev"
        if not self._download_scan_mount_has_option(path, "noexec"):
            warning = (
                "Warnung: Der aktuelle Temp-Pfad hat kein noexec. "
                "Dateien bitte niemals direkt aus diesem Ordner starten."
            )
        try:
            self.download_scan_temp_security_var.set(status)
        except Exception:
            pass
        try:
            self.download_scan_temp_hint_var.set(hint)
        except Exception:
            pass
        try:
            self.download_scan_temp_warning_var.set(warning)
        except Exception:
            pass
        try:
            self.download_scan_temp_success_var.set(success)
        except Exception:
            pass

    def _ensure_download_scan_secure_mount(self, *, interactive: bool = False) -> bool:
        target = self._normalized_download_scan_temp_dir()
        if self._download_scan_secure_mount_ready(target):
            self._refresh_download_scan_temp_security_status()
            return True

        try:
            os.makedirs(target, exist_ok=True)
            try:
                os.chmod(target, 0o700)
            except Exception:
                pass
        except Exception as exc:
            self.log_safe(f"Vor-Quarantäne konnte nicht vorbereitet werden: {exc}")
            return False

        if not has_cmd("sudo") or not has_cmd("mount"):
            self._refresh_download_scan_temp_security_status()
            self.log_safe(
                "Vor-Quarantäne ohne sicheren tmpfs-Mount: sudo oder mount fehlt."
            )
            return False

        if interactive:
            if not self.ensure_sudo_session("Vor-Quarantäne mit noexec aktivieren"):
                self._refresh_download_scan_temp_security_status()
                return False
        elif not check_sudo_nopasswd():
            self._refresh_download_scan_temp_security_status()
            return False

        info = self._download_scan_mount_info(target)
        fs_type = str(info.get("fs_type") or "").strip().lower()
        option_string = self._download_scan_mount_option_string()
        if fs_type == "tmpfs":
            cmd = ["sudo", "-n", "mount", "-o", f"remount,{option_string}", target]
        else:
            cmd = [
                "sudo",
                "-n",
                "mount",
                "-t",
                "tmpfs",
                "-o",
                option_string,
                "tmpfs",
                target,
            ]
        rc, out = run_cmd(cmd, timeout=20)
        if rc != 0:
            self._refresh_download_scan_temp_security_status()
            self.log_safe(
                "Vor-Quarantäne konnte nicht als tmpfs/noexec eingebunden werden: "
                + (str(out or "").strip() or f"Rückgabecode {rc}")
            )
            return False

        try:
            os.chmod(target, 0o700)
        except Exception:
            pass
        self._refresh_download_scan_temp_security_status()
        self.log_safe(f"Vor-Quarantäne aktiv: {target} ({option_string})")
        return self._download_scan_secure_mount_ready(target)

    def _clear_download_scan_temp_contents(self, *, startup: bool = False) -> int:
        target = self._normalized_download_scan_temp_dir()
        if not os.path.isdir(target):
            return 0
        removed = 0
        for entry in os.scandir(target):
            path = entry.path
            try:
                if entry.is_dir(follow_symlinks=False):
                    shutil.rmtree(path)
                else:
                    os.unlink(path)
                removed += 1
            except Exception as exc:
                self.log_debug_safe(
                    f"Download-Scan: Temp-Datei konnte nicht entfernt werden: {path} ({exc})"
                )
        return removed

    def prepare_download_scan_workspace(self, *, startup: bool = False):
        target = self._normalized_download_scan_temp_dir()
        try:
            os.makedirs(target, exist_ok=True)
            try:
                os.chmod(target, 0o700)
            except Exception:
                pass
            self._ensure_download_scan_secure_mount(interactive=not startup)
            self.download_scan_temp_dir_var.set(target)
            self._refresh_download_scan_temp_security_status()
            if startup:
                self._update_download_scan_result_text(
                    "Vor-Quarantäne vorbereitet.\n\n"
                    f"Pfad: {target}\n"
                    "Inhalte bleiben über NetMon-Neustarts erhalten.\n"
                    "Leeren nur manuell oder durch System-/Mount-Neustart."
                )
        except Exception as exc:
            self.log_debug_safe(
                f"Download-Scan: Workspace konnte nicht vorbereitet werden: {exc}"
            )

    def prepare_download_scan_startup_state(self):
        target = self._normalized_download_scan_temp_dir()
        self.download_scan_temp_dir_var.set(target)
        self._refresh_download_scan_temp_security_status()
        if bool(self.download_scan_prequarantine_startup_var.get()):
            try:
                self.after(800, self.create_download_scan_temp_folder)
            except Exception:
                self.create_download_scan_temp_folder()

    def _disable_download_scan_secure_mount(self, *, interactive: bool = False) -> bool:
        target = self._normalized_download_scan_temp_dir()
        if not self._download_scan_secure_mount_ready(target):
            self._refresh_download_scan_temp_security_status()
            return True

        if not has_cmd("sudo") or not has_cmd("umount"):
            self._refresh_download_scan_temp_security_status()
            self.log_safe(
                "Vor-Quarantäne konnte nicht deaktiviert werden: sudo oder umount fehlt."
            )
            return False

        if interactive:
            if not self.ensure_sudo_session("Vor-Quarantäne deaktivieren"):
                self._refresh_download_scan_temp_security_status()
                return False
        elif not check_sudo_nopasswd():
            self._refresh_download_scan_temp_security_status()
            return False

        rc, out = run_cmd(["sudo", "-n", "umount", target], timeout=20)
        self._refresh_download_scan_temp_security_status()
        if rc != 0:
            self.log_safe(
                "Vor-Quarantäne konnte nicht deaktiviert werden: "
                + (str(out or "").strip() or f"Rückgabecode {rc}")
            )
            return False

        self.log_safe(f"Vor-Quarantäne deaktiviert: {target}")
        return not self._download_scan_secure_mount_ready(target)

    def on_download_scan_prequarantine_startup_toggle(self):
        enabled = bool(self.download_scan_prequarantine_startup_var.get())
        self.settings["download_scan_prequarantine_startup"] = enabled
        self.save_settings(log_success=False)
        if enabled:
            return

        self.disable_download_scan_temp_folder(
            log_message="Vor-Quarantäne-Autostart deaktiviert",
        )

    def disable_download_scan_temp_folder(self, *, log_message=None):
        disabled = self._disable_download_scan_secure_mount(interactive=True)
        if not disabled:
            return False

        self._set_download_scan_status(
            status="🟡 ungeprüft",
            result="Vor-Quarantäne deaktiviert",
            last_scan="Noch kein Scan",
            log_message=log_message or "Vor-Quarantäne deaktiviert",
        )
        self._update_download_scan_result_text(
            "Vor-Quarantäne deaktiviert.\n\n"
            f"Pfad: {self._normalized_download_scan_temp_dir()}\n"
            "NetMon startet ohne aktivierte Vor-Quarantäne, bis du sie wieder einschaltest."
        )
        return True

    def create_download_scan_temp_folder(self):
        target = self._normalized_download_scan_temp_dir()
        try:
            os.makedirs(target, exist_ok=True)
            try:
                os.chmod(target, 0o700)
            except Exception:
                pass
            self.download_scan_temp_dir_var.set(target)
            secure_ready = self._ensure_download_scan_secure_mount(interactive=True)
            self._refresh_download_scan_temp_security_status()
            self._set_download_scan_status(
                status="🟡 ungeprüft",
                result=(
                    "Vor-Quarantäne aktiv" if secure_ready else "Temp-Ordner bereit"
                ),
                last_scan="Noch kein Scan",
                log_message=f"Temp-Download-Ordner bereit: {target}",
            )
            self._update_download_scan_result_text(
                "Vor-Quarantäne vorbereitet.\n\n"
                f"Pfad: {target}\n"
                f"{self.download_scan_temp_security_var.get()}\n"
                "Noch kein Scan durchgeführt."
            )
        except Exception as exc:
            messagebox.showerror(
                "Temp-Ordner erstellen",
                f"Der Temp-Ordner konnte nicht erstellt werden:\n{exc}",
                parent=self,
            )

    def open_download_scan_temp_folder(self):
        target = self._normalized_download_scan_temp_dir()
        if not os.path.isdir(target):
            self.create_download_scan_temp_folder()
        self.open_path_in_file_manager(target, "Temp-Ordner")
        self._set_download_scan_status(
            result="Temp-Ordner geöffnet",
            log_message=f"Temp-Ordner geöffnet: {target}",
        )

    def open_download_scan_target_folder(self):
        target = self._normalized_download_scan_target_dir()
        if not os.path.isdir(target):
            try:
                os.makedirs(target, exist_ok=True)
            except Exception:
                pass
        self.open_path_in_file_manager(target, "Zielordner")
        self._set_download_scan_status(
            result="Zielordner geöffnet",
            log_message=f"Zielordner geöffnet: {target}",
        )

    def choose_download_scan_temp_dir(self):
        folder = filedialog.askdirectory(
            title="Temp-Download-Ordner wählen",
            initialdir=self._normalized_download_scan_temp_dir(),
        )
        if not folder:
            return
        normalized = os.path.abspath(os.path.expanduser(folder))
        self.download_scan_temp_dir_var.set(normalized)
        self.prepare_download_scan_workspace(startup=False)
        self._set_download_scan_status(
            result="Temp-Pfad aktualisiert",
            log_message=f"Temp-Download-Pfad gesetzt: {normalized}",
        )
        self._update_download_scan_result_text(
            "Temp-Download-Pfad aktualisiert.\n\n"
            f"Neuer Pfad: {normalized}\n"
            f"{self.download_scan_temp_security_var.get()}\n"
            "Noch kein Scan durchgeführt."
        )

    def choose_download_scan_target_dir(self):
        folder = filedialog.askdirectory(
            title="Ziel-Downloadordner wählen",
            initialdir=self._normalized_download_scan_target_dir(),
        )
        if not folder:
            return
        normalized = os.path.abspath(os.path.expanduser(folder))
        self.download_scan_target_dir_var.set(normalized)
        self._set_download_scan_status(
            result="Zielordner aktualisiert",
            log_message=f"Zielordner gesetzt: {normalized}",
        )

    def clear_download_scan_temp_folder(self):
        target = self._normalized_download_scan_temp_dir()
        removed = self._clear_download_scan_temp_contents(startup=False)
        self._refresh_download_scan_temp_security_status()
        self._set_download_scan_status(
            status="🟡 ungeprüft",
            result=f"Temp-Ordner geleert ({removed})",
            last_scan="Noch kein Scan",
            log_message=f"Temp-Ordner geleert: {target} ({removed} Einträge entfernt)",
        )
        self._update_download_scan_result_text(
            "Temp-Ordner geleert.\n\n"
            f"Zielpfad: {target}\n"
            f"Entfernte Einträge: {removed}\n"
            "Dateien in diesem Bereich sind nur temporär gedacht."
        )

    def choose_download_scan_file(self):
        self.prepare_download_scan_workspace(startup=False)
        initial_dir = self._normalized_download_scan_temp_dir()
        if not self._download_scan_path_is_accessible(initial_dir):
            self.create_download_scan_temp_folder()
            initial_dir = self._normalized_download_scan_temp_dir()
        if not self._download_scan_path_is_accessible(initial_dir):
            messagebox.showerror(
                "ClamAV Download-Scan",
                "Der aktuelle Vor-Quarantänepfad ist nicht zugänglich.\n\n"
                f"Pfad: {initial_dir}\n\n"
                "Bitte Vor-Quarantäne erneut aktivieren oder den Pfad anpassen.",
                parent=self,
            )
            return
        self.download_scan_selected_file = ""
        try:
            file_path = filedialog.askopenfilename(
                title="Datei für Download-Scan auswählen",
                initialdir=initial_dir,
            )
        except tk.TclError as exc:
            messagebox.showerror(
                "ClamAV Download-Scan",
                "Der Dateidialog konnte den aktuellen Vor-Quarantänepfad nicht öffnen.\n\n"
                f"Pfad: {initial_dir}\n"
                f"Fehler: {exc}",
                parent=self,
            )
            return
        if not file_path:
            return
        normalized = os.path.abspath(os.path.expanduser(file_path))
        imported_from = ""
        try:
            normalized, imported_from = self._download_scan_import_file_to_temp(
                normalized
            )
        except Exception as exc:
            messagebox.showerror(
                "ClamAV Download-Scan",
                "Die Datei konnte nicht in die Vor-Quarantäne übernommen werden.\n\n"
                f"{exc}",
                parent=self,
            )
            return

        self.download_scan_selected_file = normalized
        result_lines = [
            "Datei ausgewählt.",
            "",
            f"Datei: {normalized}",
        ]
        log_message = f"Download-Scan-Datei ausgewählt: {normalized}"
        if imported_from:
            result_lines.extend(
                [
                    f"Importiert aus: {imported_from}",
                    "",
                    "Die Datei wurde zuerst in die Vor-Quarantäne übernommen.",
                ]
            )
            log_message = (
                f"Download-Scan-Datei in Vor-Quarantäne übernommen: {imported_from} -> "
                f"{normalized}"
            )
        else:
            result_lines.append("Die Datei liegt bereits in der Vor-Quarantäne.")
        result_lines.extend(["", "Noch kein Scan durchgeführt."])
        self._set_download_scan_status(
            status="🟡 ungeprüft",
            result="Datei ausgewählt, Scan noch nicht gestartet",
            filename=os.path.basename(normalized),
            last_scan="Noch kein Scan",
            log_message=log_message,
        )
        self._update_download_scan_result_text("\n".join(result_lines))

    def choose_and_scan_download_scan_file(self):
        self.choose_download_scan_file()
        selected = str(self.download_scan_selected_file or "").strip()
        if selected:
            self.scan_selected_download_scan_file()

    def _download_scan_clamav_available(self) -> bool:
        try:
            return bool(has_cmd("clamscan"))
        except Exception:
            return False

    def _download_scan_report_dir(self) -> str:
        return os.path.join(self._normalized_download_scan_temp_dir(), "reports")

    def _download_scan_report_path(self, scan_kind: str) -> str:
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        safe_kind = re.sub(r"[^a-zA-Z0-9_.-]", "_", scan_kind or "scan")
        return os.path.join(
            self._download_scan_report_dir(),
            f"netmon_download_scan_{safe_kind}_{stamp}.txt",
        )

    def _download_scan_write_report(self, scan_kind: str, report_text: str) -> str:
        if not bool(self.download_scan_save_report_var.get()):
            return ""
        try:
            report_dir = self._download_scan_report_dir()
            os.makedirs(report_dir, exist_ok=True)
            report_path = self._download_scan_report_path(scan_kind)
            with open(report_path, "w", encoding="utf-8") as handle:
                handle.write(report_text.rstrip() + "\n")
            return report_path
        except Exception as exc:
            self.log_debug_safe(
                f"Download-Scan-Bericht konnte nicht gespeichert werden: {exc}"
            )
            return ""

    def _download_scan_confirm_move(
        self, source_path: str, destination_path: str
    ) -> bool:
        decision = {"value": False}
        done = threading.Event()

        def _ask():
            try:
                decision["value"] = bool(
                    messagebox.askyesno(
                        "Datei verschieben",
                        "ClamAV hat keinen Fund gemeldet.\n\n"
                        f"Datei: {source_path}\n"
                        f"Ziel: {destination_path}\n\n"
                        "Jetzt in den Zielordner verschieben?",
                        parent=self,
                    )
                )
            except Exception:
                decision["value"] = False
            finally:
                done.set()

        self.after(0, _ask)
        done.wait()
        return bool(decision["value"])

    def _download_scan_unique_destination(self, source_path: str) -> str:
        target_dir = self._normalized_download_scan_target_dir()
        os.makedirs(target_dir, exist_ok=True)
        base_name = os.path.basename(source_path.rstrip(os.sep)) or "download"
        stem, ext = os.path.splitext(base_name)
        candidate = os.path.join(target_dir, base_name)
        counter = 1
        while os.path.exists(candidate):
            candidate = os.path.join(target_dir, f"{stem}_{counter}{ext}")
            counter += 1
        return candidate

    def _download_scan_unique_temp_file_path(self, source_path: str) -> str:
        temp_dir = self._normalized_download_scan_temp_dir()
        os.makedirs(temp_dir, exist_ok=True)
        base_name = os.path.basename(source_path.rstrip(os.sep)) or "download"
        stem, ext = os.path.splitext(base_name)
        candidate = os.path.join(temp_dir, base_name)
        counter = 1
        while os.path.exists(candidate):
            candidate = os.path.join(temp_dir, f"{stem}_{counter}{ext}")
            counter += 1
        return candidate

    def _download_scan_import_file_to_temp(self, source_path: str) -> tuple[str, str]:
        normalized = os.path.abspath(os.path.expanduser(source_path or ""))
        temp_root = os.path.realpath(self._normalized_download_scan_temp_dir())
        source_real = os.path.realpath(normalized)
        if source_real == temp_root or source_real.startswith(temp_root + os.sep):
            return normalized, ""

        destination = self._download_scan_unique_temp_file_path(normalized)
        shutil.copy2(normalized, destination)
        try:
            os.chmod(destination, 0o600)
        except Exception:
            pass
        return destination, normalized

    def _download_scan_maybe_move_clean_file(self, source_path: str) -> str:
        if not source_path or not os.path.isfile(source_path):
            return ""
        temp_root = os.path.realpath(self._normalized_download_scan_temp_dir())
        source_real = os.path.realpath(source_path)
        if not source_real.startswith(temp_root + os.sep) and source_real != temp_root:
            self.log_safe(
                "Download-Scan: Datei bleibt liegen, weil sie nicht im Temp-Ordner liegt."
            )
            return ""
        auto_move = bool(self.download_scan_auto_move_var.get())
        ask_before_move = bool(self.download_scan_ask_before_move_var.get())
        if not auto_move and not ask_before_move:
            return ""

        destination = self._download_scan_unique_destination(source_path)
        should_move = auto_move
        if ask_before_move:
            should_move = self._download_scan_confirm_move(source_path, destination)
        if not should_move:
            return ""

        shutil.move(source_path, destination)
        self.log_safe(f"Download-Scan: Datei verschoben nach {destination}")
        return destination

    def _run_download_scan(self, target_path: str, *, target_kind: str):
        normalized = os.path.abspath(os.path.expanduser(target_path or ""))
        if not normalized:
            messagebox.showinfo(
                "ClamAV Download-Scan",
                "Bitte zuerst eine Datei oder einen Ordner auswählen.",
                parent=self,
            )
            return
        if not os.path.exists(normalized):
            messagebox.showerror(
                "ClamAV Download-Scan",
                f"Der Scan-Pfad wurde nicht gefunden:\n{normalized}",
                parent=self,
            )
            return
        if not self._download_scan_clamav_available():
            self._set_download_scan_status(
                status="🔴 Fund / verdächtig",
                result="ClamAV nicht verfügbar",
                filename=os.path.basename(normalized),
                last_scan=datetime.now().strftime("%d.%m.%Y %H:%M"),
                log_message="Download-Scan nicht möglich: clamscan fehlt.",
            )
            self._update_download_scan_result_text(
                "ClamAV ist lokal nicht verfügbar.\n\n"
                "Benötigt: clamscan\n"
                "Empfehlung: sudo apt install clamav clamav-freshclam"
            )
            return
        if self.security_clamav_running:
            messagebox.showinfo(
                "ClamAV Download-Scan",
                "Es läuft bereits ein anderer ClamAV-Scan.",
                parent=self,
            )
            return

        scan_label = "Ordner" if os.path.isdir(normalized) else "Datei"
        self.security_clamav_running = True
        self._set_download_scan_status(
            status="🟡 ungeprüft",
            result="ClamAV-Scan läuft",
            filename=os.path.basename(normalized),
            last_scan=datetime.now().strftime("%d.%m.%Y %H:%M"),
            log_message=f"Download-Scan gestartet für {normalized}",
        )
        self._update_download_scan_result_text(
            f"ClamAV prüft {scan_label.lower()}...\n\nZiel: {normalized}"
        )

        if os.path.isdir(normalized):
            self._clamav_progress_start()
        else:
            self._clamav_progress_start(expected_files=1)

        def job():
            moved_to = ""
            try:
                if os.path.isdir(normalized):
                    cmd = ["clamscan", "-r", "--infected", normalized]
                    rc, out, cancelled, timed_out, scanned = (
                        self._run_clamscan_with_progress(
                            cmd,
                            timeout=3600,
                            progress_cb=self._clamav_progress_update_safe,
                        )
                    )
                    if scanned:
                        self._clamav_progress_update_safe(scanned)
                else:
                    cmd = ["clamscan", "--infected", normalized]
                    rc, out, cancelled = self._run_clamscan_with_cancel(
                        cmd,
                        timeout=900,
                    )
                    timed_out = False
                    self._clamav_progress_update_safe(1)

                timestamp = datetime.now()
                timestamp_log = timestamp.strftime("%Y-%m-%d %H:%M:%S")
                timestamp_ui = timestamp.strftime("%d.%m.%Y %H:%M")

                if cancelled:
                    self._set_download_scan_status(
                        status="🟡 ungeprüft",
                        result="Scan abgebrochen",
                        filename=os.path.basename(normalized),
                        last_scan=timestamp_ui,
                        log_message=f"Download-Scan abgebrochen: {normalized}",
                    )
                    self._update_download_scan_result_text(
                        "ClamAV-Scan wurde abgebrochen.\n\n" f"Ziel: {normalized}"
                    )
                    return

                if timed_out:
                    self._set_download_scan_status(
                        status="🔴 Fund / verdächtig",
                        result="Scan-Zeitlimit erreicht",
                        filename=os.path.basename(normalized),
                        last_scan=timestamp_ui,
                        log_message=f"Download-Scan Zeitlimit erreicht: {normalized}",
                    )
                    self._update_download_scan_result_text(
                        "ClamAV-Scan wurde wegen Zeitlimit beendet.\n\n"
                        f"Ziel: {normalized}"
                    )
                    return

                infected_count = self._clamav_parse_infected_count(out)
                scanned_files = self._clamav_parse_scanned_files(out)
                if isinstance(scanned_files, int) and scanned_files >= 0:
                    self._clamav_progress_update_safe(scanned_files)

                nonfatal_issue = rc == 2 and (
                    self._clamav_is_nonfatal_scan_issue(out)
                    or self._clamav_parse_scanned_files(out) is not None
                )
                if rc not in (0, 1) and not nonfatal_issue:
                    error_line = self._clamav_extract_error_message(out)
                    self._set_download_scan_status(
                        status="🔴 Fund / verdächtig",
                        result="ClamAV-Fehler",
                        filename=os.path.basename(normalized),
                        last_scan=timestamp_ui,
                        log_message=f"Download-Scan fehlgeschlagen: {error_line or rc}",
                    )
                    self._update_download_scan_result_text(
                        "ClamAV-Scan fehlgeschlagen.\n\n"
                        f"Ziel: {normalized}\n"
                        f"Fehler: {error_line or f'Rückgabecode {rc}'}"
                    )
                    return

                findings = self._clamav_extract_findings(
                    out,
                    scan_type=f"download_scan_{target_kind}",
                    timestamp=timestamp_log,
                )
                self._clamav_replace_open_findings(findings)

                result_text = (
                    "sauber" if infected_count == 0 else f"{infected_count} Fund/Funde"
                )
                if nonfatal_issue and infected_count == 0:
                    result_text = "sauber (mit Zugriffswarnungen)"

                report_lines = [
                    "NetMon Download Scan / ClamAV",
                    f"Zeit: {timestamp_log}",
                    f"Zieltyp: {target_kind}",
                    f"Ziel: {normalized}",
                    f"Scanned files: {scanned_files if scanned_files is not None else '-'}",
                    f"Ergebnis: {result_text}",
                ]
                if findings:
                    report_lines.append("Funde:")
                    report_lines.extend(
                        [
                            f"- {item.get('path', '-')}: {item.get('signature', '-')}"
                            for item in findings
                        ]
                    )
                else:
                    report_lines.append("Funde: keine")
                if out.strip():
                    report_lines.extend(["", "ClamAV-Ausgabe:", out.strip()])

                report_path = self._download_scan_write_report(
                    target_kind,
                    "\n".join(report_lines),
                )

                if infected_count == 0 and os.path.isfile(normalized):
                    try:
                        moved_to = self._download_scan_maybe_move_clean_file(normalized)
                    except Exception as exc:
                        self.log_safe(
                            f"Download-Scan: Verschieben nach sauberem Scan fehlgeschlagen: {exc}"
                        )

                status_icon = (
                    "🟢 sauber" if infected_count == 0 else "🔴 Fund / verdächtig"
                )
                summary = "Sauber" if infected_count == 0 else f"Fund: {infected_count}"
                if nonfatal_issue and infected_count == 0:
                    summary = "Sauber mit Warnungen"
                if moved_to:
                    summary += " und verschoben"

                result_lines = [
                    f"{scan_label} mit ClamAV geprüft.",
                    "",
                    f"{scan_label}: {normalized}",
                    f"Scanzeit: {timestamp_log}",
                    f"Ergebnis: {result_text}",
                ]
                if findings:
                    result_lines.append("Fundname:")
                    result_lines.extend(
                        [f"- {item.get('signature', '-')}" for item in findings]
                    )
                if moved_to:
                    result_lines.extend(["", f"Verschoben nach: {moved_to}"])
                if report_path:
                    result_lines.extend(["", f"Bericht: {report_path}"])

                self._set_download_scan_status(
                    status=status_icon,
                    result=summary,
                    filename=os.path.basename(normalized),
                    last_scan=timestamp_ui,
                    log_message=f"Download-Scan abgeschlossen: {normalized} | {summary}",
                )
                self._update_download_scan_result_text("\n".join(result_lines))
            finally:
                self.security_clamav_running = False
                self._clamav_progress_finish_safe()

        threading.Thread(target=job, daemon=True).start()

    def scan_download_scan_temp_folder(self):
        target = self._normalized_download_scan_temp_dir()
        if not os.path.isdir(target):
            self.create_download_scan_temp_folder()
        self._run_download_scan(target, target_kind="temp_folder")

    def scan_selected_download_scan_file(self):
        selected = str(self.download_scan_selected_file or "").strip()
        if not selected:
            messagebox.showinfo(
                "ClamAV Download-Scan",
                "Bitte zuerst eine Datei auswählen.",
                parent=self,
            )
            return
        self._run_download_scan(selected, target_kind="file")

    def update_startup_vpn_profile_options(self):
        combo = self.__dict__.get("start_vpn_profile_combo")
        value_var = self.__dict__.get("var_start_vpn_profile")
        profiles = list(self.__dict__.get("wg_profiles", []) or [])
        current = ""
        if value_var is not None:
            try:
                current = str(value_var.get() or "").strip()
            except Exception:
                current = ""
        values = list(profiles)
        if current and current not in values:
            values.insert(0, current)
        if combo is not None:
            try:
                combo["values"] = values
            except Exception:
                pass
        self.on_start_network_mode_changed()

    def on_start_network_mode_changed(self):
        combo = self.__dict__.get("start_vpn_profile_combo")
        killswitch_cb = self.__dict__.get("cb_start_killswitch")
        dot_cb = self.__dict__.get("cb_start_dot")
        killswitch_var = self.__dict__.get("var_start_killswitch")
        dot_var = self.__dict__.get("var_start_dot")
        if killswitch_var is not None:
            try:
                killswitch_var.set(False)
            except Exception:
                pass
        if dot_var is not None:
            try:
                dot_var.set(False)
            except Exception:
                pass
        if combo is not None:
            try:
                combo.configure(state="disabled")
            except Exception:
                pass
        if killswitch_cb is not None:
            try:
                killswitch_cb.configure(state="disabled")
            except Exception:
                pass
        if dot_cb is not None:
            try:
                dot_cb.configure(state="disabled")
            except Exception:
                pass

    def apply_startup_settings(self):
        startup_theme = (
            str(
                self.settings.get("theme", self._preferred_theme_name or "light")
                or "light"
            )
            .strip()
            .lower()
            or "light"
        )
        self.apply_theme(
            self._normalize_theme_name(startup_theme),
            log_change=False,
            persist=False,
        )

        if self.settings.get("auto_log_clear", False):
            try:
                self.clear_log()
            except Exception:
                pass

        if self.settings.get("dns_guard_enabled", True):
            self.after(50, lambda: self.set_dns_guard_enabled(True))

        if self.settings.get("start_security_monitoring", False):
            self.after(150, self.security_start_monitoring)

        sudo_ready = check_sudo_nopasswd()

        ufw_logging_default = (
            str(self.settings.get("ufw_logging_default", "keep") or "keep")
            .strip()
            .lower()
        )
        if ufw_logging_default in {"off", "low", "high"}:
            if sudo_ready:
                self.after(
                    2000,
                    lambda level=ufw_logging_default: self.set_ufw_logging(level),
                )
            else:
                self.log_safe(
                    "Startup: UFW-Logging-Default übersprungen (sudo -n nicht verfügbar)."
                )

    def restart_netmon_with_network_reset(self):
        if not messagebox.askyesno(
            self.tr("netmon_restart_network_title", "NetMon Neustart"),
            self.tr(
                "netmon_restart_network_message",
                "NetMon wird neu gestartet.\n\n"
                "Zusätzlich werden systemd-resolved und NetworkManager neu gestartet.\n"
                "Die Netzwerkverbindung kann kurz abbrechen.\n\n"
                "Fortfahren?",
            ),
            parent=self,
        ):
            self.log_safe("NetMon Neustart + Netzwerk reset abgebrochen.")
            return False

        if not self.ensure_sudo_session("NetMon Neustart + Netzwerk reset"):
            return False

        def worker():
            if not self._try_begin_network_operation(
                "NetMon Neustart + Netzwerk reset"
            ):
                return
            try:
                self.log_safe("NetMon Neustart: Netzwerk-/Resolver-Reset gestartet...")

                commands = [
                    ["sudo", "-n", "systemctl", "restart", "systemd-resolved"],
                    ["sudo", "-n", "systemctl", "restart", "NetworkManager"],
                ]

                for cmd in commands:
                    rc, out = run_cmd(cmd, timeout=20)
                    self.log_safe(f"$ {' '.join(cmd)}")
                    if out:
                        self.log_safe(out)
                    if rc != 0:
                        self.log_safe(f"Warnung: Befehl fehlgeschlagen rc={rc}")

                self.log_safe("NetMon Neustart: DNS-Status wird neu geprüft...")
                dns_cmd = ["resolvectl", "status"]
                rc_dns, out_dns = run_cmd(dns_cmd, timeout=10)
                self.log_safe(f"$ {' '.join(dns_cmd)}")
                if out_dns:
                    self.log_safe(out_dns)
                if rc_dns != 0:
                    self.log_safe(
                        f"Warnung: DNS-Status konnte nicht gelesen werden rc={rc_dns}"
                    )

                self.log_safe("NetMon Neustart: kurzer Stabilisierungspuffer...")
                time.sleep(2)
                self.after(0, self.restart_netmon_process)
            finally:
                self._end_network_operation()

        self.run_async(worker, job_name="NetMon Neustart + Netzwerk reset")
        return True

    def reset_network_stack(self):
        if not messagebox.askyesno(
            self.tr("network_reset_title", "Netzwerkreset"),
            self.tr(
                "network_reset_message",
                "NetMon setzt jetzt WireGuard, systemd-resolved und NetworkManager zurück.\n\n"
                "Die Netzwerkverbindung kann kurz unterbrochen werden.\n\n"
                "Fortfahren?",
            ),
            parent=self,
        ):
            self.log_safe("Netzwerkreset abgebrochen.")
            return False

        if not self.ensure_sudo_session("Netzwerkreset"):
            return False

        def worker():
            if not self._try_begin_network_operation("Netzwerkreset"):
                return
            try:
                self.log_safe("Netzwerkreset gestartet...")
                cleanup_ok = self.cleanup_wireguard_interfaces()
                if not cleanup_ok:
                    self.log_safe(
                        "Netzwerkreset: WG Cleanup war nicht vollständig. Dienste werden trotzdem neu gestartet."
                    )

                commands = [
                    (
                        "Netzwerkreset: systemd-resolved restart",
                        ["sudo", "-n", "systemctl", "restart", "systemd-resolved"],
                        30,
                    ),
                    (
                        "Netzwerkreset: NetworkManager restart",
                        ["sudo", "-n", "systemctl", "restart", "NetworkManager"],
                        30,
                    ),
                ]
                for message, cmd, timeout in commands:
                    self.log_safe(message)
                    rc, out = run_cmd(cmd, timeout=timeout)
                    self.log_network_debug(f"[DEBUG] NET CMD -> {' '.join(cmd)}")
                    self.log_network_debug(f"[DEBUG] NET RC -> {rc}")
                    self.log_network_debug(
                        f"[DEBUG] NET OUT -> {(out or '').strip() or '-'}"
                    )
                    if rc != 0:
                        self.log_safe(
                            f"Warnung: {' '.join(cmd)} fehlgeschlagen (rc={rc})"
                        )
                        if out:
                            self.log_safe((out or "").strip())

                time.sleep(3)
                self.after(0, self.refresh_after_network_reset)
            finally:
                self._end_network_operation()

        self.run_async(worker, job_name="Netzwerkreset")
        return True

    def refresh_after_network_reset(self):
        self.log_safe("Netzwerkreset abgeschlossen. Aktualisiere Status...")
        try:
            self.refresh_safe()
        except Exception:
            pass

        try:
            self.resolved_status_async()
        except Exception:
            pass

        try:
            self.update_vpn_status_text()
        except Exception:
            pass

    def restart_netmon_only(self):
        if not messagebox.askyesno(
            self.tr("netmon_restart_only_title", "NetMon Neustart"),
            self.tr(
                "netmon_restart_only_message",
                "NetMon jetzt neu starten?",
            ),
            parent=self,
        ):
            self.log_safe("NetMon Neustart abgebrochen.")
            return False

        self.restart_netmon_process()
        return True

    def restart_netmon_process(self):
        try:
            self.log_safe("NetMon wird neu gestartet...")
        except Exception:
            pass

        try:
            self.stop_radio()
        except Exception:
            pass

        try:
            release_netmon_instance_lock()
        except Exception:
            pass

        python = sys.executable or shutil.which("python3") or "python3"
        current_argv = [arg for arg in sys.argv if arg is not None]
        if current_argv and current_argv[0]:
            argv = [python] + current_argv
        else:
            argv = [python, "-m", "netmon"]

        try:
            self.destroy()
        except Exception:
            pass

        os.execv(python, argv)

    def _read_text_widget_content(self, widget_name: str) -> str:
        widget = self.__dict__.get(widget_name)
        if widget is None:
            return ""
        try:
            return widget.get("1.0", "end").strip()
        except Exception:
            return ""

    def _selected_security_systemcheck_specs(self):
        specs = [
            {
                "enabled": bool(self.var_systemcheck_security_summary.get()),
                "title": "Security Monitoring Analyse",
                "runner": None,
                "collector": self._collect_security_summary_for_systemcheck,
                "wait": None,
            },
            {
                "enabled": bool(self.var_systemcheck_startup_guard.get()),
                "title": "Startup Guard Analyse",
                "runner": (
                    lambda: (
                        security_audit_controller.startup_guard_check(self)
                        if security_audit_controller is not None
                        else None
                    )
                ),
                "collector": self._collect_startup_guard_for_systemcheck,
                "wait": lambda: bool(getattr(self, "startup_guard_running", False)),
            },
            {
                "enabled": bool(self.var_systemcheck_path_guard.get()),
                "title": "PATH Guard Analyse",
                "runner": (
                    lambda: (
                        security_audit_controller.run_path_guard_check(self)
                        if security_audit_controller is not None
                        else None
                    )
                ),
                "collector": self._collect_path_guard_for_systemcheck,
                "wait": None,
            },
            {
                "enabled": bool(self.var_systemcheck_process_guard.get()),
                "title": "Process Guard Analyse",
                "runner": (
                    lambda: (
                        process_guard_controller.run_process_guard_check(self)
                        if process_guard_controller is not None
                        else None
                    )
                ),
                "collector": self._collect_process_guard_for_systemcheck,
                "wait": None,
            },
            {
                "enabled": bool(self.var_systemcheck_lynis.get()),
                "title": "Lynis Probleme Analyse",
                "runner": (
                    lambda: (
                        security_audit_controller.run_lynis_quick(self)
                        if security_audit_controller is not None
                        else None
                    )
                ),
                "collector": self._collect_lynis_for_systemcheck,
                "wait": lambda: bool(getattr(self, "lynis_running", False)),
            },
            {
                "enabled": bool(self.var_systemcheck_rkhunter.get()),
                "title": "rkhunter Analyse",
                "runner": self.rkhunter_scan_async,
                "collector": self._collect_rkhunter_for_systemcheck,
                "wait": lambda: bool(
                    getattr(self, "rkhunter_running", False)
                    or getattr(self, "rkhunter_updating", False)
                ),
                "availability": self._is_rkhunter_available_for_chad_systemcheck,
                "unavailable_text": self._missing_rkhunter_for_chad_systemcheck_message,
            },
            {
                "enabled": bool(self.var_systemcheck_clamav.get()),
                "title": "ClamAV Analyse",
                "runner": self.security_clamav_quickscan_async,
                "collector": self._collect_clamav_for_systemcheck,
                "wait": lambda: bool(getattr(self, "security_clamav_running", False)),
                "availability": self._is_clamav_available_for_chad_systemcheck,
                "unavailable_text": self._missing_clamav_for_chad_systemcheck_message,
            },
        ]
        return [spec for spec in specs if spec.get("enabled")]

    def _collect_security_summary_for_systemcheck(self) -> str:
        if security_monitoring_controller is not None:
            try:
                return security_monitoring_controller.build_security_chad_summary(self)
            except Exception:
                pass
        return "Keine Security-Zusammenfassung verfügbar."

    def _collect_startup_guard_for_systemcheck(self) -> str:
        result = getattr(self, "startup_guard_last_result", None) or {}
        if result and security_audit_controller is not None:
            try:
                count = len(getattr(self, "startup_guard_visible_entries", []) or [])
                return security_audit_controller.render_startup_guard_result(
                    self,
                    result,
                    count,
                )
            except Exception:
                pass
        text = self._read_text_widget_content("startup_guard_details_text")
        if text:
            return text
        return str(
            self.startup_guard_status_var.get()
            or "Startup Guard ohne Ergebnis beendet."
        )

    def _collect_path_guard_for_systemcheck(self) -> str:
        result = getattr(self, "path_guard_last_result", None)
        if result and security_audit_controller is not None:
            try:
                return security_audit_controller.format_path_guard_result(result)
            except Exception:
                pass
        return str(
            self.path_guard_status_var.get() or "PATH Guard ohne Ergebnis beendet."
        )

    def _collect_process_guard_for_systemcheck(self) -> str:
        result = getattr(self, "process_guard_last_result", None)
        if result and process_guard_controller is not None:
            try:
                return process_guard_controller.format_process_guard_result(result)
            except Exception:
                pass
        text = self._read_text_widget_content("process_guard_detail")
        if text:
            return text
        return str(
            self.process_guard_status_var.get()
            or "Process Guard ohne Ergebnis beendet."
        )

    def _collect_lynis_for_systemcheck(self) -> str:
        text = str(getattr(self, "lynis_last_output", "") or "").strip()
        if text and security_audit_controller is not None:
            try:
                filtered = (
                    security_audit_controller.extract_lynis_issues_and_recommendations(
                        text,
                        normalize_output_fn=normalize_lynis_output,
                    )
                )
                if filtered.strip():
                    return filtered
            except Exception:
                pass
        if text:
            return text
        widget_text = self._read_text_widget_content("lynis_text")
        if widget_text:
            return widget_text
        return str(self.lynis_summary_var.get() or "Lynis ohne Ergebnis beendet.")

    def _collect_rkhunter_for_systemcheck(self) -> str:
        text = self._read_text_widget_content("rkhunter_text")
        if text:
            return text
        return str(self.rkhunter_summary_var.get() or "rkhunter ohne Ergebnis beendet.")

    def _collect_clamav_for_systemcheck(self) -> str:
        snapshot = str(
            getattr(self, "security_clamav_last_systemcheck_text", "") or ""
        ).strip()
        if snapshot:
            return snapshot
        text = self._read_text_widget_content("clamav_output_text")
        if text:
            return text
        return "\n".join(
            [
                "=== ClamAV ===",
                f"Status: {self.clamav_status_var.get()}",
                f"Signaturen: {self.clamav_signatures_var.get()}",
                f"Letzter Scan: {self.clamav_last_scan_var.get()}",
                f"Ziel: {self.clamav_last_target_var.get()}",
                f"Funde: {self.clamav_findings_var.get()}",
                f"Ergebnis: {self.clamav_result_var.get()}",
            ]
        )

