    def apply_chad_profile(self):
        profile = str(self.chad_profile_var.get() or "custom").strip().lower()
        preset = self._chad_profile_presets().get(profile)
        if preset is None:
            try:
                self.chad_analysis_status_var.set(
                    f"Chad-Profil aktiv: {self._format_chad_profile_label(profile)}"
                )
            except Exception:
                pass
            return

        self._applying_chad_profile = True
        try:
            self.chad_analysis_mode_var.set(str(preset["analysis_mode"]))
            filters = preset["filters"]
            self.chad_filter_relevant_var.set(bool(filters["relevant"]))
            self.chad_filter_critical_var.set(bool(filters["critical"]))
            self.chad_filter_recommendations_var.set(bool(filters["recommendations"]))
            self.chad_filter_beginner_var.set(bool(filters["beginner"]))
            self.chad_filter_rawdata_var.set(bool(filters["rawdata"]))
            self.chad_filter_technical_var.set(bool(filters["technical"]))
            self.chad_filter_hide_normal_services_var.set(
                bool(filters["hide_normal_services"])
            )
            self.chad_filter_ignore_harmless_processes_var.set(
                bool(filters["ignore_harmless_processes"])
            )
            self.chad_filter_ignore_dev_environment_var.set(
                bool(filters["ignore_dev_environment"])
            )

            focuses = preset["focuses"]
            self.chad_focus_security_var.set(bool(focuses["security"]))
            self.chad_focus_dns_var.set(bool(focuses["dns"]))
            self.chad_focus_network_var.set(bool(focuses["network"]))
            self.chad_focus_process_var.set(bool(focuses["process"]))
            self.chad_focus_firewall_var.set(bool(focuses["firewall"]))
            self.chad_focus_performance_var.set(bool(focuses["performance"]))
            self.chad_focus_optimization_var.set(bool(focuses["optimization"]))
            self.chad_focus_rootkit_var.set(bool(focuses["rootkit"]))

            answers = preset["answers"]
            self.chad_answer_short_var.set(bool(answers["short"]))
            self.chad_answer_detailed_var.set(bool(answers["detailed"]))
            self.chad_answer_step_var.set(bool(answers["step"]))
            self.chad_answer_linux_help_var.set(bool(answers["linux_help"]))
            self.chad_answer_risk_var.set(bool(answers["risk"]))
            self.chad_answer_recommendations_var.set(bool(answers["recommendations"]))

            self.chad_model_var.set(str(preset.get("model") or "gpt-4.1-mini"))
            self.apply_chad_model_selection()
            self.chad_systemcheck_profile_var.set(str(preset["systemcheck_profile"]))
            self.apply_chad_systemcheck_profile()
        finally:
            self._applying_chad_profile = False

        self._update_chad_controls_state()
        try:
            self.chad_analysis_status_var.set(
                f"Chad-Profil geladen: {self._format_chad_profile_label(profile)}"
            )
        except Exception:
            pass

