    def _build_two_col_toggle_grid(
        self, parent, specs, *, is_radio=False, variable=None, row_gap=2
    ):
        outer = ttk.Frame(parent)
        outer.pack(fill="x")
        outer.columnconfigure(0, weight=1, uniform="chad_settings_cols")
        outer.columnconfigure(1, weight=1, uniform="chad_settings_cols")

        left_col = ttk.Frame(outer)
        left_col.grid(row=0, column=0, sticky="nw", padx=(0, 18))
        right_col = ttk.Frame(outer)
        right_col.grid(row=0, column=1, sticky="nw")

        left_count = (len(specs) + 1) // 2
        for index, spec in enumerate(specs):
            column_parent = left_col if index < left_count else right_col
            row = index if index < left_count else index - left_count
            label, var_or_value, widget_command = spec
            kwargs = {"text": label}
            if is_radio:
                kwargs["variable"] = variable
                kwargs["value"] = var_or_value
                kwargs["command"] = widget_command
                widget = ttk.Radiobutton(column_parent, **kwargs)
            else:
                kwargs["variable"] = var_or_value
                kwargs["command"] = widget_command
                widget = ttk.Checkbutton(column_parent, **kwargs)
            widget.grid(
                row=row,
                column=0,
                sticky="w",
                pady=(0 if row == 0 else row_gap, 0),
            )
        return outer

    def build_security_systemcheck_panel(
        self,
        parent,
        *,
        wraplength=520,
        pady=(0, 6),
        compact=False,
        geometry="pack",
        grid_row=0,
        grid_column=0,
        grid_sticky="new",
    ):
        live_systemcheck = ttk.LabelFrame(
            parent,
            text=self.tr("settings_security_systemcheck", "Security Systemcheck"),
            padding=8,
        )
        if geometry == "grid":
            live_systemcheck.grid(
                row=grid_row,
                column=grid_column,
                sticky=grid_sticky,
                pady=pady,
            )
        else:
            live_systemcheck.pack(fill="x", pady=pady)
        check_specs = [
            (
                self.tr(
                    "settings_systemcheck_security_summary",
                    "Security Monitoring Zusammenfassung",
                ),
                self.var_systemcheck_security_summary,
                self.mark_chad_systemcheck_profile_custom,
            ),
            (
                self.tr("settings_systemcheck_startup_guard", "Startup Guard"),
                self.var_systemcheck_startup_guard,
                self.mark_chad_systemcheck_profile_custom,
            ),
            (
                self.tr("settings_systemcheck_path_guard", "PATH Guard"),
                self.var_systemcheck_path_guard,
                self.mark_chad_systemcheck_profile_custom,
            ),
            (
                self.tr("settings_systemcheck_process_guard", "Process Guard"),
                self.var_systemcheck_process_guard,
                self.mark_chad_systemcheck_profile_custom,
            ),
            (
                self.tr("settings_systemcheck_lynis", "Lynis Quick Scan"),
                self.var_systemcheck_lynis,
                self.mark_chad_systemcheck_profile_custom,
            ),
            (
                self.tr("settings_systemcheck_rkhunter", "rkhunter Scan"),
                self.var_systemcheck_rkhunter,
                self.mark_chad_systemcheck_profile_custom,
            ),
            (
                self.tr("settings_systemcheck_clamav", "ClamAV Schnellscan"),
                self.var_systemcheck_clamav,
                self.mark_chad_systemcheck_profile_custom,
            ),
        ]
        if compact:
            check_specs = [
                (
                    "Security Monitoring",
                    self.var_systemcheck_security_summary,
                    self.mark_chad_systemcheck_profile_custom,
                ),
                (
                    "Startup Guard",
                    self.var_systemcheck_startup_guard,
                    self.mark_chad_systemcheck_profile_custom,
                ),
                (
                    "PATH Guard",
                    self.var_systemcheck_path_guard,
                    self.mark_chad_systemcheck_profile_custom,
                ),
                (
                    "Process Guard",
                    self.var_systemcheck_process_guard,
                    self.mark_chad_systemcheck_profile_custom,
                ),
                (
                    "Lynis",
                    self.var_systemcheck_lynis,
                    self.mark_chad_systemcheck_profile_custom,
                ),
                (
                    "rkhunter",
                    self.var_systemcheck_rkhunter,
                    self.mark_chad_systemcheck_profile_custom,
                ),
                (
                    "ClamAV Schnellscan",
                    self.var_systemcheck_clamav,
                    self.mark_chad_systemcheck_profile_custom,
                ),
            ]
        self._build_two_col_toggle_grid(
            live_systemcheck,
            check_specs,
            row_gap=1 if compact else 2,
        )
        ttk.Label(
            live_systemcheck,
            textvariable=self.chad_security_tools_status_var,
            justify="left",
        ).pack(anchor="w", pady=(8, 0))
        ttk.Label(
            live_systemcheck,
            text=self.tr(
                "settings_systemcheck_hint",
                "Ausgewählte Prüfungen laufen nacheinander und werden direkt an Chad zur Analyse gesendet.",
            ),
            justify="left",
            wraplength=wraplength,
        ).pack(anchor="w", pady=(4, 0))
        self.refresh_chad_security_tools_status()
        ttk.Button(
            live_systemcheck,
            text=self.tr("settings_systemcheck_run", "Systemcheck ausführen"),
            command=self.run_selected_security_systemcheck,
        ).pack(anchor="w", pady=(8, 0))
        ttk.Label(
            live_systemcheck,
            textvariable=self.security_systemcheck_status_var,
            justify="left",
            wraplength=wraplength,
        ).pack(anchor="w", pady=(8, 0))
        return live_systemcheck

