    def _cancel_active_context_menu_timeout(self):
        after_id = self.__dict__.get("_active_context_menu_after_id")
        if after_id is None:
            return
        self._active_context_menu_after_id = None
        try:
            self.after_cancel(after_id)
        except Exception:
            pass

    def _close_active_context_menu(self):
        self._cancel_active_context_menu_timeout()
        menu = self.__dict__.get("_active_context_menu")
        self._active_context_menu = None
        if menu is None:
            return
        try:
            menu.unpost()
        except Exception:
            pass
        try:
            menu.grab_release()
        except Exception:
            pass

    def _schedule_active_context_menu_close(self):
        self._cancel_active_context_menu_timeout()
        self._active_context_menu_after_id = self.after(
            10000, self._close_active_context_menu
        )

    def _deactivate_chad_analysis_scroll(self, event=None):
        chad_output = self.__dict__.get("chad_analysis_text")
        if chad_output is None:
            return

        try:
            current_focus = self.focus_get()
        except Exception:
            current_focus = None
        if current_focus != chad_output:
            return

        widget = getattr(event, "widget", None)
        if widget == chad_output:
            return

        chad_input = self.__dict__.get("chad_chat_input")
        if widget == chad_input:
            return

        try:
            widget_class = widget.winfo_class() if widget is not None else ""
        except Exception:
            widget_class = ""
        if widget_class in {
            "Text",
            "Entry",
            "TEntry",
            "Spinbox",
            "TCombobox",
            "Listbox",
            "Treeview",
        }:
            return

        try:
            self.page_canvas.focus_set()
        except Exception:
            pass

    def _deactivate_local_mousewheel_scroll(self, event=None):
        target_names = tuple(self.__dict__.get("_local_mousewheel_target_names") or ())
        if not target_names:
            return

        try:
            current_focus = self.focus_get()
        except Exception:
            current_focus = None

        tracked_widgets = [
            self.__dict__.get(widget_name)
            for widget_name in target_names
            if self.__dict__.get(widget_name) is not None
        ]
        if current_focus not in tracked_widgets:
            return

        widget = getattr(event, "widget", None)
        if widget in tracked_widgets:
            return

        try:
            widget_class = widget.winfo_class() if widget is not None else ""
        except Exception:
            widget_class = ""
        if widget_class in {
            "Text",
            "Entry",
            "TEntry",
            "Spinbox",
            "TCombobox",
            "Listbox",
            "Treeview",
        }:
            return

        try:
            self.page_canvas.focus_set()
        except Exception:
            pass

    def _handle_app_click_for_context_menu(self, event=None):
        self._close_active_context_menu()
        self._deactivate_local_mousewheel_scroll(event)
        self._deactivate_chad_analysis_scroll(event)

    def _show_context_menu(self, menu, event):
        self._close_active_context_menu()
        self._active_context_menu = menu
        self._schedule_active_context_menu_close()
        try:
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            try:
                menu.grab_release()
            except Exception:
                pass
        return "break"

    def _copy_text_widget_selection(self, text_widget, _event=None):
        try:
            selected = text_widget.get("sel.first", "sel.last")
        except Exception:
            return "break"
        if not selected:
            return "break"
        self.clipboard_clear()
        self.clipboard_append(selected)
        return "break"

    def _copy_listbox_selection(self, listbox, _event=None):
        try:
            selection = listbox.curselection()
        except Exception:
            selection = ()
        if not selection:
            return "break"

        lines = []
        for index in selection:
            try:
                value = listbox.get(index)
            except Exception:
                value = ""
            value = str(value or "").strip()
            if value:
                lines.append(value)

        if not lines:
            return "break"

        self.clipboard_clear()
        self.clipboard_append("\n".join(lines))
        return "break"

    def get_treeview_selection_text(self, treeview) -> str:
        try:
            selection = tuple(treeview.selection())
        except Exception:
            selection = ()
        if not selection:
            return ""

        try:
            columns = tuple(treeview["columns"])
        except Exception:
            columns = ()

        headings = []
        for column in columns:
            try:
                heading = treeview.heading(column, "text")
            except Exception:
                heading = ""
            headings.append(str(heading or column))

        lines = []
        if headings:
            lines.append("\t".join(headings))

        for item_id in selection:
            try:
                values = treeview.item(item_id, "values")
            except Exception:
                values = ()
            row = [str(value or "").strip() for value in values]
            if row:
                lines.append("\t".join(row))

        return "\n".join(lines).strip()

    def _copy_treeview_selection(self, treeview, _event=None):
        text = self.get_treeview_selection_text(treeview)
        if not text:
            return "break"
        self.clipboard_clear()
        self.clipboard_append(text)
        return "break"

    def _paste_text_widget_clipboard(self, text_widget, _event=None):
        try:
            if str(text_widget.cget("state")) == "disabled":
                return "break"
        except Exception:
            pass

        try:
            text_widget.focus_force()
        except Exception:
            pass

        try:
            text_widget.event_generate("<<Paste>>")
            return "break"
        except Exception:
            pass

        try:
            pasted = self.clipboard_get()
        except Exception:
            pasted = ""

        if pasted:
            try:
                text_widget.insert("insert", pasted)
            except Exception:
                pass
        return "break"

    def _paste_entry_widget_clipboard(self, entry_widget, _event=None):
        try:
            state = str(entry_widget.cget("state"))
            if state in {"disabled", "readonly"}:
                return "break"
        except Exception:
            pass

        try:
            entry_widget.focus_force()
        except Exception:
            pass

        try:
            entry_widget.event_generate("<<Paste>>")
            return "break"
        except Exception:
            pass

        try:
            pasted = self.clipboard_get()
        except Exception:
            pasted = ""

        if pasted:
            try:
                entry_widget.insert("insert", pasted)
            except Exception:
                pass
        return "break"

    def attach_selection_copy_shortcuts(self, widget, kind: str):
        if widget is None:
            return

        attached = self.__dict__.setdefault("_selection_copy_shortcuts_attached", set())
        widget_id = str(widget)
        if widget_id in attached:
            return
        attached.add(widget_id)

        if kind == "text":

            def handler(event):
                return self._copy_text_widget_selection(widget, event)

        elif kind == "listbox":

            def handler(event):
                return self._copy_listbox_selection(widget, event)

        elif kind == "treeview":

            def handler(event):
                return self._copy_treeview_selection(widget, event)

        else:
            return

        widget.bind("<Control-c>", handler, add="+")
        widget.bind("<Control-C>", handler, add="+")
        widget.bind("<Control-Insert>", handler, add="+")
        if kind == "text":
            widget.bind(
                "<Control-v>",
                lambda event: self._paste_text_widget_clipboard(widget, event),
                add="+",
            )
            widget.bind(
                "<Control-V>",
                lambda event: self._paste_text_widget_clipboard(widget, event),
                add="+",
            )
            widget.bind(
                "<Shift-Insert>",
                lambda event: self._paste_text_widget_clipboard(widget, event),
                add="+",
            )

    def attach_entry_edit_shortcuts(self, entry_widget):
        if entry_widget is None:
            return

        attached = self.__dict__.setdefault("_selection_copy_shortcuts_attached", set())
        widget_id = str(entry_widget)
        if widget_id in attached:
            return
        attached.add(widget_id)

        def copy_handler(_event=None):
            try:
                selected = entry_widget.selection_get()
            except Exception:
                return "break"
            if not selected:
                return "break"
            self.clipboard_clear()
            self.clipboard_append(selected)
            return "break"

        def paste_handler(event):
            return self._paste_entry_widget_clipboard(entry_widget, event)

        entry_widget.bind("<Control-c>", copy_handler, add="+")
        entry_widget.bind("<Control-C>", copy_handler, add="+")
        entry_widget.bind("<Control-Insert>", copy_handler, add="+")
        entry_widget.bind("<Control-v>", paste_handler, add="+")
        entry_widget.bind("<Control-V>", paste_handler, add="+")
        entry_widget.bind("<Shift-Insert>", paste_handler, add="+")

    def safe_attach_entry_edit_shortcuts(self, widget_name: str):
        widget = self.__dict__.get(widget_name)
        if widget is None:
            return

        try:
            self.attach_entry_edit_shortcuts(widget)
        except Exception as exc:
            try:
                self.log(
                    f"[WARN] Edit-Shortcuts für {widget_name} konnten nicht gesetzt werden: {exc}"
                )
            except Exception:
                pass

    def safe_attach_selection_copy_shortcuts(self, widget_name: str, kind: str):
        widget = self.__dict__.get(widget_name)
        if widget is None:
            return

        try:
            self.attach_selection_copy_shortcuts(widget, kind)
        except Exception as exc:
            try:
                self.log(
                    f"[WARN] Kopier-Shortcuts für {widget_name} konnten nicht gesetzt werden: {exc}"
                )
            except Exception:
                pass

    def attach_text_context_menu(self, widget):
        if widget is None:
            return

        attached = self.__dict__.setdefault("_text_context_menu_attached", set())
        widget_id = str(widget)
        if widget_id in attached:
            return
        attached.add(widget_id)

        menu = tk.Menu(widget, tearoff=0)

        def _is_disabled():
            try:
                return str(widget.cget("state")) == "disabled"
            except Exception:
                return False

        def _is_readonly():
            try:
                return str(widget.cget("state")) == "readonly"
            except Exception:
                return False

        def _run_virtual_event(sequence):
            try:
                widget.event_generate(sequence)
                return True
            except Exception:
                return False

        def cut_text():
            if _is_disabled() or _is_readonly():
                return
            _run_virtual_event("<<Cut>>")

        def copy_text():
            if hasattr(widget, "tag_ranges"):
                try:
                    selected = widget.get("sel.first", "sel.last")
                except Exception:
                    selected = ""
            else:
                try:
                    selected = widget.selection_get()
                except Exception:
                    selected = ""

            if selected:
                try:
                    self.clipboard_clear()
                    self.clipboard_append(selected)
                    return
                except Exception:
                    pass

            _run_virtual_event("<<Copy>>")

        def paste_text():
            if _is_disabled() or _is_readonly():
                return

            if _run_virtual_event("<<Paste>>"):
                return

            if hasattr(widget, "tag_ranges"):
                self._paste_text_widget_clipboard(widget)
            else:
                self._paste_entry_widget_clipboard(widget)

        def select_all():
            if _run_virtual_event("<<SelectAll>>"):
                return

            if hasattr(widget, "tag_ranges"):
                try:
                    widget.tag_add("sel", "1.0", "end")
                    widget.mark_set("insert", "1.0")
                    widget.see("insert")
                except Exception:
                    pass
                return

            try:
                widget.selection_range(0, "end")
                widget.icursor("end")
            except Exception:
                pass

        menu.add_command(label="Ausschneiden", command=cut_text)
        menu.add_command(label="Kopieren", command=copy_text)
        menu.add_command(label="Einfügen", command=paste_text)
        menu.add_separator()
        menu.add_command(label="Alles markieren", command=select_all)

        def show_menu(event):
            try:
                widget.focus_set()
            except Exception:
                pass
            return self._show_context_menu(menu, event)

        widget.bind("<Button-3>", show_menu, add="+")
        widget._netmon_context_menu = menu

    def attach_copy_paste_context_menu(self, widget):
        if widget is None:
            return

        attached = self.__dict__.setdefault("_copy_paste_context_menu_attached", set())
        widget_id = str(widget)
        if widget_id in attached:
            return
        attached.add(widget_id)

        menu = tk.Menu(widget, tearoff=0)

        def _is_disabled():
            try:
                return str(widget.cget("state")) == "disabled"
            except Exception:
                return False

        def _is_readonly():
            try:
                return str(widget.cget("state")) == "readonly"
            except Exception:
                return False

        def _run_virtual_event(sequence):
            try:
                widget.event_generate(sequence)
                return True
            except Exception:
                return False

        def copy_text():
            if hasattr(widget, "tag_ranges"):
                try:
                    selected = widget.get("sel.first", "sel.last")
                except Exception:
                    selected = ""
            else:
                try:
                    selected = widget.selection_get()
                except Exception:
                    selected = ""

            if selected:
                try:
                    self.clipboard_clear()
                    self.clipboard_append(selected)
                    return
                except Exception:
                    pass

            _run_virtual_event("<<Copy>>")

        def paste_text():
            if _is_disabled() or _is_readonly():
                return

            if _run_virtual_event("<<Paste>>"):
                return

            if hasattr(widget, "tag_ranges"):
                self._paste_text_widget_clipboard(widget)
            else:
                self._paste_entry_widget_clipboard(widget)

        menu.add_command(label="Kopieren", command=copy_text)
        menu.add_command(label="Einfügen", command=paste_text)

        def show_menu(event):
            try:
                widget.focus_set()
            except Exception:
                pass
            return self._show_context_menu(menu, event)

        widget.bind("<Button-3>", show_menu, add="+")
        widget._netmon_context_menu = menu

