    def attach_chad_context_menu(self, text_widget, title: str):
        attached = self.__dict__.setdefault("_chad_context_menu_attached", set())
        widget_id = str(text_widget)
        if widget_id in attached:
            return
        attached.add(widget_id)
        self.attach_selection_copy_shortcuts(text_widget, "text")

        menu = tk.Menu(text_widget, tearoff=0)

        def get_selected_text():
            try:
                return text_widget.get("sel.first", "sel.last").strip()
            except Exception:
                return ""

        def copy_selection():
            selected = get_selected_text()
            if not selected:
                return
            self.clipboard_clear()
            self.clipboard_append(selected)

        def paste_from_clipboard():
            try:
                if str(text_widget.cget("state")) == "disabled":
                    return
            except Exception:
                pass

            try:
                text_widget.focus_force()
            except Exception:
                pass

            try:
                text_widget.event_generate("<<Paste>>")
                return
            except Exception:
                pass

            try:
                pasted = self.clipboard_get()
                if pasted:
                    text_widget.insert("insert", pasted)
            except Exception:
                pass

        def select_all():
            try:
                text_widget.tag_add("sel", "1.0", "end")
                text_widget.mark_set("insert", "1.0")
                text_widget.see("insert")
            except Exception:
                pass

        def send_selection_to_chad():
            if not self.is_chad_enabled():
                self._show_chad_activation_required_popup()
                return

            selected = get_selected_text()
            if not selected:
                try:
                    self.chad_analysis_status_var.set(
                        "Keine Auswahl für Chad Analyse markiert."
                    )
                except Exception:
                    pass
                return

            self.prepare_chad_analysis(title, selected)

        def copy_selection_as_prompt():
            selected = get_selected_text()
            if not selected:
                try:
                    self.chad_analysis_status_var.set(
                        "Keine Auswahl zum Kopieren markiert."
                    )
                except Exception:
                    pass
                return

            prompt = self._build_chad_analysis_prompt(title, selected)
            self.clipboard_clear()
            self.clipboard_append(prompt)

            try:
                self.chad_analysis_status_var.set(
                    "Chad-Prompt in Zwischenablage kopiert."
                )
            except Exception:
                pass

        menu.add_command(label="Kopieren", command=copy_selection)
        menu.add_command(label="Einfügen", command=paste_from_clipboard)
        menu.add_command(label="Alles auswählen", command=select_all)
        menu.add_separator()
        menu.add_command(
            label="Auswahl an Chad Analyse senden",
            command=send_selection_to_chad,
        )
        menu.add_command(
            label="Auswahl als Chad-Prompt kopieren",
            command=copy_selection_as_prompt,
        )

        def show_menu(event):
            return self._show_context_menu(menu, event)

        text_widget.bind("<Button-3>", show_menu, add="+")
        text_widget._chad_context_menu = menu

    def safe_attach_chad_context_menu(self, widget_name: str, title: str):
        widget = self.__dict__.get(widget_name)
        if widget is None:
            return

        try:
            self.attach_chad_context_menu(widget, title)
        except Exception as exc:
            try:
                self.log(
                    f"[WARN] Kontextmenü für {widget_name} konnte nicht gesetzt werden: {exc}"
                )
            except Exception:
                pass

    def attach_chad_listbox_context_menu(self, listbox, title: str):
        attached = self.__dict__.setdefault(
            "_chad_listbox_context_menu_attached", set()
        )
        widget_id = str(listbox)
        if widget_id in attached:
            return
        attached.add(widget_id)
        self.attach_selection_copy_shortcuts(listbox, "listbox")

        menu = tk.Menu(listbox, tearoff=0)

        def get_selected_text():
            try:
                selection = listbox.curselection()
            except Exception:
                selection = ()
            if not selection:
                return ""
            lines = []
            for index in selection:
                try:
                    value = listbox.get(index)
                except Exception:
                    value = ""
                value = str(value or "").strip()
                if value:
                    lines.append(value)
            return "\n".join(lines).strip()

        def copy_selection():
            selected = get_selected_text()
            if not selected:
                try:
                    self.chad_analysis_status_var.set(
                        "Keine Auswahl zum Kopieren markiert."
                    )
                except Exception:
                    pass
                return
            self.clipboard_clear()
            self.clipboard_append(selected)

        def paste_from_clipboard():
            try:
                self.chad_analysis_status_var.set(
                    "Einfügen ist in dieser Verlaufsliste nicht verfügbar."
                )
            except Exception:
                pass

        def select_all():
            try:
                size = int(listbox.size())
            except Exception:
                size = 0
            if size <= 0:
                return
            try:
                listbox.selection_clear(0, "end")
                listbox.selection_set(0, "end")
                listbox.activate(0)
            except Exception:
                pass

        def send_selection_to_chad():
            if not self.is_chad_enabled():
                self._show_chad_activation_required_popup()
                return

            selected = get_selected_text()
            if not selected:
                try:
                    self.chad_analysis_status_var.set(
                        "Keine Auswahl für Chad Analyse markiert."
                    )
                except Exception:
                    pass
                return

            self.prepare_chad_analysis(title, selected)

        def copy_selection_as_prompt():
            selected = get_selected_text()
            if not selected:
                try:
                    self.chad_analysis_status_var.set(
                        "Keine Auswahl zum Kopieren markiert."
                    )
                except Exception:
                    pass
                return

            prompt = self._build_chad_analysis_prompt(title, selected)
            self.clipboard_clear()
            self.clipboard_append(prompt)

            try:
                self.chad_analysis_status_var.set(
                    "Chad-Prompt in Zwischenablage kopiert."
                )
            except Exception:
                pass

        menu.add_command(label="Kopieren", command=copy_selection)
        menu.add_command(label="Einfügen", command=paste_from_clipboard)
        menu.add_command(label="Alles auswählen", command=select_all)
        menu.add_separator()
        menu.add_command(
            label="Auswahl an Chad Analyse senden",
            command=send_selection_to_chad,
        )
        menu.add_command(
            label="Auswahl als Chad-Prompt kopieren",
            command=copy_selection_as_prompt,
        )

        def show_menu(event):
            try:
                index = int(listbox.nearest(event.y))
            except Exception:
                index = -1
            if index >= 0:
                try:
                    current_selection = tuple(listbox.curselection())
                except Exception:
                    current_selection = ()
                if index not in current_selection:
                    try:
                        listbox.selection_clear(0, "end")
                        listbox.selection_set(index)
                        listbox.activate(index)
                    except Exception:
                        pass
            return self._show_context_menu(menu, event)

        listbox.bind("<Button-3>", show_menu, add="+")
        listbox._chad_context_menu = menu

