    def wireshark_launch_blocked(self):
        return bool(self.settings.get("wireshark_launch_blocked", False))

    def refresh_wireshark_launch_controls(self):
        dep_status = self.__dict__.get("dep_status", {}) or {}
        wireshark_available = bool(dep_status.get("wireshark", False))
        packet_capture_ready = bool(
            dep_status.get("tshark", False) or dep_status.get("dumpcap", False)
        )
        packet_capture_ui_ready = bool(dep_status.get("ip", False))
        blocked = bool(self.settings.get("wireshark_launch_blocked", False))
        action_buttons = (
            "btn_packet_capture_start",
            "btn_packet_capture_stop",
            "btn_packet_capture_open_wireshark",
            "btn_packet_capture_open_file",
            "btn_packet_capture_info",
        )
        if blocked:
            for name in action_buttons:
                button = self.__dict__.get(name)
                if button is None:
                    continue
                try:
                    button.configure(state="disabled")
                except Exception:
                    pass
            return

        if packet_capture_controller is not None:
            try:
                packet_capture_controller.packet_capture_set_running_state(
                    self,
                    bool(getattr(self, "packet_capture_running", False)),
                )
            except Exception:
                pass

        open_wireshark_button = self.__dict__.get("btn_packet_capture_open_wireshark")
        if open_wireshark_button is not None:
            try:
                open_wireshark_button.configure(
                    state="normal" if wireshark_available else "disabled"
                )
            except Exception:
                pass

        open_file_button = self.__dict__.get("btn_packet_capture_open_file")
        if open_file_button is not None:
            try:
                open_file_button.configure(
                    state="normal" if packet_capture_ready else "disabled"
                )
            except Exception:
                pass

        info_button = self.__dict__.get("btn_packet_capture_info")
        if info_button is not None:
            try:
                info_button.configure(
                    state="normal" if packet_capture_ui_ready else "disabled"
                )
            except Exception:
                pass

    def on_wireshark_launch_block_toggle(self):
        blocked = bool(self.var_wireshark_launch_blocked.get())
        self.settings["wireshark_launch_blocked"] = blocked
        self.refresh_wireshark_launch_controls()
        self.save_settings(log_success=False)
        try:
            self.log(
                "Wireshark-Start in NetMon gesperrt."
                if blocked
                else "Wireshark-Start in NetMon wieder erlaubt."
            )
        except Exception:
            pass

