    def get_startup_guard_analysis_text(self) -> str:
        table = self.__dict__.get("startup_guard_tree")
        if table is None:
            return ""

        selection = list(table.selection())
        target_items = selection or list(table.get_children())
        if not target_items:
            return ""

        visible_entries = list(getattr(self, "startup_guard_visible_entries", []) or [])
        lines = ["=== Startup Guard Auswahl ===", ""]
        appended = 0
        for item in target_items:
            try:
                index = int(table.index(item))
            except Exception:
                continue
            if index < 0 or index >= len(visible_entries):
                continue
            if appended:
                lines.append("")
            lines.append(
                self.format_startup_guard_entry_details(visible_entries[index])
            )
            appended += 1
        return "\n".join(lines).strip()

