    def get_connected_devices_analysis_text(self) -> str:
        table = self.__dict__.get("security_devices_table")
        if table is None:
            return ""

        selection = list(table.selection())
        target_items = selection or list(table.get_children())
        if not target_items:
            return ""

        inventory = list(getattr(self, "connected_devices_inventory", []) or [])
        lines = ["=== Verbundene Geräte Auswahl ===", ""]
        appended = 0
        for item in target_items:
            try:
                index = int(table.index(item))
            except Exception:
                continue
            if index < 0 or index >= len(inventory):
                continue
            device = inventory[index]
            if appended:
                lines.append("")
            lines.extend(
                [
                    f"[{appended + 1}] {device.get('name', 'Unbekannt')}",
                    f"Typ: {device.get('type', 'unknown')}",
                    f"Pfad: {device.get('path', '-')}",
                    f"Kennung: {device.get('sys_name', '-')}",
                    f"Vendor-ID: {device.get('vendor', '-')}",
                    f"Product-ID: {device.get('product', '-')}",
                    f"Bus-Typ: {device.get('bustype', '-')}",
                    f"Phys: {device.get('phys', '-')}",
                    f"Unique-ID: {device.get('uniq', '-')}",
                    "Baseline: "
                    + (
                        "bekannt"
                        if device.get("known_in_baseline")
                        else "neu/nicht in Baseline"
                    ),
                ]
            )
            appended += 1
        return "\n".join(lines).strip()

