    def get_repository_guard_findings_analysis_text(self) -> str:
        table = self.__dict__.get("repository_guard_findings_tree")
        if table is None or repository_guard_controller is None:
            return ""

        selection = list(table.selection())
        target_items = selection or list(table.get_children())
        if not target_items:
            return ""

        visible_findings = list(
            getattr(self, "repository_guard_visible_findings", []) or []
        )
        lines = ["=== Repository Guard Findings Auswahl ===", ""]
        appended = 0
        for item in target_items:
            try:
                index = int(table.index(item))
            except Exception:
                continue
            if index < 0 or index >= len(visible_findings):
                continue
            if appended:
                lines.append("")
            lines.append(
                repository_guard_controller.format_repository_guard_finding_details(
                    self,
                    visible_findings[index],
                )
            )
            appended += 1
        return "\n".join(lines).strip()

