    def _security_query_log_level(self):
        attempts = [
            ["sudo", "-n", "ufw", "status", "verbose"],
            ["ufw", "status", "verbose"],
        ]

        for cmd in attempts:
            try:
                rc, out = run_cmd(cmd, timeout=12)
            except Exception as e:
                self.log(
                    f"Security: UFW-Level-Abfrage fehlgeschlagen (cmd={' '.join(cmd)}): {e}"
                )
                continue

            if rc != 0 or not out:
                continue

            level = self._parse_ufw_logging_level(out)
            if level != "–":
                return level

        return "–"

    def _parse_ufw_logging_level(self, text):
        t = (text or "").lower()

        patterns = [
            (r"logging:\s*(?:on\s*)?\(?high\)?", "HIGH"),
            (r"protokollierung:\s*(?:on|ein)\s*\(?high\)?", "HIGH"),
            (r"protokollierung:\s*(?:on|ein)\s*\(?hoch\)?", "HIGH"),
            (r"logging:\s*(?:on\s*)?\(?medium\)?", "MEDIUM"),
            (r"protokollierung:\s*(?:on|ein)\s*\(?medium\)?", "MEDIUM"),
            (r"protokollierung:\s*(?:on|ein)\s*\(?mittel\)?", "MEDIUM"),
            (r"logging:\s*(?:on\s*)?\(?low\)?", "LOW"),
            (r"protokollierung:\s*(?:on|ein)\s*\(?low\)?", "LOW"),
            (r"protokollierung:\s*(?:on|ein)\s*\(?niedrig\)?", "LOW"),
            (r"logging:\s*off", "OFF"),
            (r"protokollierung:\s*(?:off|aus)", "OFF"),
        ]

        for pattern, level in patterns:
            if re.search(pattern, t, re.IGNORECASE):
                return level

        return "–"

    def get_ufw_logging_level(self):
        return security_monitoring_controller.get_ufw_logging_level(self)

    def refresh_security_log_level(self, log_failures=False):
        level = self._security_query_log_level()
        self.security_log_level = level
        level_var = self.__dict__.get("security_level_var")
        if level_var is not None:
            try:
                level_var.set(f"Logging: {level}")
            except Exception:
                pass
        return level

    def _active_ufw_portscan_ip(self):
        now = time.time()
        for event in reversed(list(self.__dict__.get("security_events", []) or [])):
            if str(event.get("type") or "") != "Portscan-Verdacht":
                continue
            try:
                event_age = now - float(event.get("epoch") or 0.0)
            except (TypeError, ValueError):
                event_age = 999999.0
            if event_age > 120.0:
                continue
            src = str(event.get("src") or "").strip()
            if src:
                return src
        return None

    def update_ufw_logging_light(self):
        level = self._security_query_log_level()
        self.security_log_level = level

        level_var = self.__dict__.get("security_level_var")
        if level_var is not None:
            try:
                level_var.set(f"Logging: {level}")
            except Exception:
                pass

        status_var = self.__dict__.get("ufw_logging_status_var")
        portscan_ip = self._active_ufw_portscan_ip()
        light = self.__dict__.get("l_ufw_log")
        if portscan_ip:
            if status_var is not None:
                try:
                    status_var.set(f"Portscan von IP: {portscan_ip}")
                except Exception:
                    pass
            if light is not None:
                self.set_light(light, "red")
            return

        if status_var is not None:
            try:
                status_var.set(f"UFW Logging: {level}")
            except Exception:
                pass

        color = {
            "OFF": "gray",
            "LOW": "yellow",
            "MEDIUM": "green",
            "HIGH": "green",
        }.get(level, "gray")
        if light is not None:
            self.set_light(light, color)

