    def open_path_in_file_manager(self, path, label="Ordner"):
        target = os.path.abspath(os.path.expanduser(str(path or "").strip()))
        if not target:
            try:
                self.roots_baseline_status_var.set(
                    "Kein Ordnerpfad zum Öffnen verfügbar."
                )
            except Exception:
                pass
            return False
        if not shutil.which("xdg-open"):
            try:
                self.roots_baseline_status_var.set(
                    "Ordner öffnen nicht verfügbar: 'xdg-open' fehlt."
                )
            except Exception:
                pass
            return False
        try:
            subprocess.Popen(
                ["xdg-open", target],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
        except Exception as exc:
            try:
                self.roots_baseline_status_var.set(
                    f"{label} konnte nicht geöffnet werden: {exc}"
                )
            except Exception:
                pass
            return False
        try:
            self.roots_baseline_status_var.set(f"{label} geöffnet: {target}")
        except Exception:
            pass
        return True

