    def attach_roots_baseline_guard_tree_context_menu(self):
        table = self.__dict__.get("roots_baseline_guard_results_table")
        if table is None:
            return

        menu = tk.Menu(table, tearoff=0)
        menu.add_command(
            label="Kopieren", command=self.copy_roots_baseline_guard_to_clipboard
        )
        menu.add_command(
            label="Einfügen",
            command=self.paste_roots_baseline_guard_selection_from_clipboard,
        )
        menu.add_command(
            label="Alles auswählen",
            command=self.select_all_roots_baseline_guard_entries,
        )
        menu.add_command(
            label="Pfad kopieren",
            command=self.copy_selected_roots_baseline_guard_path,
        )
        menu.add_command(
            label="Übergeordneten Ordner öffnen",
            command=self.open_selected_roots_baseline_guard_parent_folder,
        )
        menu.add_separator()
        menu.add_command(
            label="Auswahl an Chad Analyse senden",
            command=self.analyze_roots_baseline_guard_tree_selection_with_chad,
        )
        menu.add_command(
            label="Auswahl als Chad-Prompt kopieren",
            command=self.copy_roots_baseline_guard_as_chad_prompt,
        )

        def prepare_selection(row_id: str):
            if not row_id:
                return
            try:
                current_selection = tuple(table.selection())
            except Exception:
                current_selection = ()
            if row_id in current_selection:
                try:
                    table.focus(row_id)
                except Exception:
                    pass
                return
            try:
                table.selection_set(row_id)
                table.focus(row_id)
            except Exception:
                pass

        def show_menu(event):
            row_id = ""
            try:
                row_id = table.identify_row(event.y)
            except Exception:
                row_id = ""
            prepare_selection(row_id)
            return self._show_context_menu(menu, event)

        table.bind("<Button-3>", show_menu, add="+")
        table._netmon_context_menu = menu

