    def update_wg_rates(self):
        iface = (self.get_wg_iface() or "").strip()
        if not iface:
            self.last_wg_transfer = None
            self.last_wg_ts = None
            self.wg_rx_rate = 0.0
            self.wg_tx_rate = 0.0
            return

        rc, out = run_cmd(["wg", "show", iface, "transfer"], timeout=3)
        if rc != 0:
            self.last_wg_transfer = None
            self.last_wg_ts = None
            self.wg_rx_rate = 0.0
            self.wg_tx_rate = 0.0
            return

        totals = []
        for line in (out or "").splitlines():
            parts = line.split()
            if len(parts) < 2:
                continue
            try:
                totals.append((int(parts[-2]), int(parts[-1])))
            except ValueError:
                continue

        if not totals:
            self.last_wg_transfer = None
            self.last_wg_ts = None
            self.wg_rx_rate = 0.0
            self.wg_tx_rate = 0.0
            return

        rx_total = sum(rx for rx, _tx in totals)
        tx_total = sum(tx for _rx, tx in totals)
        now = time.time()
        previous = self.__dict__.get("last_wg_transfer")
        previous_ts = self.__dict__.get("last_wg_ts")
        self.last_wg_transfer = (rx_total, tx_total)
        self.last_wg_ts = now

        if not previous or not previous_ts:
            self.wg_rx_rate = 0.0
            self.wg_tx_rate = 0.0
            return

        elapsed = max(0.001, now - float(previous_ts))
        self.wg_rx_rate = max(0.0, (rx_total - previous[0]) / elapsed)
        self.wg_tx_rate = max(0.0, (tx_total - previous[1]) / elapsed)

