    def _set_manual_wg_status(self, message, level="info"):
        text_var = self.__dict__.get("manual_wg_status_var")
        label = self.__dict__.get("manual_wg_status_label")
        if text_var is None:
            return

        palette = {
            "ok": "#1f4f1f",
            "info": "#1f3f74",
            "warn": "#7a5a00",
            "error": "#8b1a1a",
        }
        color = palette.get((level or "info").strip().lower(), palette["info"])
        text_var.set((message or "").strip() or "-")
        if label is not None:
            try:
                label.configure(fg=color)
            except Exception:
                pass

    def _focus_manual_wg_field(self, widget_name):
        widget = self.__dict__.get(str(widget_name or "").strip())
        if widget is None:
            return False
        try:
            widget.focus_set()
        except Exception:
            pass
        try:
            widget.selection_range(0, "end")
        except Exception:
            pass
        try:
            widget.icursor("end")
        except Exception:
            pass
        return True

