    def _collect_missing_installable_dependencies(
        self, checks=None, include_optional=False
    ):
        status = checks if checks is not None else (self.dep_status or {})
        missing = []
        for dep_key, info in DEPENDENCIES.items():
            dep_type = str(info.get("type", "") or "").strip().lower()
            if dep_type == "optional_backend" and not include_optional:
                continue
            check_keys = list(info.get("checks", []) or [])
            if not check_keys:
                continue
            if dep_type == "optional_backend":
                availability_key = str(info.get("availability_check", "") or "").strip()
                if availability_key and not bool(status.get(availability_key, False)):
                    continue
            if any(not status.get(key, False) for key in check_keys):
                missing.append(dep_key)
        return missing

    def _describe_dependency_install_method(self, info):
        dep_type = str(info.get("type", "") or "").strip().lower()
        if dep_type == "file_feature":
            method = str(info.get("install_method", "") or "").strip().lower()
            if method == "zip_import":
                return "ZIP Import"
            return "Datei-Import"
        install_method = str(info.get("install_method", "") or "").strip().lower()
        if install_method == "cloudflare_repo":
            return "Cloudflare Repo"
        methods = []
        if info.get("apt_packages"):
            methods.append("APT")
        if info.get("pip_packages"):
            methods.append("PIP")
        return " + ".join(methods) if methods else "-"

    def _describe_setup_removal_method(self, info):
        kind = str(info.get("kind", "") or "").strip().lower()
        if kind == "apt":
            return "APT remove"
        if kind == "data":
            return "Datei löschen"
        return "-"

    def _project_venv_python_path(self):
        return os.path.join(NETMON_REPO_ROOT, "venv", "bin", "python")

    def _venv_python_modules_available(self, *module_names):
        names = tuple(
            str(name or "").strip() for name in module_names if str(name or "").strip()
        )
        if not names:
            return False

        cache = self.__dict__.get("_venv_module_check_cache")
        if cache is None:
            cache = {}
            self._venv_module_check_cache = cache
        if names in cache:
            return bool(cache[names])

        def _current_runtime_has_modules():
            for module_name in names:
                try:
                    if importlib.util.find_spec(module_name) is None:
                        return False
                except Exception:
                    return False
            return True

        if _current_runtime_has_modules():
            cache[names] = True
            return True

        venv_python = self._project_venv_python_path()
        if not os.path.isfile(venv_python) or not os.access(venv_python, os.X_OK):
            cache[names] = False
            return False

        probe = (
            "import importlib.util, sys\n"
            f"mods = {list(names)!r}\n"
            "sys.stdout.write('1' if all(importlib.util.find_spec(name) is not None for name in mods) else '0')\n"
        )
        try:
            result = subprocess.run(
                [venv_python, "-c", probe],
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL,
                text=True,
                timeout=5,
                check=False,
            )
            available = (
                result.returncode == 0 and str(result.stdout or "").strip() == "1"
            )
        except Exception:
            available = False

        cache[names] = available
        return available

    def _is_safe_netmon_managed_path(self, path):
        raw_path = str(path or "").strip()
        if not raw_path:
            return False
        target = os.path.abspath(os.path.expanduser(raw_path))
        allowed_roots = [
            os.path.abspath(os.path.expanduser(self.netmon_config_dir)),
            os.path.abspath(os.path.expanduser(self.netmon_state_dir)),
            os.path.abspath(os.path.expanduser("~/.local/share/netmon")),
        ]
        for root in allowed_roots:
            if target == root or target.startswith(root + os.sep):
                return True
        return False

    def _count_code_the_classics_files(self):
        root = os.path.abspath(
            os.path.expanduser(str(self.fun_games_dir or "").strip())
        )
        if (
            not root
            or not self._is_safe_netmon_managed_path(root)
            or not os.path.isdir(root)
        ):
            return 0
        count = 0
        for _dirpath, _dirnames, filenames in os.walk(root):
            for filename in filenames:
                if filename.endswith(".py"):
                    count += 1
        return count

    def _import_code_the_classics_zip_archive(self, zip_path):
        target_root = os.path.abspath(
            os.path.expanduser(str(self.fun_games_dir or "").strip())
        )
        if not target_root or not self._is_safe_netmon_managed_path(target_root):
            raise ValueError("Unsicheres Zielverzeichnis für Code the Classics")

        os.makedirs(target_root, exist_ok=True)

        with zipfile.ZipFile(zip_path, "r") as zip_ref:
            members = zip_ref.infolist()
            for member in members:
                member_name = str(member.filename or "").replace("\\", "/")
                if not member_name:
                    continue
                member_path = os.path.abspath(os.path.join(target_root, member_name))
                if member_path != target_root and not member_path.startswith(
                    target_root + os.sep
                ):
                    raise ValueError("Unsicherer ZIP-Pfad erkannt")
            for member in members:
                member_name = str(member.filename or "").replace("\\", "/")
                if not member_name:
                    continue
                member_path = os.path.abspath(os.path.join(target_root, member_name))
                if member.is_dir() or member_name.endswith("/"):
                    os.makedirs(member_path, exist_ok=True)
                    continue
                os.makedirs(os.path.dirname(member_path), exist_ok=True)
                with zip_ref.open(member, "r") as src, open(member_path, "wb") as dst:
                    shutil.copyfileobj(src, dst)

        imported_count = self._count_code_the_classics_files()
        if imported_count <= 0:
            raise ValueError("Keine Python-Spieldateien in der ZIP gefunden")
        return imported_count

    def _get_code_the_classics_zip_path(self):
        zip_path = find_code_the_classics_zip()
        if zip_path:
            return zip_path
        raise FileNotFoundError(
            "Code-the-Classics.zip nicht gefunden. "
            "Erwartet in: netmon/features/Code-the-Classics.zip"
        )

    def _install_selected_file_features(self, dependency_keys):
        imported_features = []
        for dep_key in dependency_keys:
            info = DEPENDENCIES.get(dep_key, {})
            dep_type = str(info.get("type", "") or "").strip().lower()
            if dep_type != "file_feature":
                continue
            install_method = str(info.get("install_method", "") or "").strip().lower()
            if dep_key == "code_the_classics_files" and install_method == "zip_import":
                zip_path = self._get_code_the_classics_zip_path()
                imported_count = self._import_code_the_classics_zip_archive(zip_path)
                imported_features.append((dep_key, imported_count))
                continue
            raise ValueError(f"Unbekannte Installationsmethode für {dep_key}")
        return imported_features

    def _collect_setup_removable_components(self, checks=None):
        status = checks if checks is not None else (self.dep_status or {})
        removable = []
        for comp_key, info in SETUP_REMOVABLES.items():
            kind = str(info.get("kind", "") or "").strip().lower()
            if kind == "apt":
                check_keys = list(info.get("checks", []) or [])
                if check_keys and all(status.get(key, False) for key in check_keys):
                    removable.append(comp_key)
                continue
            if kind == "data":
                if comp_key == "fun_code_classics":
                    if self._count_code_the_classics_files() > 0:
                        removable.append(comp_key)
                    continue
                paths = []
                for attr_name in info.get("path_attrs", []) or []:
                    value = getattr(self, attr_name, "")
                    if value:
                        paths.append(value)
                if any(
                    self._is_safe_netmon_managed_path(path) and os.path.exists(path)
                    for path in paths
                ):
                    removable.append(comp_key)
        return removable

    def _update_dependency_installer_button(self):
        missing_count = len(getattr(self, "dep_installer_missing_keys", []) or [])
        removable_count = len(getattr(self, "dep_installer_removable_keys", []) or [])
        if missing_count:
            self.dep_installer_button_var.set(
                f"Fehlende Komponenten installieren ({missing_count})"
            )
        elif removable_count:
            self.dep_installer_button_var.set("Setup-Assistent öffnen")
        else:
            self.dep_installer_button_var.set("Fehlende Komponenten installieren")
        button = self.__dict__.get("btn_dependency_installer")
        if button is not None:
            try:
                button.configure(
                    state="normal" if (missing_count or removable_count) else "disabled"
                )
            except Exception:
                pass
        if self.dep_installer_window is not None:
            try:
                self._populate_dependency_installer_rows()
                self._populate_dependency_removal_rows()
            except Exception:
                pass

    def _build_dependency_terminal_command(self, dependency_keys):
        apt_packages = []
        pip_packages = []
        commands = []
        for dep_key in dependency_keys:
            if dep_key == "projectm_visualizer":
                try:
                    probe = netmon_projectm_sidecar.probe_projectm_package_candidates(
                        app=self,
                        refresh=True,
                    )
                except Exception:
                    probe = {}
                projectm_command = (
                    netmon_projectm_sidecar.build_projectm_install_command(probe)
                )
                if projectm_command:
                    commands.append(projectm_command)
                continue
            info = DEPENDENCIES.get(dep_key, {})
            for package in info.get("apt_packages", []) or []:
                if package not in apt_packages:
                    apt_packages.append(package)
            for package in info.get("pip_packages", []) or []:
                if package not in pip_packages:
                    pip_packages.append(package)
        if apt_packages:
            commands.append("sudo apt install -y " + " ".join(apt_packages))
        if pip_packages:
            repo_root = shlex.quote(NETMON_REPO_ROOT)
            venv_dir = shlex.quote(os.path.join(NETMON_REPO_ROOT, "venv"))
            venv_python = shlex.quote(
                os.path.join(NETMON_REPO_ROOT, "venv", "bin", "python")
            )
            venv_activate = shlex.quote(
                os.path.join(NETMON_REPO_ROOT, "venv", "bin", "activate")
            )
            venv_pip = shlex.quote(os.path.join(NETMON_REPO_ROOT, "venv", "bin", "pip"))
            requirements_path = shlex.quote(
                os.path.join(NETMON_REPO_ROOT, "requirements.txt")
            )
            commands.extend(
                [
                    "echo 'Virtuelle Umgebung wird erstellt ...'",
                    "if ! dpkg -s python3-venv >/dev/null 2>&1; then sudo apt install -y python3-venv python3-full; fi",
                    f"cd {repo_root}",
                    f"if [ ! -d {venv_dir} ]; then python3 -m venv {venv_dir}; fi",
                    f"if [ ! -x {venv_pip} ]; then {venv_python} -m ensurepip --upgrade; fi",
                    f"if [ ! -f {requirements_path} ]; then echo 'requirements.txt fehlt.'; exit 1; fi",
                    f". {venv_activate}",
                    "if ! command -v pip >/dev/null 2>&1; then python -m ensurepip --upgrade; fi",
                    "echo 'Python-Abhängigkeiten werden installiert ...'",
                    f"pip install -r {requirements_path}",
                    "echo 'Installation abgeschlossen.'",
                ]
            )
        return " ; ".join(commands)

    def _populate_dependency_installer_rows(self):
        frame = self.__dict__.get("dep_installer_rows_frame")
        if frame is None:
            return
        for child in frame.winfo_children():
            try:
                child.destroy()
            except Exception:
                pass
        self.dep_installer_vars = {}
        sorted_missing_keys = sorted(
            self.dep_installer_missing_keys,
            key=self._dependency_installer_sort_key,
        )
        for row_idx, dep_key in enumerate(sorted_missing_keys):
            info = DEPENDENCIES.get(dep_key, {})
            row = ttk.Frame(frame)
            row.pack(fill="x", pady=2)
            var = tk.BooleanVar(value=True)
            self.dep_installer_vars[dep_key] = var
            left = ttk.Frame(row)
            left.pack(side="left", fill="x", expand=True)
            title = info.get("label", dep_key)
            category = info.get("category", "")
            if category:
                title = f"{title} [{category}]"
            ttk.Checkbutton(left, variable=var, text=title).pack(anchor="w")
            ttk.Label(
                left,
                text=info.get("description", ""),
                foreground="#666666",
            ).pack(anchor="w", padx=(24, 0))
            ttk.Label(
                row,
                text=self._describe_dependency_install_method(info),
                width=9,
                anchor="e",
                foreground="#666666",
            ).pack(side="right")
        if not self.dep_installer_missing_keys:
            ttk.Label(
                frame,
                text="Keine fehlenden Komponenten erkannt.",
                foreground="#666666",
            ).pack(anchor="w")
        self._populate_dependency_installer_optional_hint()

    def _populate_dependency_installer_optional_hint(self):
        frame = self.__dict__.get("dep_installer_optional_frame")
        if frame is None:
            return
        for child in frame.winfo_children():
            try:
                child.destroy()
            except Exception:
                pass
        if "projectm_visualizer" not in (self.dep_installer_missing_keys or []):
            return

        try:
            probe = netmon_projectm_sidecar.probe_projectm_package_candidates()
        except Exception:
            probe = {}
        packages = ", ".join(list(probe.get("available_packages", []) or []))
        strategy = str(probe.get("install_strategy", "") or "").strip()
        flatpak_ready = bool(probe.get("flatpak_available"))

        box = ttk.Frame(frame, padding=(8, 6))
        box.pack(fill="x", pady=(0, 8))
        ttk.Label(
            box,
            text="Optional verfügbar: projectM Visualizer",
            font=("TkDefaultFont", 10, "bold"),
        ).pack(anchor="w")
        if strategy == "apt":
            detail = (
                "projectM ist als externer Test-Visualizer per APT installierbar."
                if not packages
                else "projectM ist als externer Test-Visualizer per APT installierbar. "
                f"Paket: {packages}"
            )
        elif strategy == "flatpak":
            detail = (
                "projectM ist nicht als APT-Paket verfügbar. "
                "Flatpak-Installation ist optional möglich."
            )
        elif strategy == "install_flatpak":
            detail = (
                "projectM ist nicht als APT-Paket verfügbar. "
                "Optional: zuerst Flatpak, dann projectM über Flathub installieren."
            )
        elif flatpak_ready:
            detail = "projectM ist als externer Test-Visualizer über Flatpak verfügbar."
        else:
            detail = "projectM ist als externer Test-Visualizer optional verfügbar."
        ttk.Label(
            box,
            text=detail,
            foreground="#555555",
            wraplength=680,
            justify="left",
        ).pack(anchor="w", pady=(2, 0))
        ttk.Button(
            box,
            text="Nur projectM auswählen",
            command=lambda: self._select_only_missing_dependency("projectm_visualizer"),
        ).pack(anchor="w", pady=(6, 0))

    def _select_only_missing_dependency(self, dep_key):
        has_match = False
        for key, var in (self.dep_installer_vars or {}).items():
            selected = key == dep_key
            if selected:
                has_match = True
            try:
                var.set(selected)
            except Exception:
                pass
        if has_match:
            try:
                self.dep_installer_status_var.set(
                    f"Auswahl gesetzt: {DEPENDENCIES.get(dep_key, {}).get('label', dep_key)}"
                )
            except Exception:
                pass

    def _dependency_installer_sort_key(self, dep_key):
        priority = {
            "projectm_visualizer": 0,
            "mpv": 1,
        }
        info = DEPENDENCIES.get(dep_key, {})
        category = str(info.get("category", "") or "").strip().lower()
        label = str(info.get("label", dep_key) or dep_key).strip().lower()
        return (
            priority.get(dep_key, 50),
            0 if category == "radio" else 1,
            label,
        )

    def _populate_dependency_removal_rows(self):
        frame = self.__dict__.get("dep_installer_remove_rows_frame")
        if frame is None:
            return
        for child in frame.winfo_children():
            try:
                child.destroy()
            except Exception:
                pass
        self.dep_installer_remove_vars = {}
        for comp_key in self.dep_installer_removable_keys:
            info = SETUP_REMOVABLES.get(comp_key, {})
            row = ttk.Frame(frame)
            row.pack(fill="x", pady=2)
            var = tk.BooleanVar(value=False)
            self.dep_installer_remove_vars[comp_key] = var
            left = ttk.Frame(row)
            left.pack(side="left", fill="x", expand=True)
            title = info.get("label", comp_key)
            category = info.get("category", "")
            if category:
                title = f"{title} [{category}]"
            ttk.Checkbutton(left, variable=var, text=title).pack(anchor="w")
            ttk.Label(
                left,
                text=info.get("description", ""),
                foreground="#666666",
            ).pack(anchor="w", padx=(24, 0))
            ttk.Label(
                row,
                text=self._describe_setup_removal_method(info),
                width=9,
                anchor="e",
                foreground="#666666",
            ).pack(side="right")
        if not self.dep_installer_removable_keys:
            ttk.Label(
                frame,
                text="Keine optionalen Komponenten zum Entfernen erkannt.",
                foreground="#666666",
            ).pack(anchor="w")

    def _select_all_missing_dependencies(self):
        for var in (self.dep_installer_vars or {}).values():
            try:
                var.set(True)
            except Exception:
                pass

    def _clear_selected_removals(self):
        for var in (self.dep_installer_remove_vars or {}).values():
            try:
                var.set(False)
            except Exception:
                pass

