    def install_selected_dependencies(self):
        selected_keys = [
            dep_key
            for dep_key, var in (self.dep_installer_vars or {}).items()
            if bool(var.get())
        ]
        if not selected_keys:
            self.dep_installer_status_var.set("Keine Komponenten ausgewählt.")
            return

        file_feature_keys = [
            dep_key
            for dep_key in selected_keys
            if str((DEPENDENCIES.get(dep_key, {}) or {}).get("type", ""))
            .strip()
            .lower()
            == "file_feature"
        ]
        package_keys = [
            dep_key for dep_key in selected_keys if dep_key not in file_feature_keys
        ]

        imported_features = []
        if file_feature_keys:
            try:
                imported_features = self._install_selected_file_features(
                    file_feature_keys
                )
            except Exception as exc:
                self.dep_installer_status_var.set(f"ZIP-Import fehlgeschlagen: {exc}")
                self.log_safe(f"Setup ZIP-Import Fehler: {exc}")
                return
            if imported_features is False:
                return
            if imported_features:
                self.refresh_fun_games()
                imported_messages = []
                for dep_key, imported_count in imported_features:
                    label = DEPENDENCIES.get(dep_key, {}).get("label", dep_key)
                    imported_messages.append(f"{label} ({imported_count} Spiele)")
                self.log_safe("Setup importiert: " + ", ".join(imported_messages))

        if not package_keys:
            self.dep_installer_status_var.set("Installation abgeschlossen.")
            self.preflight_dependencies(manual_trigger=True)
            return

        if not messagebox.askyesno(
            "Komponenten installieren",
            "NetMon installiert jetzt ausgewählte Pakete über apt und/oder pip.\n"
            "Es werden sudo-Rechte benötigt.\n\n"
            "Fortfahren?",
            parent=self,
        ):
            self.dep_installer_status_var.set("Installation abgebrochen.")
            return

        install_cmd = self._build_dependency_terminal_command(package_keys)
        if not install_cmd:
            self.dep_installer_status_var.set(
                "Für die Auswahl ist kein APT-Befehl definiert."
            )
            return

        script = (
            f"{install_cmd}; "
            "echo; "
            "echo 'Installer beendet. Shell bleibt offen.'; "
            "exec bash"
        )
        launch_cmd = self._build_external_terminal_command(script)
        if not launch_cmd:
            self.dep_installer_status_var.set("Kein externes Terminal gefunden.")
            self.log_safe("Dependency Installer: Kein unterstütztes Terminal gefunden.")
            return

        proc = subprocess.Popen(launch_cmd, start_new_session=True)
        self.dep_installer_status_var.set("Installation im Terminal gestartet.")
        self.log_safe("Dependency Installer gestartet.")
        self.log_safe(install_cmd)

        def monitor_terminal():
            try:
                proc.wait()
            except Exception:
                pass
            try:
                self.after(0, self.preflight_dependencies, True)
            except Exception:
                self.preflight_dependencies(manual_trigger=True)

        threading.Thread(target=monitor_terminal, daemon=True).start()

    def _build_setup_removal_terminal_command(self, component_keys):
        apt_packages = []
        for comp_key in component_keys:
            info = SETUP_REMOVABLES.get(comp_key, {})
            if str(info.get("kind", "") or "").strip().lower() != "apt":
                continue
            for package in info.get("packages", []) or []:
                if package not in apt_packages:
                    apt_packages.append(package)
        if not apt_packages:
            return ""
        return "sudo apt remove -y " + " ".join(apt_packages)

    def _remove_selected_netmon_paths(self, component_keys):
        removed = []
        for comp_key in component_keys:
            info = SETUP_REMOVABLES.get(comp_key, {})
            if str(info.get("kind", "") or "").strip().lower() != "data":
                continue
            for attr_name in info.get("path_attrs", []) or []:
                raw_path = getattr(self, attr_name, "")
                path = str(raw_path or "").strip()
                if not path or not self._is_safe_netmon_managed_path(path):
                    continue
                path = os.path.abspath(os.path.expanduser(path))
                if not os.path.exists(path):
                    continue
                if os.path.isdir(path):
                    shutil.rmtree(path)
                else:
                    os.remove(path)
                removed.append(path)
        return removed

    def remove_selected_setup_components(self):
        selected_keys = [
            comp_key
            for comp_key, var in (self.dep_installer_remove_vars or {}).items()
            if bool(var.get())
        ]
        if not selected_keys:
            self.dep_installer_remove_status_var.set("Keine Komponenten ausgewählt.")
            return

        selected_infos = [
            SETUP_REMOVABLES.get(comp_key, {}) for comp_key in selected_keys
        ]
        if any(info.get("kind") == "apt" for info in selected_infos):
            if not messagebox.askyesno(
                "Komponenten entfernen",
                "Achtung:\n"
                "Mindestens ein Paket kann auch von anderen Programmen genutzt werden.\n"
                "Wirklich entfernen?",
                parent=self,
            ):
                self.dep_installer_remove_status_var.set("Entfernen abgebrochen.")
                return
        elif not messagebox.askyesno(
            "Komponenten entfernen",
            "Ausgewählte NetMon-Daten jetzt entfernen?",
            parent=self,
        ):
            self.dep_installer_remove_status_var.set("Entfernen abgebrochen.")
            return

        apt_cmd = self._build_setup_removal_terminal_command(selected_keys)

        def finish_refresh():
            self.log_safe("Setup: Entfernung abgeschlossen.")
            try:
                self.after(0, self.preflight_dependencies, True)
            except Exception:
                self.preflight_dependencies(manual_trigger=True)

        try:
            removed_paths = self._remove_selected_netmon_paths(selected_keys)
        except Exception as exc:
            self.dep_installer_remove_status_var.set(
                f"Fehler beim Entfernen lokaler Daten: {exc}"
            )
            self.log_safe(f"Setup Entfernen Fehler: {exc}")
            return

        if removed_paths:
            self.log_safe(
                "Setup entfernt: "
                + ", ".join(os.path.basename(path) for path in removed_paths)
            )

        if not apt_cmd:
            self.dep_installer_remove_status_var.set("Entfernen abgeschlossen.")
            finish_refresh()
            return

        script = (
            f"{apt_cmd}; "
            "echo; "
            "echo 'Entfernen beendet. Shell bleibt offen.'; "
            "exec bash"
        )
        launch_cmd = self._build_external_terminal_command(script)
        if not launch_cmd:
            self.dep_installer_remove_status_var.set("Kein externes Terminal gefunden.")
            self.log_safe("Setup Entfernen: Kein unterstütztes Terminal gefunden.")
            return

        proc = subprocess.Popen(launch_cmd, start_new_session=True)
        self.dep_installer_remove_status_var.set("Entfernen im Terminal gestartet.")
        self.log_safe("Setup Entfernen gestartet.")
        self.log_safe(apt_cmd)

        def monitor_terminal():
            try:
                proc.wait()
            except Exception:
                pass
            finish_refresh()

        threading.Thread(target=monitor_terminal, daemon=True).start()

    def _log_preflight_tool_state(self, label, ok, path=""):
        if ok and path:
            self.log(
                self.tr("preflight_tool_ok_path", "{label}: OK ({path})").format(
                    label=label, path=path
                )
            )
        elif ok:
            self.log(self.tr("preflight_tool_ok", "{label}: OK").format(label=label))
        else:
            self.log(
                self.tr("preflight_tool_missing", "{label}: FEHLT").format(label=label)
            )

    def _log_strict_protection_state(self, prefix="Strenger Schutz"):
        strict_var = self.__dict__.get("strict_protection_var")
        if strict_var is not None:
            try:
                enabled = bool(strict_var.get())
            except Exception:
                enabled = bool(getattr(self, "danger_guard_enabled", True))
        else:
            enabled = bool(getattr(self, "danger_guard_enabled", True))
        self.log(
            self.tr(
                "preflight_strict_protection_state",
                "{prefix}: {state}",
            ).format(
                prefix=prefix,
                state=(
                    self.tr(
                        "preflight_strict_protection_on",
                        "AKTIV (Bestätigungswort AUSFUEHREN erforderlich)",
                    )
                    if enabled
                    else self.tr(
                        "preflight_strict_protection_off",
                        "AUS (nur Standard-Bestätigung)",
                    )
                ),
            )
        )

    def _log_preflight_manual_summary(self, checks):
        ordered_tools = [
            ("traceroute", "traceroute"),
            ("mtr", "mtr"),
            ("nmap", "nmap"),
            ("nmcli", "nmcli"),
            ("resolvectl", "resolvectl"),
            ("wg", "wg"),
            ("wg-quick", "wg-quick"),
            ("ufw", "ufw"),
            ("ss", "ss"),
            ("iftop", "iftop"),
            ("htop", "htop"),
            ("tshark", "tshark"),
            ("dumpcap", "dumpcap"),
            ("Wireshark GUI", "wireshark"),
            ("capinfos", "capinfos"),
            ("lynis", "lynis"),
            ("rkhunter", "rkhunter"),
            ("whois", "whois"),
            ("mpv (Radio)", "mpv"),
            ("projectM Visualizer", "projectm_visualizer"),
            ("python3 (Fun)", "python3"),
        ]
        projectm_state = None
        try:
            projectm_state = netmon_projectm_sidecar.get_projectm_sidecar_status(
                app=self
            )
        except Exception:
            projectm_state = None
        for label, key in ordered_tools:
            if key == "projectm_visualizer":
                path = ""
                if projectm_state is not None:
                    command = list(projectm_state.command or [])
                    backend_label = str(projectm_state.backend_label or "").strip()
                    if command:
                        path = " ".join(command)
                    elif checks.get("projectm_visualizer_installable", False):
                        path = (
                            f"{backend_label} optional" if backend_label else "Optional"
                        )
                elif checks.get("projectm_visualizer_installable", False):
                    path = "Optional"
            else:
                path = get_cmd_path(key)
            self._log_preflight_tool_state(label, checks.get(key, False), path)

        speedtest_path = get_cmd_path("speedtest") or get_cmd_path("speedtest-cli")
        self._log_preflight_tool_state(
            "Speedtest CLI", checks.get("speedtest", False), speedtest_path
        )
        self._log_preflight_tool_state(
            "Speedtest Modul", checks.get("speedtest_module", False)
        )

        self._log_preflight_tool_state(
            "ClamAV Scan", checks.get("clamav", False), get_cmd_path("clamscan")
        )
        self._log_preflight_tool_state(
            "ClamAV Update",
            checks.get("freshclam", False),
            get_cmd_path("freshclam"),
        )
        self._log_preflight_tool_state("Pillow (Log-Bild)", checks.get("pillow", False))
        self._log_preflight_tool_state(
            "pygame (Fun)", checks.get("pygame_module", False)
        )
        self._log_preflight_tool_state(
            "pgzero (Fun)", checks.get("pgzero_module", False)
        )
        code_file_count = self._count_code_the_classics_files()
        if code_file_count:
            self.log(
                f"Code the Classics Spiele: OK ({code_file_count} Dateien gefunden)"
            )
        else:
            self.log("Code the Classics Spiele: FEHLT")
        if not checks.get("pillow", False) and PIL_IMPORT_ERROR:
            self.log("Pillow Detail: " + PIL_IMPORT_ERROR)
        self._log_strict_protection_state("Strenger Schutz")

    def _log_dependency_installer_summary(self):
        missing_count = len(getattr(self, "missing_dependencies", []) or [])
        if missing_count:
            self.log(
                f"Preflight: {missing_count} Komponenten fehlen. Bitte Setup-Assistent öffnen."
            )
        else:
            self.log("Preflight: Alle Abhängigkeiten OK.")

    def preflight_dependencies(self, manual_trigger=False):
        self._venv_module_check_cache = {}
        vscode_desktop = self._find_vscode_desktop_file()
        wireshark_launcher = self._resolve_wireshark_launcher()
        wireshark_available = bool(wireshark_launcher.get("target"))
        speedtest_module_ok, speedtest_module_detail = check_speedtest_module_available(
            app_file=__file__,
            repo_root=NETMON_REPO_ROOT,
            search_paths=sys.path,
        )
        checks = {
            "sudo": has_cmd("sudo"),
            "ip": has_cmd("ip"),
            "ping": has_cmd("ping"),
            "curl": has_cmd("curl"),
            "systemctl": has_cmd("systemctl"),
            "wg": has_cmd("wg"),
            "wg-quick": has_cmd("wg-quick"),
            "ufw": has_cmd("ufw"),
            "nmcli": has_cmd("nmcli"),
            "dig": has_cmd("dig"),
            "nslookup": has_cmd("nslookup"),
            "tracepath": has_cmd("tracepath"),
            "traceroute": has_cmd("traceroute"),
            "ss": has_cmd("ss"),
            "resolvectl": has_cmd("resolvectl"),
            "find": has_cmd("find"),
            "install": has_cmd("install"),
            "mtr": has_cmd("mtr"),
            "nmap": has_cmd("nmap"),
            "speedtest": has_cmd("speedtest") or has_cmd("speedtest-cli"),
            "speedtest_module": speedtest_module_ok,
            "iftop": has_cmd("iftop"),
            "htop": has_cmd("htop"),
            "tshark": has_cmd("tshark"),
            "dumpcap": has_cmd("dumpcap"),
            "wireshark": wireshark_available,
            "capinfos": has_cmd("capinfos"),
            "lynis": has_cmd("lynis"),
            "rkhunter": has_cmd("rkhunter"),
            "clamav": has_cmd("clamscan"),
            "freshclam": has_cmd("freshclam"),
            "pillow": (Image is not None and ImageTk is not None)
            or self._venv_python_modules_available("PIL", "PIL.ImageTk"),
            "pypdf2": PyPDF2 is not None
            or self._venv_python_modules_available("PyPDF2"),
            "docx": docx is not None or self._venv_python_modules_available("docx"),
            "whois": has_cmd("whois"),
            "mpv": has_cmd("mpv"),
            "pactl": has_cmd("pactl"),
            "parec": has_cmd("parec"),
            "projectM": has_cmd("projectM"),
            "projectm": has_cmd("projectm"),
            "projectM-pulseaudio": has_cmd("projectM-pulseaudio"),
            "projectm-pulseaudio": has_cmd("projectm-pulseaudio"),
            "python3": has_cmd("python3"),
            # legacy direct probe reference for source-based tests:
            # "pygame_module": importlib.util.find_spec("pygame") is not None
            # "pgzero_module": importlib.util.find_spec("pgzero") is not None
            "pygame_module": self._venv_python_modules_available("pygame"),
            "pgzero_module": self._venv_python_modules_available("pgzero"),
            "code_the_classics_files": self._count_code_the_classics_files() > 0,
            "xdg-open": has_cmd("xdg-open"),
            "lsblk": has_cmd("lsblk"),
            "findmnt": has_cmd("findmnt"),
            "df": has_cmd("df"),
            "mount": has_cmd("mount"),
            "umount": has_cmd("umount"),
            "mkdir": has_cmd("mkdir"),
            "udisksctl": has_cmd("udisksctl"),
            "cryptsetup": has_cmd("cryptsetup"),
            "tail": has_cmd("tail"),
            "gtk-launch": has_cmd("gtk-launch"),
            "code": has_cmd("code"),
            "codium": has_cmd("codium"),
            "code-insiders": has_cmd("code-insiders"),
            "vscode_desktop": bool(vscode_desktop),
        }
        projectm_state = netmon_projectm_sidecar.get_projectm_sidecar_status(app=self)
        projectm_probe = netmon_projectm_sidecar.probe_projectm_package_candidates(
            app=self
        )
        checks["projectm_visualizer_installable"] = bool(
            projectm_probe.get("installable", False)
        )
        checks["flatpak"] = bool(projectm_probe.get("flatpak_available", False))
        checks["projectm_visualizer"] = bool(projectm_state.installed)
        checks["wireshark_launcher"] = wireshark_launcher
        self.dep_status = checks
        self.dep_installer_missing_keys = (
            self._collect_missing_installable_dependencies(
                checks, include_optional=True
            )
        )
        self.missing_dependencies = list(self.dep_installer_missing_keys)
        self.dep_installer_removable_keys = self._collect_setup_removable_components(
            checks
        )

        if not self.security_clamav_running and not self.security_clamav_update_running:
            if checks.get("clamav"):
                sig_status = "aktuell" if checks.get("freshclam") else "unbekannt"
                self.update_clamav_panel(status="bereit", signatures=sig_status)
            else:
                sig_status = (
                    "nicht aktualisierbar"
                    if not checks.get("freshclam")
                    else "unbekannt"
                )
                self.update_clamav_panel(
                    status="nicht installiert", signatures=sig_status
                )

        self.sudo_nopasswd = check_sudo_nopasswd()
        sudo_ready = self.sudo_nopasswd

        if manual_trigger:
            self._log_preflight_manual_summary(checks)
            if not checks.get("speedtest_module") and speedtest_module_detail:
                self.log(
                    self.tr(
                        "preflight_speedtest_module_detail",
                        "Speedtest Modul Detail: {detail}",
                    ).format(detail=speedtest_module_detail)
                )
            self._log_dependency_installer_summary()
        else:
            required = ["sudo", "ip", "ping", "curl", "wg", "wg-quick", "ufw"]
            missing_required = [name for name in required if not checks.get(name)]
            if missing_required:
                self.log(
                    self.tr(
                        "preflight_missing_required_tools",
                        "Fehlende Pflicht-Tools: {tools}",
                    ).format(tools=", ".join(missing_required))
                )
            else:
                self.log(
                    self.tr(
                        "preflight_required_tools_ok", "Preflight: Pflicht-Tools OK."
                    )
                )

            if not sudo_ready:
                self.log(
                    self.tr(
                        "preflight_warning_no_sudo",
                        "WARNUNG: Keine gültige Sudo-Authentifizierung aktiv – Aktionen können fehlschlagen.",
                    )
                )
            else:
                self.log(
                    self.tr(
                        "preflight_sudo_session_valid",
                        "Preflight: sudo-Session gültig (sudo -n true).",
                    )
                )

            self._log_strict_protection_state("Strenger Schutz")
            if checks.get("speedtest") and not checks.get("speedtest_module"):
                self.log(
                    self.tr(
                        "preflight_speedtest_cli_detected", "Speedtest CLI erkannt."
                    )
                )
                self.log(
                    self.tr(
                        "preflight_speedtest_module_detail",
                        "Speedtest Modul Detail: {detail}",
                    ).format(detail=speedtest_module_detail)
                )
            if not checks.get("pillow") and PIL_IMPORT_ERROR:
                self.log("Pillow Detail: " + PIL_IMPORT_ERROR)
            if not checks.get("pypdf2") and PYPDF2_IMPORT_ERROR:
                self.log("PDF Import Detail: " + PYPDF2_IMPORT_ERROR)
            if not checks.get("docx") and DOCX_IMPORT_ERROR:
                self.log("DOCX Import Detail: " + DOCX_IMPORT_ERROR)
            self._log_dependency_installer_summary()

        self.set_feature_enabled(
            "wg", checks.get("wg", False) and checks.get("wg-quick", False)
        )
        self.set_feature_enabled(
            "wg_profiles",
            checks.get("install", False) and checks.get("sudo", False),
        )
        self.set_feature_enabled(
            "ufw", checks.get("ufw", False) and checks.get("sudo", False)
        )
        self.set_feature_enabled("nmcli", checks.get("nmcli", False))
        self.set_feature_enabled(
            "dot",
            checks.get("sudo", False)
            and checks.get("install", False)
            and checks.get("systemctl", False)
            and checks.get("resolvectl", False),
        )
        self.set_feature_enabled(
            "dns_consistency", checks.get("dig", False) or checks.get("nslookup", False)
        )
        self.set_feature_enabled(
            "trace_log",
            checks.get("tracepath", False) or checks.get("traceroute", False),
        )
        self.set_feature_enabled("traceroute", checks.get("traceroute", False))
        self.set_feature_enabled("ss", checks.get("ss", False))
        self.set_feature_enabled("mtr", checks.get("mtr", False))
        self.set_feature_enabled("nmap", checks.get("nmap", False))
        self.set_feature_enabled(
            "speedtest",
            checks.get("speedtest", False) and checks.get("speedtest_module", False),
        )
        self.set_feature_enabled("iftop", checks.get("iftop", False))
        self.set_feature_enabled("htop", checks.get("htop", False))
        self.set_feature_enabled("packet_capture_ui", checks.get("ip", False))
        self.set_feature_enabled(
            "packet_capture",
            checks.get("tshark", False) or checks.get("dumpcap", False),
        )
        self.set_feature_enabled("wireshark_open", checks.get("wireshark", False))
        self.set_feature_enabled("lynis", checks.get("lynis", False))
        self.set_feature_enabled("rkhunter", checks.get("rkhunter", False))
        self.set_feature_enabled("radio", checks.get("mpv", False))
        self.set_feature_enabled("fun", checks.get("python3", False))
        self.set_feature_enabled("clamav", checks.get("clamav", False))
        self.set_feature_enabled("clamav_scan", checks.get("clamav", False))
        self.set_feature_enabled("clamav_update", checks.get("freshclam", False))
