    # ---------- IPv6 ----------
    def ipv6_is_disabled(self):
        checks = [
            "net.ipv6.conf.all.disable_ipv6",
            "net.ipv6.conf.default.disable_ipv6",
        ]
        values = []

        for key in checks:
            rc, out = run_cmd(["sysctl", "-n", key], timeout=3)
            if rc == 0:
                value = (out or "").strip()
                if value in {"0", "1"}:
                    values.append(value == "1")
                    continue
            proc_path = f"/proc/sys/{key.replace('.', '/')}"
            try:
                with open(proc_path, "r", encoding="utf-8") as f:
                    value = f.read().strip()
                if value in {"0", "1"}:
                    values.append(value == "1")
            except Exception:
                continue

        if values:
            # Konservativ: IPv6 gilt als deaktiviert, wenn all/default deaktiviert sind.
            return all(values)
        return False

    def ipv6_runtime_available_on_iface(self, iface):
        name = (iface or "").strip()
        if not name or self.ipv6_is_disabled():
            return False
        rc, out = run_cmd(
            ["ip", "-6", "-o", "addr", "show", "dev", name, "scope", "global"],
            timeout=4,
        )
        if rc != 0:
            return False
        for line in (out or "").splitlines():
            if " inet6 " in line:
                return True
        return False

    def update_ipv6_controls_state(self):
        def _widget_exists(widget):
            if widget is None:
                return False
            if hasattr(widget, "configure") or hasattr(widget, "config"):
                return True
            try:
                return bool(int(widget.winfo_exists()))
            except Exception:
                return False

        active_profile = (self.active_wg_profile() or "").strip()
        selected_profile = ""
        selected_profile_var = self.__dict__.get("isp_stealth_vpn_profile")
        if selected_profile_var is not None:
            selected_profile = (selected_profile_var.get() or "").strip()
        selected_choice_var = self.__dict__.get("isp_stealth_vpn_choice")
        if not selected_profile and selected_choice_var is not None:
            selected_profile = self._privacy_vpn_profile_from_value(
                selected_choice_var.get()
            )

        buttons_state = "normal"
        system_ipv6_enabled = not self.ipv6_is_disabled()
        active_iface = (self.get_wg_iface() or "").strip()
        active_supports_ipv6 = bool(
            active_profile and self.profile_supports_ipv6(active_profile)
        )
        active_runtime_ipv6 = bool(
            active_iface and self.ipv6_runtime_available_on_iface(active_iface)
        )

        if not active_profile:
            vpn_status = "kein aktives Profil"
        elif active_runtime_ipv6 or (active_iface and system_ipv6_enabled):
            vpn_status = "nutzt IPv6"
        elif active_supports_ipv6 and not system_ipv6_enabled:
            vpn_status = "erwartet IPv6, System deaktiviert"
        else:
            vpn_status = "nutzt nur IPv4"

        system_status = "aktiv" if system_ipv6_enabled else "deaktiviert"
        ipv6_hint_lines = [
            "IPv6 Status:",
            f"System:        {system_status}",
            f"VPN-Profil:    {vpn_status}",
        ]

        ipv6_hint = "\n".join(ipv6_hint_lines)

        for widget_name in ("btn_ipv6_on", "btn_ipv6_off"):
            widget = self.__dict__.get(widget_name)
            if widget is None:
                continue
            try:
                widget.configure(state=buttons_state)
            except Exception:
                try:
                    widget["state"] = buttons_state
                except Exception:
                    pass

        ipv6_controls_hint = self.__dict__.get("ipv6_controls_hint")
        if _widget_exists(ipv6_controls_hint):
            if not active_profile:
                hint_color = "#666666"
            elif active_runtime_ipv6:
                hint_color = "#2e7d32"
            else:
                hint_color = "#c62828"
            ipv6_controls_hint.config(text=ipv6_hint, foreground=hint_color)

        privacy_profile = active_profile or selected_profile
        privacy_enabled = True
        privacy_hint = ""
        if privacy_profile and not self.profile_supports_ipv6(privacy_profile):
            privacy_enabled = False
            if active_profile:
                privacy_hint = "Aktives VPN-Profil nutzt nur IPv4"
            else:
                privacy_hint = "Gewaehltes Privacy-VPN-Profil nutzt nur IPv4"

        privacy_state = "normal" if privacy_enabled else "disabled"
        widget = self.__dict__.get("cb_privacy_ipv6")
        if widget is not None:
            try:
                widget.configure(state=privacy_state)
            except Exception:
                try:
                    widget["state"] = privacy_state
                except Exception:
                    pass
        privacy_ipv6_hint = self.__dict__.get("privacy_ipv6_hint")
        if _widget_exists(privacy_ipv6_hint):
            privacy_ipv6_hint.config(text=privacy_hint)

    def ipv6_disable(self, refresh_ui=True):
        ok = True
        cmds = [
            ["sudo", "-n", "sysctl", "-w", "net.ipv6.conf.all.disable_ipv6=1"],
            ["sudo", "-n", "sysctl", "-w", "net.ipv6.conf.default.disable_ipv6=1"],
            ["sudo", "-n", "sysctl", "-w", "net.ipv6.conf.lo.disable_ipv6=1"],
        ]
        for c in cmds:
            rc, out = run_cmd(c, timeout=6)
            if rc != 0:
                ok = False
                if out:
                    self.log_safe(out)
        self.log_safe("IPv6: deaktiviert (sysctl; nicht persistent nach Reboot).")
        if refresh_ui:
            self.refresh_safe()
        return ok

    def ipv6_enable(self, refresh_ui=True):
        ok = True
        cmds = [
            ["sudo", "-n", "sysctl", "-w", "net.ipv6.conf.all.disable_ipv6=0"],
            ["sudo", "-n", "sysctl", "-w", "net.ipv6.conf.default.disable_ipv6=0"],
            ["sudo", "-n", "sysctl", "-w", "net.ipv6.conf.lo.disable_ipv6=0"],
        ]
        for c in cmds:
            rc, out = run_cmd(c, timeout=6)
            if rc != 0:
                ok = False
                if out:
                    self.log_safe(out)
        self.log_safe("IPv6: aktiviert (sysctl; nicht persistent nach Reboot).")
        if refresh_ui:
            self.refresh_safe()
        return ok

    # ---------- Network detect ----------
    def get_default_iface(self):
        _, out = run_cmd(["ip", "route", "show", "default"], timeout=3)
        parts = out.split()
        for i, p in enumerate(parts):
            if p == "dev" and i + 1 < len(parts):
                return parts[i + 1]
        return "eth0"

    def nm_active_connections(self):
        _, out = run_cmd(
            ["nmcli", "-t", "-f", "NAME,DEVICE", "con", "show", "--active"], timeout=5
        )
        res = []
        for line in (out or "").splitlines():
            if ":" in line:
                n, d = line.split(":", 1)
                if n and d:
                    res.append((n, d))
        return res

    def nm_active_conn_for_dev(self, dev: str):
        for n, d in self.nm_active_connections():
            if d == dev:
                return n
        return None

    def check_internet(self):
        if has_cmd("nmcli"):
            try:
                rc, out = run_cmd(
                    ["nmcli", "-t", "-f", "CONNECTIVITY", "general"], timeout=4
                )
                if rc == 0:
                    connectivity = (out or "").strip().splitlines()
                    state = (connectivity[0] if connectivity else "").strip().lower()
                    if state == "full":
                        return True
            except Exception:
                pass

        try:
            for target in ("1.1.1.1", "8.8.8.8"):
                p = subprocess.run(
                    ["ping", "-c", "1", "-W", "1", target],
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                    timeout=2,
                    check=False,
                    text=True,
                )
                if p.returncode == 0:
                    return True
        except Exception:
            pass
        return False

    def _internet_transition_active(self):
        if self._dns_runtime_transition_active():
            return True
        active_operation = str(self.__dict__.get("network_active_operation") or "")
        active_operation = active_operation.strip().lower()
        return bool(
            active_operation
            and any(token in active_operation for token in ("vpn", "internet", "dns"))
        )

    def _update_internet_indicator_state(self, inet_ok: bool):
        if self._internet_transition_active():
            self.__dict__["internet_indicator_state"] = "transition"
            return "transition"

        if inet_ok:
            self.__dict__["internet_fail_streak"] = 0
            self.__dict__["internet_indicator_state"] = "ok"
            return "ok"

        fail_streak = int(self.__dict__.get("internet_fail_streak", 0)) + 1
        self.__dict__["internet_fail_streak"] = fail_streak
        state = "warning" if fail_streak == 1 else "error"
        self.__dict__["internet_indicator_state"] = state
        return state

    def _clear_internet_suspend_request(self):
        self.__dict__["internet_suspend_requested"] = False
        self.__dict__["internet_suspend_until"] = 0.0
        self.__dict__["internet_suspend_logged_reactivation"] = False

    def _local_internet_available_for_suspend(self):
        if has_cmd("nmcli"):
            rc, out = run_cmd(["nmcli", "networking"], timeout=4)
            if rc == 0:
                state = (out or "").strip().lower()
                if state in {"off", "disabled"}:
                    return False

        rc, out = run_cmd(["ip", "route", "show", "default"], timeout=3)
        if rc != 0:
            return None
        return bool((out or "").strip())

    def _internet_suspend_indicator_override(self):
        if not bool(self.__dict__.get("internet_suspend_requested", False)):
            return None

        now = time.time()
        deadline = float(self.__dict__.get("internet_suspend_until", 0.0) or 0.0)
        local_available = self._local_internet_available_for_suspend()

        if local_available is False:
            self.__dict__["internet_fail_streak"] = 0
            self.__dict__["internet_indicator_state"] = "suspended"
            self._clear_internet_suspend_request()
            return "suspended"

        if now < deadline:
            self.__dict__["internet_indicator_state"] = "transition"
            return "transition"

        self._clear_internet_suspend_request()
        if local_available is True:
            self.log(
                "Internet AUS: Netzwerk wurde durch VPN/NetworkManager wieder aktiv."
            )
        return None

    def _debug_log_system_cmd(self, cmd, rc, out):
        parts = [
            str(part or "").strip() for part in (cmd or []) if str(part or "").strip()
        ]
        filtered = [part for part in parts if part not in {"sudo", "-n"}]
        if self._should_suppress_repeated_debug_cmd(filtered, rc, out):
            return
        tool = filtered[0] if filtered else ""
        if tool == "wg":
            prefix = "WG"
        elif tool == "nmcli":
            prefix = "NM"
        else:
            prefix = "NET"
        rendered_cmd = " ".join(parts)
        text = str(out or "").strip()
        if not text:
            rendered_out = "-"
        else:
            lines = [line.rstrip() for line in text.splitlines() if line.strip()]
            if len(lines) <= 1:
                rendered_out = lines[0] if lines else "-"
            else:
                rendered_out = "\n" + "\n".join(f"    {line}" for line in lines)
        self.log_network_debug(f"[VPN][{prefix}] cmd: {rendered_cmd}")
        self.log_network_debug(f"[VPN][{prefix}] rc: {rc}")
        self.log_network_debug(f"[VPN][{prefix}] out: {rendered_out}")

    def _should_suppress_repeated_debug_cmd(self, filtered_cmd, rc, out):
        noisy_poll_commands = {
            ("wg", "show", "interfaces"),
            ("nmcli", "-t", "-f", "NAME,TYPE", "connection", "show"),
            ("nmcli", "-t", "-f", "NAME,TYPE", "connection", "show", "--active"),
        }
        cmd_key = tuple(filtered_cmd or [])
        if cmd_key not in noisy_poll_commands:
            return False

        snapshot = (int(rc), (out or "").strip() or "-")
        now = time.time()
        state = self.__dict__.setdefault("_debug_cmd_repeat_state", {})
        previous = state.get(cmd_key)
        state[cmd_key] = (snapshot, now)
        if previous is None:
            return False

        previous_snapshot, previous_ts = previous
        return previous_snapshot == snapshot and (now - previous_ts) < 30.0

    def debug_nm_state(self, context=""):
        label = f" ({context})" if str(context or "").strip() else ""
        wg_profiles = list(self.__dict__.get("wg_profiles", []) or [])
        current_vpn = (self.get_current_vpn_profile() or "").strip() or "-"
        current_wg_iface = (self.get_wg_iface() or "").strip() or "-"
        vpn_text = "VPN aus" if current_vpn == "-" else f"VPN {current_vpn}"
        wg_text = (
            "kein WG-Interface" if current_wg_iface == "-" else f"WG {current_wg_iface}"
        )
        if not has_cmd("nmcli"):
            self.log_safe(
                f"Netzwerkstatus{label}: {vpn_text}, {wg_text}, "
                f"{len(wg_profiles)} Profile geladen, NetworkManager nicht verfügbar"
            )
            return

        try:
            rc_all, out_all = run_cmd(
                ["nmcli", "-t", "-f", "NAME,TYPE,DEVICE,STATE", "connection", "show"],
                timeout=10,
            )
            rc_active, out_active = run_cmd(
                [
                    "nmcli",
                    "-t",
                    "-f",
                    "NAME,TYPE,DEVICE,STATE",
                    "connection",
                    "show",
                    "--active",
                ],
                timeout=10,
            )
        except Exception as exc:
            self.log_safe(
                f"Netzwerkstatus{label}: {vpn_text}, {wg_text}, "
                f"{len(wg_profiles)} Profile geladen, NetworkManager-Fehler: {exc}"
            )
            return

        total_connections = len(
            [line for line in (out_all or "").splitlines() if line.strip()]
        )
        active_connections = len(
            [line for line in (out_active or "").splitlines() if line.strip()]
        )
        self.log_safe(
            f"Netzwerkstatus{label}: {vpn_text}, {wg_text}, "
            f"{len(wg_profiles)} Profile geladen, "
            f"{active_connections}/{total_connections} NM-Verbindungen aktiv"
        )

    def refresh_internet_status(self):
        self.refresh()

    def _set_internet_toggle_buttons_state(self, enabled):
        state = "normal" if enabled else "disabled"
        for attr_name in ("btn_inet_off", "btn_inet_on"):
            button = self.__dict__.get(attr_name)
            if button is None:
                continue
            try:
                button.configure(state=state)
            except Exception:
                pass

    def _log_internet_toggle_state(self, label):
        if not self.__dict__.get("debug_network_logging", False):
            return

        active_wg = list(self.get_wg_interfaces() or [])
        self.log_network_debug(f"[DEBUG] {label}")
        self.log_network_debug(
            f"[DEBUG] WG active: {', '.join(active_wg) if active_wg else '-'}"
        )
        self.log_network_debug(
            "[DEBUG] Last VPN/current VPN: "
            + f"{getattr(self, 'vpn_before_internet_off', None)} / "
            + f"{(self.get_current_vpn_profile() or '').strip() or '-'}"
        )

        commands = [
            ("wg show interfaces", ["wg", "show", "interfaces"]),
            (
                "nmcli networking connectivity",
                ["nmcli", "networking", "connectivity"],
            ),
            (
                "nmcli connection show --active",
                ["nmcli", "connection", "show", "--active"],
            ),
            ("ip route", ["ip", "route"]),
        ]
        for title, cmd in commands:
            rc, out = run_cmd(cmd, timeout=10)
            body = (out or "").strip() or "-"
            self.log_network_debug(f"[DEBUG] {title} rc={rc}")
            self.log_network_debug(body)

    def wait_for_network_ready(self, timeout=20):
        deadline = time.time() + timeout
        while time.time() < deadline:
            rc_conn, out_conn = run_cmd(
                ["nmcli", "networking", "connectivity"], timeout=5
            )
            connectivity = (out_conn or "").strip().lower()
            rc_route, out_route = run_cmd(["ip", "route", "show", "default"], timeout=5)
            has_default_route = rc_route == 0 and bool((out_route or "").strip())
            if (
                rc_conn == 0
                and connectivity in {"full", "limited"}
                and has_default_route
            ):
                return True
            time.sleep(1)
        return False

    def internet_disable(self, interactive_guard=True):
        if not self._try_begin_network_operation("Internet AUS"):
            return False
        self._record_diagnostic_action(
            "Internet deaktivieren",
            "network",
            details={"interactive_guard": bool(interactive_guard)},
        )
        if interactive_guard and not self._confirm_danger_action(
            "network:internet_off",
            title=self.tr("internet_off_confirm_title", "Internet AUS bestätigen"),
            prompt=self.tr(
                "internet_off_confirm_message",
                "Diese Aktion deaktiviert Netzwerk systemweit über NetworkManager.\n"
                "Aktive Verbindungen werden getrennt.\n\n"
                "Wirklich fortfahren?",
            ),
            cooldown_s=0,
            require_phrase="AUSFUEHREN",
        ):
            self.log("Internet AUS abgebrochen.")
            self._end_network_operation()
            return False

        if not has_cmd("nmcli"):
            self.log("Internet AN/AUS nicht verfügbar: nmcli fehlt.")
            messagebox.showerror(
                self.tr(
                    "networkmanager_missing_title",
                    "NetworkManager nicht verfügbar",
                ),
                self.tr(
                    "networkmanager_missing_message",
                    "nmcli (NetworkManager) ist nicht installiert.\n"
                    "Internet AN/AUS ist nicht möglich.",
                ),
                parent=self,
            )
            self._end_network_operation()
            return False

        if not self.ensure_sudo_session("Internet deaktivieren"):
            self._end_network_operation()
            return False

        active_wg_profile = self.active_wg_profile() or ""
        active_wg_iface = (self.get_wg_iface() or "").strip()
        normalized_vpn_profile = (
            self._base_wg_profile_name(active_wg_profile)
            or self._base_wg_profile_name(active_wg_iface)
            or ""
        )
        state_coordinator = self._state_coordinator()
        if state_coordinator is not None:
            self.internet_suspend_state = (
                state_coordinator.capture_internet_suspend_state(
                    ufw_was_active=self.check_ufw_active(),
                    killswitch_was_active=self.killswitch_is_on(),
                    vpn_was_active=bool(normalized_vpn_profile or active_wg_iface),
                    vpn_profile=normalized_vpn_profile,
                    vpn_interface=active_wg_iface,
                )
            )
        else:
            self.internet_suspend_state = {
                "ufw_was_active": self.check_ufw_active(),
                "killswitch_was_active": self.killswitch_is_on(),
                "vpn_was_active": bool(normalized_vpn_profile or active_wg_iface),
                "vpn_profile": normalized_vpn_profile,
                "vpn_interface": active_wg_iface,
            }
        self.vpn_before_internet_off = normalized_vpn_profile
        self.internet_suspend_requested = True
        self.internet_suspend_until = time.time() + 10.0
        self.internet_suspend_logged_reactivation = False
        self.log("Internet AUS: NetworkManager Umschaltung gestartet.")
        self.debug_nm_state("vor Internet AUS")
        self.set_light(self.l_inet, "yellow")
        self._set_internet_toggle_buttons_state(False)

        def worker():
            self._log_internet_toggle_state("Internet AUS: Zustand vorher")
            cmd = ["sudo", "-n", "nmcli", "networking", "off"]
            rc, out = run_cmd(cmd, timeout=15)
            self._log_internet_toggle_state("Internet AUS: Zustand nachher")

            def finish():
                try:
                    self._debug_log_system_cmd(cmd, rc, out)
                    self.debug_nm_state("nach Internet AUS")
                    if rc == 0:
                        self.log_safe("Internet AUS: NetworkManager networking off")
                        self.set_light(self.l_inet, "gray")
                        self._schedule_refresh_burst(
                            delays_ms=(0, 1000, 2500, 5000, 9000)
                        )
                    else:
                        self.log_safe(f"Internet AUS Fehler: {out}")
                        self.internet_suspend_state = (
                            self._default_internet_suspend_state()
                        )
                        self.vpn_before_internet_off = ""
                        self._clear_internet_suspend_request()
                        self.set_light(self.l_inet, "red")
                        messagebox.showerror(
                            self.tr(
                                "internet_off_failed_title",
                                "Internet AUS fehlgeschlagen",
                            ),
                            self.tr(
                                "internet_off_failed_message",
                                "Netzwerk konnte nicht deaktiviert werden:\n{details}",
                            ).format(details=out),
                            parent=self,
                        )
                finally:
                    self._set_internet_toggle_buttons_state(True)
                    self._end_network_operation()

            self.after(0, finish)

        threading.Thread(target=worker, daemon=True).start()
        return True

    def internet_enable(self, interactive_guard=True):
        if not self._try_begin_network_operation("Internet AN"):
            return False
        self._record_diagnostic_action(
            "Internet aktivieren",
            "network",
            details={"interactive_guard": bool(interactive_guard)},
        )
        if interactive_guard and not self._confirm_danger_action(
            "network:internet_on",
            title=self.tr("internet_on_confirm_title", "Internet AN bestätigen"),
            prompt=self.tr(
                "internet_on_confirm_message",
                "Diese Aktion aktiviert Netzwerk systemweit über NetworkManager.\n"
                "Anschließend wird ein gespeicherter VPN/Killswitch-Zustand ggf. wiederhergestellt.\n\n"
                "Wirklich fortfahren?",
            ),
            cooldown_s=0,
            require_phrase="AUSFUEHREN",
        ):
            self.log("Internet AN abgebrochen.")
            self._end_network_operation()
            return False

        if not has_cmd("nmcli"):
            self.log("Internet AN/AUS nicht verfügbar: nmcli fehlt.")
            messagebox.showerror(
                self.tr(
                    "networkmanager_missing_title",
                    "NetworkManager nicht verfügbar",
                ),
                self.tr(
                    "networkmanager_missing_message",
                    "nmcli (NetworkManager) ist nicht installiert.\n"
                    "Internet AN/AUS ist nicht möglich.",
                ),
                parent=self,
            )
            self._end_network_operation()
            return False

        if not self.ensure_sudo_session("Internet aktivieren"):
            self._end_network_operation()
            return False

        self.log("Internet AN: NetworkManager Umschaltung gestartet.")
        self.debug_nm_state("vor Internet AN")
        self.set_light(self.l_inet, "yellow")
        self._set_internet_toggle_buttons_state(False)

        def worker():
            result = self._internet_enable_button_restore_sequence()

            def finish():
                try:
                    if result:
                        self.set_light(self.l_inet, "yellow")
                    else:
                        self.set_light(self.l_inet, "red")
                finally:
                    self._set_internet_toggle_buttons_state(True)
                    self._end_network_operation()
                    self._schedule_pending_internet_restore_retry()

            self.after(0, finish)

        threading.Thread(target=worker, daemon=True).start()
        return True

    def _default_internet_suspend_state(self):
        coordinator = self._state_coordinator()
        if coordinator is not None:
            return coordinator.default_internet_suspend_state()
        return {
            "ufw_was_active": False,
            "killswitch_was_active": False,
            "vpn_was_active": False,
            "vpn_profile": "",
            "vpn_interface": "",
        }

    def _pending_internet_restore_profile(self):
        try:
            raw_state = self.__dict__.get(
                "internet_suspend_state", self._default_internet_suspend_state()
            )
            suspend_state = dict(raw_state or {})
        except Exception:
            suspend_state = {}

        try:
            base_name = object.__getattribute__(self, "_base_wg_profile_name")
        except AttributeError:

            def base_name(value):
                return str(value or "").strip()

        profile = (
            base_name(suspend_state.get("vpn_profile", ""))
            or base_name(self.__dict__.get("vpn_before_internet_off", ""))
            or ""
        )
        vpn_was_active = bool(suspend_state.get("vpn_was_active") or profile)
        if not vpn_was_active or not profile:
            return ""

        try:
            current_vpn = bool(self.active_wg_profile() or self.get_wg_iface())
        except Exception:
            current_vpn = False
        return "" if current_vpn else profile

    def _internet_suspend_restore_profile(self):
        try:
            raw_state = self.__dict__.get(
                "internet_suspend_state", self._default_internet_suspend_state()
            )
            suspend_state = dict(raw_state or {})
        except Exception:
            suspend_state = {}

        try:
            base_name = object.__getattribute__(self, "_base_wg_profile_name")
        except AttributeError:

            def base_name(value):
                return str(value or "").strip()

        profile = (
            base_name(suspend_state.get("vpn_profile", ""))
            or base_name(self.__dict__.get("vpn_before_internet_off", ""))
            or ""
        )
        if not bool(suspend_state.get("vpn_was_active") or profile):
            return ""
        return profile

    def _schedule_pending_internet_restore_retry(self, delay_ms=6000, max_attempts=3):
        profile = self._pending_internet_restore_profile()
        if not profile:
            self.__dict__["internet_restore_retry_count"] = 0
            self.__dict__["internet_vpn_restore_active"] = False
            return False

        attempts = int(self.__dict__.get("internet_restore_retry_count", 0) or 0)
        if attempts >= max_attempts:
            self.log(
                "VPN-Wiederherstellung: automatischer Retry abgebrochen "
                f"({max_attempts} Versuche erreicht)."
            )
            return False

        attempts += 1
        self.__dict__["internet_restore_retry_count"] = attempts
        self.__dict__["internet_vpn_restore_active"] = True
        self.log(
            "VPN-Wiederherstellung: erneuter Versuch geplant "
            f"({attempts}/{max_attempts}, Profil: {profile})."
        )

        def retry():
            if self.__dict__.get("network_active_operation"):
                self.after(
                    delay_ms,
                    lambda: self._schedule_pending_internet_restore_retry(
                        delay_ms=delay_ms,
                        max_attempts=max_attempts,
                    ),
                )
                return

            def retry_job():
                self._internet_on_sync()
                self._schedule_pending_internet_restore_retry(
                    delay_ms=delay_ms,
                    max_attempts=max_attempts,
                )

            self.run_async(
                retry_job,
                job_name="Internet AN VPN-Restore Retry",
            )

        self.after(delay_ms, retry)
        return True

    def _capture_stealth_runtime_state(self):
        dns_choice_var = self.__dict__.get("dns_choice")
        dns_choice = "System (DHCP/auto)"
        if dns_choice_var is not None:
            dns_choice = (dns_choice_var.get() or "System (DHCP/auto)").strip()

        state_coordinator = self._state_coordinator()
        if state_coordinator is not None:
            return state_coordinator.capture_stealth_runtime_state(
                ipv6_was_disabled=self.ipv6_is_disabled(),
                killswitch_was_on=self.killswitch_is_on(),
                vpn_was_active=bool(self.active_wg_profile() or self.get_wg_iface()),
                vpn_profile=self.active_wg_profile() or "",
                dns_choice=dns_choice,
            )

        return {
            "ipv6_was_disabled": self.ipv6_is_disabled(),
            "killswitch_was_on": self.killswitch_is_on(),
            "vpn_was_active": bool(self.active_wg_profile() or self.get_wg_iface()),
            "vpn_profile": self.active_wg_profile() or "",
            "dns_choice": dns_choice or "System (DHCP/auto)",
        }

    def _restore_stealth_runtime_state(self, state, refresh_ui=False):
        state = state or {}
        previous_dns = (state.get("dns_choice") or "System (DHCP/auto)").strip()
        previous_vpn = (state.get("vpn_profile") or "").strip()
        previous_vpn_active = bool(state.get("vpn_was_active"))
        previous_killswitch = bool(state.get("killswitch_was_on"))
        previous_ipv6_disabled = bool(state.get("ipv6_was_disabled"))

        if not previous_killswitch and self.killswitch_is_on():
            self.killswitch_off(async_mode=False, ensure_sudo=False, refresh_ui=False)

        current_vpn_active = bool(self.active_wg_profile() or self.get_wg_iface())
        if previous_vpn_active and previous_vpn:
            if self.active_wg_profile() != self._base_wg_profile_name(previous_vpn):
                self.vpn_switch(
                    previous_vpn,
                    ensure_sudo=False,
                    refresh_ui=False,
                    force_reconnect=True,
                )
                self.wait_for_vpn_ready(timeout=12, interval=0.5)
        elif current_vpn_active:
            self.vpn_off(ensure_sudo=False, refresh_ui=False)

        if previous_ipv6_disabled:
            self.ipv6_disable(refresh_ui=False)
        else:
            self.ipv6_enable(refresh_ui=False)

        self._set_dns_choice_safe(previous_dns)
        if self._normalize_dns_profile_choice(previous_dns) == previous_dns:
            self.apply_dns(
                choice=previous_dns,
                refresh_ui=False,
                update_choice_var=False,
                confirm_dnssec=False,
            )

        if previous_killswitch and not self.killswitch_is_on():
            self.killswitch_on(async_mode=False, ensure_sudo=False, refresh_ui=False)

        if refresh_ui:
            self.refresh_safe()

    def _schedule_refresh_burst(self, delays_ms=None):
        delays = delays_ms or (0, 1500, 3000)
        for delay in delays:
            self.after(delay, self.refresh)

    def _vpn_route_uses_iface(self, iface):
        name = (iface or "").strip()
        if not name:
            return False
        rc, out = run_cmd(["ip", "route", "show", "default"], timeout=3)
        if rc != 0:
            return False
        for line in (out or "").splitlines():
            if f" dev {name}" in f" {line} ":
                return True
        return False

    def _check_public_ip_quick(self):
        if not has_cmd("curl"):
            return False
        rc, out = run_cmd(
            ["curl", "-4", "-fsS", "--max-time", "3", "https://api.ipify.org"],
            timeout=4,
        )
        if rc != 0:
            return False
        ip = (out or "").strip()
        try:
            ipaddress.ip_address(ip)
            return True
        except Exception:
            return False

    def wait_for_vpn_ready(self, timeout=15, interval=0.5):
        return vpn_controller.wait_for_vpn_ready(
            self,
            timeout=timeout,
            interval=interval,
        )

    def _internet_on_sync(self):
        if not self._try_begin_network_operation("Internet AN"):
            return False
        try:
            return self._internet_on_restore_sequence()
        finally:
            self._end_network_operation()

    def _internet_on_restore_sequence(self):
        rc, out = run_cmd(["sudo", "-n", "nmcli", "networking", "on"], timeout=10)
        cmd = ["sudo", "-n", "nmcli", "networking", "on"]
        self.after(
            0,
            lambda c=cmd, code=rc, output=out: self._debug_log_system_cmd(
                c, code, output
            ),
        )
        self.after(0, lambda: self.debug_nm_state("nach Internet AN"))
        if rc != 0:
            self.after(0, lambda: self.log(f"Internet AN fehlgeschlagen: {out}"))
            self.after(
                0,
                lambda: messagebox.showerror(
                    self.tr("internet_on_failed_title", "Internet AN fehlgeschlagen"),
                    self.tr(
                        "internet_on_failed_message",
                        "Netzwerk konnte nicht aktiviert werden:\n{details}",
                    ).format(details=out),
                    parent=self,
                ),
            )
            return False

        self._clear_internet_suspend_request()
        self.after(0, lambda: self.log("Internet AN: NetworkManager networking on"))
        restore_profile_hint = self._internet_suspend_restore_profile()
        initial_network_timeout = 5 if restore_profile_hint else 20
        network_ready = self.wait_for_network_ready(timeout=initial_network_timeout)
        self.after(
            0,
            lambda ready=network_ready, restore_hint=restore_profile_hint: self.log(
                "Internet AN: NetworkManager bereit."
                if ready
                else (
                    "Internet AN: NetworkManager noch nicht stabil, VPN-Restore setzt mit WG-Reset fort."
                    if restore_hint
                    else "Internet AN: NetworkManager wurde nicht rechtzeitig stabil."
                )
            ),
        )
        self.after(0, lambda: self.log("Internet systemweit aktiviert."))
        time.sleep(1)

        def _noop_state_coordinator_factory():
            return None

        def _fallback_base_wg_profile_name(profile):
            return str(profile or "").strip()

        try:
            state_coordinator_factory = object.__getattribute__(
                self, "_state_coordinator"
            )
        except AttributeError:
            state_coordinator_factory = _noop_state_coordinator_factory
        try:
            base_wg_profile_name = object.__getattribute__(
                self, "_base_wg_profile_name"
            )
        except AttributeError:
            base_wg_profile_name = _fallback_base_wg_profile_name

        state_coordinator = state_coordinator_factory()
        raw_suspend_state = self.__dict__.get(
            "internet_suspend_state", self._default_internet_suspend_state()
        )
        if state_coordinator is not None:
            suspend_state = state_coordinator.normalize_internet_suspend_state(
                raw_suspend_state
            )
        else:
            suspend_state = dict(raw_suspend_state or {})

        fallback_profile = (
            base_wg_profile_name(self.__dict__.get("vpn_before_internet_off", "")) or ""
        )
        if fallback_profile and not str(suspend_state.get("vpn_profile") or "").strip():
            suspend_state["vpn_profile"] = fallback_profile
            suspend_state["vpn_was_active"] = True

        killswitch_was_active = bool(suspend_state.get("killswitch_was_active"))
        vpn_was_active = bool(suspend_state.get("vpn_was_active"))
        profile_to_restore = (
            base_wg_profile_name(suspend_state.get("vpn_profile", "")) or ""
        )
        if vpn_was_active and profile_to_restore:
            self.__dict__["internet_vpn_restore_active"] = True
        restore_complete = True
        vpn_restore_ok = False
        killswitch_temporarily_disabled = False
        killswitch_kept_active_for_restore = bool(
            killswitch_was_active and vpn_was_active and profile_to_restore
        )
        wg_cleanup_done = False
        wg_cleanup_ok = None

        if vpn_was_active and profile_to_restore:
            self.after(
                0,
                lambda: self.log(
                    "Internet AN: WG Cleanup vor VPN-Wiederherstellung gestartet."
                ),
            )
            wg_cleanup_done = True
            wg_cleanup_ok = self.cleanup_wireguard_interfaces()
            if not wg_cleanup_ok:
                self.after(
                    0,
                    lambda: self.log(
                        "Internet AN: WG Cleanup war nicht vollständig vor Restore."
                    ),
                )

        if killswitch_kept_active_for_restore:
            self.after(
                0,
                lambda: self.log(
                    "Killswitch bleibt während der VPN-Wiederherstellung aktiv."
                ),
            )
        elif killswitch_was_active and self.killswitch_is_on():
            if self.killswitch_off(
                async_mode=False,
                ensure_sudo=False,
                refresh_ui=False,
            ):
                killswitch_temporarily_disabled = True
                self.after(
                    0,
                    lambda: self.log(
                        "Killswitch für Internet- und VPN-Wiederherstellung vorübergehend deaktiviert."
                    ),
                )
            else:
                restore_complete = False
                self.after(
                    0,
                    lambda: self.log(
                        "Killswitch konnte vor der VPN-Wiederherstellung nicht deaktiviert werden."
                    ),
                )

        if (
            vpn_was_active
            and profile_to_restore
            and not network_ready
            and (wg_cleanup_done or killswitch_temporarily_disabled)
        ):
            self.after(
                0,
                lambda: self.log(
                    "Internet AN: warte nach WG/Killswitch-Reset erneut auf NetworkManager."
                ),
            )
            network_ready = self.wait_for_network_ready(timeout=20)
            self.after(
                0,
                lambda ready=network_ready: self.log(
                    "Internet AN: NetworkManager nach Reset bereit."
                    if ready
                    else "Internet AN: NetworkManager nach Reset noch nicht stabil."
                ),
            )

        if vpn_was_active:
            restore_complete = False
            if profile_to_restore and network_ready:
                if self._network_operation_active_elsewhere():
                    self.after(
                        0,
                        lambda: self.log(
                            "VPN-Wiederherstellung wird nach Abschluss von Internet AN erneut versucht."
                        ),
                    )
                else:
                    self.after(
                        0,
                        lambda: self.log(
                            f"VPN-Wiederherstellung gestartet (Profil: {profile_to_restore})."
                        ),
                    )
                    if not wg_cleanup_done:
                        cleanup_ok = self.cleanup_wireguard_interfaces()
                        wg_cleanup_ok = cleanup_ok
                        if not cleanup_ok:
                            self.after(
                                0,
                                lambda: self.log(
                                    "Internet AN: WG Cleanup war nicht vollständig vor Restore."
                                ),
                            )
                    if wg_cleanup_done and wg_cleanup_ok:
                        self.after(
                            0,
                            lambda: self.log(
                                "Internet AN: WG Cleanup abgeschlossen, VPN-Reconnect folgt."
                            ),
                        )
                    vpn_ok = self.vpn_switch(
                        profile_to_restore,
                        ensure_sudo=False,
                        refresh_ui=False,
                        force_reconnect=True,
                        skip_cleanup=bool(wg_cleanup_done and wg_cleanup_ok),
                    )
                    ready_ok = self.wait_for_vpn_ready() if vpn_ok else False
                    if vpn_ok and ready_ok:
                        vpn_restore_ok = True
                        restore_complete = True
                        self.internet_restore_retry_count = 0
                        self.internet_vpn_restore_active = False
                        self.vpn_before_internet_off = ""
                        self.after(0, lambda: self.log("VPN-Tunnel ist bereit."))
                    else:
                        self.after(
                            0, lambda: self.log("VPN-Wiederherstellung fehlgeschlagen.")
                        )
                        if not vpn_ok:
                            self.after(
                                0,
                                lambda: self.log_debug_safe(
                                    "VPN-Wiederherstellung: Reconnect-Aufruf fehlgeschlagen."
                                ),
                            )
                        elif not ready_ok:
                            self.after(
                                0,
                                lambda: self.log_debug_safe(
                                    "VPN-Wiederherstellung: Tunnel wurde innerhalb des Zeitlimits nicht bereit."
                                ),
                            )
            elif profile_to_restore and not network_ready:
                restore_complete = False
                self.after(
                    0,
                    lambda: self.log(
                        "VPN-Wiederherstellung übersprungen: NetworkManager ist noch nicht bereit."
                    ),
                )

        if killswitch_was_active:
            if killswitch_kept_active_for_restore and vpn_restore_ok:
                pass
            elif vpn_restore_ok or not vpn_was_active:
                if self.killswitch_on(
                    async_mode=False, ensure_sudo=False, refresh_ui=False
                ):
                    self.after(0, lambda: self.log("Killswitch wieder aktiviert."))
                else:
                    restore_complete = False
                    self.after(
                        0,
                        lambda: self.log(
                            "Killswitch konnte nach VPN-Wiederherstellung nicht wieder aktiviert werden."
                        ),
                    )
            else:
                restore_complete = False
                if killswitch_kept_active_for_restore:
                    pass
                elif killswitch_temporarily_disabled or not self.killswitch_is_on():
                    self.after(
                        0,
                        lambda: self.log(
                            "Killswitch bleibt aus, damit Internetzugang nicht blockiert wird."
                        ),
                    )

        if state_coordinator is not None:
            self.internet_suspend_state = (
                state_coordinator.finalize_internet_restore_state(
                    suspend_state,
                    restore_complete,
                )
            )
        elif restore_complete:
            self.internet_suspend_state = self._default_internet_suspend_state()
        else:
            self.internet_suspend_state = suspend_state

        if not restore_complete:
            self.after(
                0,
                lambda: self.log(
                    "Wiederherstellungszustand bleibt gespeichert, damit der Restore erneut versucht werden kann."
                ),
            )
        self._schedule_refresh_burst()
        return True

    def _internet_enable_button_restore_sequence(self):
        self._log_internet_toggle_state("Internet AN: Zustand vorher")
        result = self._internet_on_restore_sequence()
        self._log_internet_toggle_state("Internet AN: Zustand nach Restore")
        return result

    # ---------- DNS apply ----------
    def apply_dns(
        self,
        choice=None,
        refresh_ui=True,
        update_choice_var=True,
        confirm_dnssec=True,
    ):
        selected_choice = choice
        if selected_choice is None:
            selected_choice = self.__dict__.get("dns_choice_var")
            if selected_choice is None:
                selected_choice = self.__dict__.get("dns_choice")
            try:
                selected_choice = selected_choice.get()
            except Exception:
                selected_choice = ""
        self._record_diagnostic_action(
            "DNS anwenden",
            "dns",
            details={
                "choice": str(selected_choice or ""),
                "refresh_ui": bool(refresh_ui),
                "update_choice_var": bool(update_choice_var),
                "confirm_dnssec": bool(confirm_dnssec),
            },
        )
        return dns_controller.apply_dns(
            self,
            choice=choice,
            refresh_ui=refresh_ui,
            update_choice_var=update_choice_var,
            confirm_dnssec=confirm_dnssec,
        )

    def show_dns_status(self):
        self.nb.select(self.tab_dns)
        self.log(self.tr("dns_log_status_updated", "DNS-Status aktualisiert"))
        if not has_cmd("nmcli"):
            self.update_dns_output(
                "=== DNS Status (nmcli) ===\n"
                "Ergebnis: fehlgeschlagen\nDetails: nmcli fehlt – NetworkManager ist nicht verfügbar."
            )
            return
        iface = self.get_default_iface()
        _, out = run_cmd(["nmcli", "dev", "show", iface], timeout=8)
        if not out:
            self.update_dns_output(
                "=== DNS Status (nmcli) ===\n"
                f"Interface: {iface}\nErgebnis: keine Ausgabe"
            )
            return
        lines = [ln for ln in out.splitlines() if "IP4.DNS" in ln or "IP4.DOMAIN" in ln]
        body = "\n".join(lines) if lines else out
        self.update_dns_output(
            "=== DNS Status (nmcli) ===\n" f"Interface: {iface}\n\n{body}"
        )

    # ---------- DNS Consistency check ----------
    def enable_dns_consistency_test(self):
        was_enabled = self.dns_consistency_enabled
        self.dns_consistency_enabled = True
        self.dns_consistency_one_shot = False
        self.last_dns_consistency_ok = None
        self.last_dns_consistency_ts = 0.0
        self.nb.select(self.tab_dns)
        self.update_dns_output(
            "=== DNS-Konsistenztest ===\nStatus: gestartet\n"
            f"Zeit: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}"
        )
        self.log(
            self.tr(
                "dns_log_consistency_started",
                "DNS-Konsistenztest gestartet",
            )
        )
        self.refresh()
        if not was_enabled or not self.dns_consistency_running:
            self.dns_consistency_check_async(force=True)

    def disable_dns_consistency_test(self):
        self.dns_consistency_enabled = False
        self.dns_consistency_one_shot = False
        self.last_dns_consistency_ok = None
        self.last_dns_consistency_ts = 0.0
        self.nb.select(self.tab_dns)
        self.update_dns_output(
            "=== DNS-Konsistenztest ===\nStatus: gestoppt\n"
            f"Zeit: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}"
        )
        self.log(
            self.tr(
                "dns_log_consistency_stopped",
                "DNS-Konsistenztest gestoppt",
            )
        )
        self.refresh()

    def _build_dns_consistency_result_text(
        self,
        *,
        timestamp,
        profile,
        sys_ok,
        http_ok,
        selected_servers,
        explicit_results,
        overall_status,
        dns_status_label,
        summary_label,
        killswitch_active,
        vpn_active,
    ):
        lines = [
            "=== DNS-Konsistenztest ===",
            f"Zeit: {timestamp}",
            f"Profil: {profile}",
            "",
            "[System]",
            (
                "✔ System-DNS antwortet korrekt"
                if sys_ok
                else "✖ System-DNS antwortet nicht"
            ),
        ]

        if selected_servers:
            lines.extend(["", "[Profilserver]"])
            explicit_map = {
                self.normalize_dns_value(server): ok
                for server, ok in explicit_results
                if self.normalize_dns_value(server)
            }
            for server in selected_servers:
                ok = explicit_map.get(self.normalize_dns_value(server), False)
                lines.append(
                    f"{'✔' if ok else '✖'} {server} {'erreichbar' if ok else 'nicht erreichbar'}"
                )

        lines.extend(["", "=== Ergebnis ===", f"{dns_status_label}: {summary_label}"])
        if http_ok is None:
            lines.append("○ HTTP-Test: übersprungen (curl fehlt)")
        else:
            lines.append(
                f"{'✔' if http_ok else '✖'} HTTP-Test: {'OK' if http_ok else 'blockiert'}"
            )
        lines.append(f"{overall_status}: {summary_label}")

        if killswitch_active and not vpn_active:
            lines.append(
                "Hinweis: Killswitch ist AN – ohne VPN evtl. kein Internet (gewollt)."
            )

        return "\n".join(lines)

    def dns_consistency_check_async(self, force=False):
        if not self.dns_consistency_enabled and not force:
            return
        if self.dns_consistency_running:
            return
        if not force and (time.time() - self.last_dns_consistency_ts) < 30:
            return

        if not (has_cmd("dig") or has_cmd("nslookup")):
            self.nb.select(self.tab_dns)
            self.update_dns_output(
                "=== DNS-Konsistenztest ===\n"
                "Ergebnis: nicht ausführbar\n"
                "Details: weder 'dig' noch 'nslookup' gefunden. Install: sudo apt install dnsutils"
            )
            self.log(
                self.tr(
                    "dns_log_consistency_start_failed",
                    "DNS-Konsistenztest konnte nicht gestartet werden",
                )
            )
            self.last_dns_consistency_ok = None
            self.last_dns_consistency_ts = time.time()
            return

        self.dns_consistency_running = True
        choice = self.dns_choice.get()

        def job():
            try:
                selected = self._dns_servers_for_choice(choice)
                selected_addresses = [
                    self.normalize_dns_value(server)
                    for server in selected
                    if self.normalize_dns_value(server)
                ]
                test_domain = "example.com"
                killswitch_active = self.killswitch_is_on()
                vpn_active = bool(self.active_wg_profile())

                def sys_query():
                    if has_cmd("dig"):
                        _, out = run_cmd(
                            ["dig", "+time=2", "+tries=1", "+short", "A", test_domain],
                            timeout=5,
                        )
                        return out.strip()
                    _, out = run_cmd(["nslookup", "-timeout=2", test_domain], timeout=5)
                    return out.strip()

                def explicit_query(server: str):
                    if has_cmd("dig"):
                        _, out = run_cmd(
                            [
                                "dig",
                                "+time=2",
                                "+tries=1",
                                "+short",
                                "A",
                                test_domain,
                                f"@{server}",
                            ],
                            timeout=5,
                        )
                        return out.strip()
                    _, out = run_cmd(
                        ["nslookup", "-timeout=2", test_domain, server], timeout=5
                    )
                    return out.strip()

                def http_query():
                    if not has_cmd("curl"):
                        return None
                    rc, _ = run_cmd(
                        ["curl", "-fsS", "--max-time", "4", "https://example.com"],
                        timeout=6,
                    )
                    return rc == 0

                sys_ok = bool(sys_query())
                http_ok = http_query()
                timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

                if not selected:
                    self.last_dns_consistency_ok = None
                    self.last_dns_consistency_ts = time.time()
                    detail_text = self._build_dns_consistency_result_text(
                        timestamp=timestamp,
                        profile=choice,
                        sys_ok=sys_ok,
                        http_ok=http_ok,
                        selected_servers=[],
                        explicit_results=[],
                        overall_status="○ Gesamtstatus",
                        dns_status_label=(
                            "✔ DNS-Auflösung" if sys_ok else "✖ DNS-Auflösung"
                        ),
                        summary_label="OK" if sys_ok else "NICHT TESTBAR",
                        killswitch_active=killswitch_active,
                        vpn_active=vpn_active,
                    )

                    def show_auto_result():
                        self.update_dns_output(detail_text, append=True)
                        self.log("DNS-Konsistenztest aktualisiert")

                    self.after(0, show_auto_result)
                    return

                explicit_results = [
                    (server, bool(explicit_query(server)))
                    for server in selected_addresses
                ]
                any_explicit_ok = any(ok for _, ok in explicit_results)
                dns_ok = sys_ok or any_explicit_ok

                if (not sys_ok) and (not any_explicit_ok):
                    self.last_dns_consistency_ok = None
                    self.last_dns_consistency_ts = time.time()
                    detail_text = self._build_dns_consistency_result_text(
                        timestamp=timestamp,
                        profile=choice,
                        sys_ok=sys_ok,
                        http_ok=http_ok,
                        selected_servers=list(selected),
                        explicit_results=explicit_results,
                        overall_status="✖ Gesamtstatus",
                        dns_status_label="✖ DNS-Auflösung",
                        summary_label="NICHT TESTBAR",
                        killswitch_active=killswitch_active,
                        vpn_active=vpn_active,
                    )

                    def show_no_dns_result():
                        self.update_dns_output(detail_text, append=True)
                        self.log("DNS-Konsistenztest aktualisiert")

                    self.after(0, show_no_dns_result)
                    return

                ok = sys_ok and any_explicit_ok
                self.last_dns_consistency_ok = ok
                self.last_dns_consistency_ts = time.time()
                detail_text = self._build_dns_consistency_result_text(
                    timestamp=timestamp,
                    profile=choice,
                    sys_ok=sys_ok,
                    http_ok=http_ok,
                    selected_servers=list(selected),
                    explicit_results=explicit_results,
                    overall_status=("✔ Gesamtstatus" if ok else "○ Gesamtstatus"),
                    dns_status_label="✔ DNS-Auflösung" if dns_ok else "✖ DNS-Auflösung",
                    summary_label=("STABIL" if ok else "EINGESCHRÄNKT"),
                    killswitch_active=killswitch_active,
                    vpn_active=vpn_active,
                )

                def show_result():
                    self.update_dns_output(detail_text, append=True)
                    self.log("DNS-Konsistenztest aktualisiert")

                self.after(0, show_result)

            finally:
                self.dns_consistency_running = False
                if self.__dict__.get("dns_consistency_one_shot", False):
                    self.dns_consistency_one_shot = False
                    self.dns_consistency_enabled = False
                    self.after(0, lambda: self.log("DNS-Konsistenztest gestoppt"))
                self._update_dns_consistency_light_safe()

        threading.Thread(target=job, daemon=True).start()

