    def open_ufw_log_file(self):
        target = "/var/log/ufw.log"
        if not os.path.exists(target):
            try:
                self.log_safe(f"UFW Log nicht gefunden: {target}")
            except Exception:
                pass
            try:
                messagebox.showerror(
                    "UFW Log öffnen",
                    f"Die Datei wurde nicht gefunden:\n{target}",
                    parent=self,
                )
            except Exception:
                pass
            return False
        if not shutil.which("xdg-open"):
            try:
                self.log_safe("UFW Log öffnen nicht verfügbar: xdg-open fehlt.")
            except Exception:
                pass
            return False
        try:
            subprocess.Popen(
                ["xdg-open", target],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
            self.log_safe(f"UFW Log geöffnet: {target}")
            return True
        except Exception as exc:
            try:
                self.log_safe(f"UFW Log konnte nicht geöffnet werden: {exc}")
            except Exception:
                pass
            return False

    def clear_ufw_log_file(self):
        target = "/var/log/ufw.log"
        if not os.path.exists(target):
            try:
                self.log_safe(f"UFW Log nicht gefunden: {target}")
            except Exception:
                pass
            return False
        if not messagebox.askyesno(
            "UFW Log leeren",
            "Soll die UFW-Logdatei wirklich geleert werden?\n\n"
            f"{target}\n\n"
            "Die Datei bleibt bestehen, aber ihr Inhalt wird gelöscht.",
            parent=self,
        ):
            return False
        if not self.ensure_sudo_session("UFW Log leeren"):
            return False

        rc, out = run_cmd(["sudo", "-n", "truncate", "-s", "0", target], timeout=10)
        if rc != 0:
            try:
                self.log_safe(
                    "UFW Log konnte nicht geleert werden: "
                    + (str(out or "").strip() or f"Rückgabecode {rc}")
                )
            except Exception:
                pass
            return False

        try:
            self.log_safe(f"UFW Log geleert: {target}")
        except Exception:
            pass
        try:
            self.refresh_firewall_transparency_view()
        except Exception:
            pass
        return True

