    # ---------- Trace (Table of hops) ----------
    def _hop_lookup_log_once(self, ip: str, message: str):
        key = f"{ip}:{message}"
        if key in self.hop_lookup_warned_ips:
            return
        self.hop_lookup_warned_ips.add(key)
        try:
            self.after(0, lambda m=message: self.log(m))
        except RuntimeError:
            pass

    def hop_lookup(self, ip: str, enabled=None):
        ip = (ip or "").strip()
        if not ip or ip == "*" or ":" in ip:
            return "-", "unbekannt"

        if ip in self.hop_cache:
            return self.hop_cache[ip]

        lookup_enabled = self.hop_lookup_enabled.get() if enabled is None else enabled
        if not lookup_enabled:
            return "-", "-"

        rc, out = run_cmd(
            ["curl", "-s", "--max-time", "3", f"https://ipwho.is/{ip}"], timeout=5
        )
        if rc != 0 or not out:
            self.hop_cache[ip] = ("-", "unbekannt")
            self._hop_lookup_log_once(
                ip,
                f"Hop Lookup: keine Daten für {ip} (Netzwerk/Timeout).",
            )
            return self.hop_cache[ip]

        try:
            data = json.loads(out)
            if not data.get("success", True):
                self.hop_cache[ip] = ("-", "unbekannt")
                msg = (data.get("message") or "").strip()
                if msg:
                    self._hop_lookup_log_once(ip, f"Hop Lookup: {ip} -> {msg}")
                return self.hop_cache[ip]

            cc = (data.get("country_code") or data.get("country") or "").strip()
            org = (
                data.get("org")
                or data.get("connection", {}).get("org")
                or data.get("connection", {}).get("isp")
                or ""
            ).strip()
            if not cc:
                cc = "-"
            if not org:
                org = "unbekannt"
            self.hop_cache[ip] = (cc, org)
            return cc, org
        except Exception:
            self.hop_cache[ip] = ("-", "unbekannt")
            self._hop_lookup_log_once(ip, f"Hop Lookup: ungültige Antwort für {ip}.")
            return self.hop_cache[ip]

    def clear_trace_output(self):
        table_widget = getattr(self, "trace_table", None)
        if table_widget is not None:
            try:
                table_widget.delete(*table_widget.get_children())
            except Exception:
                pass
        text_widget = getattr(self, "trace_text", None)
        if text_widget is not None:
            try:
                text_widget.delete("1.0", "end")
            except Exception:
                pass
        self.trace_last_output = ""
        try:
            self.trace_summary_var.set("Trace-Bewertung wurde geleert.")
        except Exception:
            pass
        self.log("Trace: Anzeige geleert.")

    def prepare_trace_chad_analysis(self):
        target = (self.trace_target.get() or "").strip()
        summary_text = ""
        try:
            summary_text = str(self.trace_summary_var.get() or "").strip()
        except Exception:
            summary_text = ""
        table_text = ""
        table_widget = getattr(self, "trace_table", None)
        if table_widget is not None:
            try:
                rows = list(table_widget.get_children())
            except Exception:
                rows = []
            lines = []
            for item_id in rows:
                try:
                    values = list(table_widget.item(item_id, "values") or [])
                except Exception:
                    values = []
                if values:
                    lines.append(
                        " | ".join(str(value or "").strip() for value in values)
                    )
            table_text = "\n".join(lines).strip()

        if not summary_text and not table_text and not self.trace_last_output:
            self.log("Trace: Keine Daten für Chad Analyse vorhanden.")
            return

        analysis_text = "\n".join(
            [
                "Trace Analyse",
                f"Ziel: {target or '-'}",
                "",
                "Trace Bewertung",
                summary_text or "Keine Bewertung vorhanden.",
                "",
                "Trace Tabelle",
                table_text or "Keine Hop-Tabelle vorhanden.",
                "",
                "Traceroute Rohausgabe",
                self.trace_last_output or "Keine Rohausgabe vorhanden.",
            ]
        )
        self.prepare_chad_analysis("Trace Analyse", analysis_text)

    def summarize_trace_output(
        self, target: str, rows: list[tuple], rc: int, out: str
    ) -> str:
        if not str(out or "").strip():
            return (
                f"Ziel: {target}\n"
                "Status: Keine Ausgabe\n"
                "Einordnung: traceroute hat keine auswertbare Ausgabe geliefert."
            )

        if not rows:
            return (
                f"Ziel: {target}\n"
                f"Status: {'Fehler' if rc != 0 else 'Keine Hops'}\n"
                "Einordnung: Es konnten keine auswertbaren Hops aus der Traceroute gelesen werden."
            )

        total_hops = len(rows)
        responsive_rows = [row for row in rows if str(row[1] or "").strip() != "*"]
        unresolved_rows = [row for row in rows if str(row[1] or "").strip() == "*"]
        last_reachable = responsive_rows[-1] if responsive_rows else None
        target_reached = any(str(row[1] or "").strip() == target for row in rows)

        if target_reached or (rc == 0 and last_reachable is not None):
            status = "Ziel erreichbar"
            assessment = "Die Route liefert auswertbare Hops bis zum Ziel oder bis zum letzten bekannten Zielpfad."
        elif responsive_rows:
            status = "Teilweise erreichbar"
            assessment = "Traceroute zeigt einen Teil des Pfads, endet aber vor dem eigentlichen Ziel."
        else:
            status = "Nicht erreichbar"
            assessment = "Es wurden keine antwortenden Hops erkannt."

        notes = [
            f"Erkannte Hops: {total_hops}",
            f"Antwortende Hops: {len(responsive_rows)}",
        ]
        if last_reachable is not None:
            notes.append(
                f"Letzter erreichbarer Hop: {last_reachable[0]} ({last_reachable[1]})"
            )
        if unresolved_rows:
            notes.append(f"Nicht antwortende Hops: {len(unresolved_rows)}")
            notes.append(
                "Hinweis: Einzelne '*' oder fehlende Zwischenhops sind oft normal, wenn Router ICMP-Antworten filtern oder begrenzen."
            )

        return "\n".join(
            [
                f"Ziel: {target}",
                f"Status: {status}",
                f"Einordnung: {assessment}",
                "",
                *notes,
            ]
        )

    def trace_table_async(self):
        manual_target = (self.trace_manual_target_var.get() or "").strip()
        combo_target = (self.trace_target.get() or "").strip()
        target = manual_target or combo_target
        lookup_enabled = bool(self.hop_lookup_enabled.get())
        if not target:
            self.log(
                self.tr("trace_log_enter_target", "Bitte Ziel für Trace eingeben.")
            )
            return
        if not is_safe_trace_target(target):
            self.log(
                self.tr(
                    "trace_log_invalid_target",
                    "Trace-Ziel ungültig/unsicher. Erlaubt: IP oder Hostname (ohne Sonderzeichen/Leerzeichen).",
                )
            )
            return
        if not has_cmd("traceroute"):
            self.log(
                self.tr(
                    "trace_log_traceroute_missing",
                    "Für Hops-Tabelle wird 'traceroute' benötigt (sudo apt install traceroute).",
                )
            )
            return

        def clear_table():
            for item in self.trace_table.get_children():
                self.trace_table.delete(item)

        def job():
            self.after(
                0,
                lambda: (
                    self.nb.select(self.tab_trace),
                    clear_table(),
                    self.trace_summary_var.set(
                        f"Ziel: {target}\nStatus: läuft\nEinordnung: Traceroute wird gerade ausgeführt und danach automatisch bewertet."
                    ),
                    self.log(
                        self.tr(
                            "trace_log_started",
                            "Traceroute zu {target} gestartet",
                        ).format(target=target)
                    ),
                ),
            )
            rc, out = run_cmd(
                ["traceroute", "-n", "-q", "1", "-m", "20", target], timeout=35
            )
            hops = parse_traceroute_hops(out)
            rows = []
            for h in hops:
                rtt = "" if h["rtt_ms"] is None else f"{h['rtt_ms']:.2f}"
                cc, org = self.hop_lookup(h["ip"], enabled=lookup_enabled)
                rows.append((h["hop"], h["ip"], rtt, cc or "-", org or "unbekannt"))

            def fill():
                self.nb.select(self.tab_trace)
                self.trace_last_output = out or ""
                trace_text_widget = getattr(self, "trace_text", None)
                if trace_text_widget is not None:
                    try:
                        trace_text_widget.delete("1.0", "end")
                        if out.strip():
                            trace_text_widget.insert("end", out)
                        else:
                            trace_text_widget.insert(
                                "end",
                                "Keine traceroute-Rohausgabe erhalten.\n",
                            )
                        trace_text_widget.see("1.0")
                    except Exception:
                        pass
                if not out.strip():
                    self.trace_summary_var.set(
                        self.summarize_trace_output(target, rows, rc, out)
                    )
                    self.log(
                        self.tr(
                            "trace_log_finished_no_output",
                            "Traceroute zu {target} ohne Ausgabe beendet",
                        ).format(target=target)
                    )
                    return
                if rc != 0:
                    self.log(
                        self.tr(
                            "trace_log_finished_rc",
                            "Traceroute zu {target} abgeschlossen mit rc={rc}",
                        ).format(target=target, rc=rc)
                    )
                else:
                    self.log(
                        self.tr(
                            "trace_log_finished",
                            "Traceroute zu {target} abgeschlossen",
                        ).format(target=target)
                    )

                for row in rows:
                    self.trace_table.insert("", "end", values=row)

                self.trace_summary_var.set(
                    self.summarize_trace_output(target, rows, rc, out)
                )

                if rc != 0 and not rows:
                    self.log(
                        self.tr(
                            "trace_log_no_hops",
                            "Traceroute lieferte keine auswertbaren Hops.",
                        )
                    )

            self.after(0, fill)

        threading.Thread(target=job, daemon=True).start()

    # ---------- MTR ----------
    def _parse_mtr_report(self, text: str):
        hops = []
        for raw_line in str(text or "").splitlines():
            line = ANSI_RE.sub("", raw_line).strip()
            if not line or ".|--" not in line:
                continue
            match = re.match(
                r"^\s*(\d+)\.\|--\s+(\S+)\s+(\d+(?:\.\d+)?)%\s+(\d+)\s+([0-9.]+)\s+([0-9.]+)\s+([0-9.]+)\s+([0-9.]+)\s+([0-9.]+)",
                line,
            )
            if not match:
                continue
            hops.append(
                {
                    "hop": int(match.group(1)),
                    "host": match.group(2),
                    "loss": float(match.group(3)),
                    "sent": int(match.group(4)),
                    "last": float(match.group(5)),
                    "avg": float(match.group(6)),
                    "best": float(match.group(7)),
                    "worst": float(match.group(8)),
                    "stdev": float(match.group(9)),
                }
            )
        return hops

    def summarize_mtr_output(self, target: str, text: str) -> str:
        hops = self._parse_mtr_report(text)
        if not hops:
            return (
                f"Ziel: {target}\n"
                "Einordnung: Keine auswertbare MTR-Report-Struktur erkannt."
            )

        destination = hops[-1]
        destination_loss = float(destination.get("loss", 100.0))
        destination_avg = float(destination.get("avg", 0.0))
        middle_hops = hops[1:-1] if len(hops) > 2 else []
        fully_lost_middle = [
            hop for hop in middle_hops if float(hop.get("loss", 0.0)) >= 100.0
        ]
        later_responsive = False
        for idx, hop in enumerate(hops[:-1]):
            if float(hop.get("loss", 0.0)) >= 100.0:
                later_responsive = any(
                    float(item.get("loss", 100.0)) < 100.0 for item in hops[idx + 1 :]
                )
                if later_responsive:
                    break
        all_after_bad = False
        first_bad_hop = None
        for idx, hop in enumerate(hops[:-1]):
            if float(hop.get("loss", 0.0)) >= 100.0:
                later = hops[idx + 1 :]
                if later and all(
                    float(item.get("loss", 0.0)) >= 100.0 for item in later
                ):
                    all_after_bad = True
                    first_bad_hop = hop
                    break

        status = "Unauffällig"
        assessment = "Das Ziel antwortet, und die Route wirkt grundsätzlich erreichbar."
        notes = []

        if destination_loss >= 100.0:
            status = "Kritisch"
            assessment = "Das Ziel antwortet im MTR gar nicht. Das spricht eher für ein echtes Erreichbarkeits- oder Filterproblem am Zielpfad."
        elif destination_loss > 0.0:
            status = "Auffällig"
            assessment = "Das Ziel zeigt Paketverlust. Das ist relevanter als nicht antwortende Zwischenhops und deutet auf ein echtes Transportproblem hin."
        elif all_after_bad and first_bad_hop is not None:
            status = "Auffällig"
            assessment = f"Ab Hop {first_bad_hop.get('hop')} scheint die Route durchgehend wegzubrechen. Das kann auf einen Upstream-Engpass, einen harten Filter oder ein Routingproblem hindeuten."
        elif fully_lost_middle and later_responsive:
            status = "Wahrscheinlich unkritisch"
            assessment = "Zwischenhops zeigen 100% Verlust, spätere Hops und das Ziel antworten aber weiter. Das passt typischerweise zu ICMP-Filterung oder Ratelimits auf Transit-Routern."

        if destination_loss == 0.0:
            notes.append(
                f"Zielverlust: 0% am Endziel {destination.get('host', target)}"
            )
        else:
            notes.append(
                f"Zielverlust: {destination_loss:.1f}% am Endziel {destination.get('host', target)}"
            )
        notes.append(f"Durchschnittliche Ziel-Latenz: {destination_avg:.1f} ms")
        if fully_lost_middle:
            notes.append(
                "Zwischenhops mit 100% Verlust: "
                + ", ".join(
                    f"Hop {hop.get('hop')} ({hop.get('host')})"
                    for hop in fully_lost_middle[:6]
                )
            )
        if destination_loss == 0.0 and fully_lost_middle and later_responsive:
            notes.append(
                "Hinweis: Solche '???'-Hops sind oft normal, wenn Carrier oder Provider keine ICMP-Antworten für Traceroute senden."
            )
        if destination_loss > 0.0:
            notes.append(
                "Wichtiger als mittlere Hops ist hier der Verlust am Ziel selbst."
            )

        return "\n".join(
            [
                f"Ziel: {target}",
                f"Status: {status}",
                f"Einordnung: {assessment}",
                "",
                *notes,
            ]
        )

    def mtr_async(self):
        if not has_cmd("mtr"):
            self.log(self.tr("mtr_log_missing", "MTR fehlt (sudo apt install -y mtr)."))
            return

        target = (self.mtr_target.get() or "").strip()
        if not target:
            self.log(self.tr("mtr_log_enter_target", "Bitte Ziel für MTR eingeben."))
            return
        if not is_safe_trace_target(target):
            self.log(self.tr("mtr_log_invalid_target", "MTR-Ziel ungültig/unsicher."))
            return

        self._select_tools_tab(self.tab_mtr)
        if hasattr(self, "mtr_summary_var"):
            self.mtr_summary_var.set(
                f"Ziel: {target}\nStatus: läuft\nEinordnung: MTR wird gerade ausgeführt und danach automatisch bewertet."
            )
        self.mtr_text.delete("1.0", "end")
        self.mtr_text.insert(
            "end",
            self.tr("mtr_output_starting", "MTR startet für {target}...\n").format(
                target=target
            ),
        )
        self.mtr_text.see("1.0")

        def job():
            rc, out = run_cmd(
                ["mtr", "--report", "--report-cycles", "6", "--no-dns", target],
                timeout=45,
            )

            def show():
                self._select_tools_tab(self.tab_mtr)
                self.mtr_text.delete("1.0", "end")
                if out.strip():
                    self.mtr_text.insert("end", out)
                    if hasattr(self, "mtr_summary_var"):
                        self.mtr_summary_var.set(self.summarize_mtr_output(target, out))
                else:
                    self.mtr_text.insert(
                        "end",
                        self.tr(
                            "mtr_output_none",
                            "Keine MTR-Ausgabe erhalten.",
                        ),
                    )
                    if hasattr(self, "mtr_summary_var"):
                        self.mtr_summary_var.set(
                            f"Ziel: {target}\nStatus: Keine Daten\nEinordnung: MTR hat keine auswertbare Ausgabe geliefert."
                        )
                self.mtr_text.see("1.0")
                self.log(
                    self.tr(
                        "mtr_log_finished_rc",
                        "MTR abgeschlossen für {target} (rc={rc}).",
                    ).format(target=target, rc=rc)
                )

            self.after(0, show)

        threading.Thread(target=job, daemon=True).start()

    # ---------- Nmap ----------
    def _set_nmap_running_state(self, running, status_text=None, error_text=None):
        self.nmap_running = bool(running)
        if status_text is not None:
            self.nmap_status_var.set(status_text)
        if error_text is not None:
            self.nmap_error_var.set(error_text)

        btn = self.__dict__.get("btn_nmap_start")
        if btn is not None:
            try:
                btn.configure(state="disabled" if self.nmap_running else "normal")
            except Exception:
                pass

    def _abort_nmap_process(self):
        proc = self.nmap_active_process
        if proc is None:
            return
        try:
            if proc.poll() is None:
                proc.terminate()
                try:
                    proc.wait(timeout=3)
                except Exception:
                    proc.kill()
        except Exception:
            pass

    def clear_nmap_output(self):
        self.nmap_cancel_requested = True
        self._abort_nmap_process()
        self.nmap_active_process = None
        self._set_nmap_running_state(False, status_text="bereit", error_text="")
        if hasattr(self, "nmap_text"):
            self.nmap_text.delete("1.0", "end")
        self.log(
            self.tr(
                "nmap_log_cleared",
                "Nmap-Ausgabe und Status zurückgesetzt.",
            )
        )

    def update_nmap_output(self, text):
        if not hasattr(self, "nmap_text"):
            return
        self.nmap_text.delete("1.0", "end")
        self.nmap_text.insert("end", text or "")
        self.nmap_text.see("1.0")

    def summarize_nmap_output(self, target: str, text: str, preset_label: str) -> str:
        clean_text = str(text or "").strip()
        if not clean_text:
            return (
                f"Ziel: {target}\n"
                f"Profil: {preset_label}\n"
                "Einordnung: Keine auswertbare Nmap-Ausgabe vorhanden."
            )

        host_up = "Host is up" in clean_text
        open_ports = parse_nmap_open_tcp_ports(clean_text)
        open_ports_text = (
            ", ".join(str(port) for port in open_ports[:12]) if open_ports else "-"
        )

        if "0 hosts up" in clean_text or not host_up:
            status = "Keine Antwort"
            assessment = "Das Ziel wurde in diesem Lauf nicht als erreichbar erkannt. Das kann auf Nichterreichbarkeit, Filterung oder ein unpassendes Scanprofil hindeuten."
        elif open_ports:
            status = "Erreichbar mit offenen Ports"
            assessment = "Das Ziel antwortet und zeigt offene TCP-Ports. Damit ist der Host grundsätzlich erreichbar und für weitere Detailprüfung geeignet."
        else:
            status = "Erreichbar, keine offenen TCP-Ports"
            assessment = "Das Ziel antwortet, aber im aktuellen Profil wurden keine offenen TCP-Ports gefunden. Je nach Fall kann ein anderes Profil oder ein UDP-Scan sinnvoll sein."

        lines = [
            f"Ziel: {target}",
            f"Profil: {preset_label}",
            f"Status: {status}",
            f"Einordnung: {assessment}",
            "",
            f"Offene TCP-Ports: {open_ports_text}",
        ]
        if host_up:
            lines.append("Host-Reaktion: Ziel antwortet auf den Scan.")
        if "filtered" in clean_text.lower():
            lines.append(
                "Hinweis: Gefilterte Ports/Antworten deuten häufig auf Firewalls oder Paketfilter hin."
            )
        if preset_label == "ping scan":
            lines.append(
                "Hinweis: Ping Scan bewertet primär die Erreichbarkeit und nicht die Portlandschaft."
            )
        return "\n".join(lines)

    def _collect_iftop_interfaces(self):
        interfaces = []
        if self.dep_status.get("ip"):
            rc, out = run_cmd(["ip", "-o", "link", "show"], timeout=6)
            if rc == 0:
                for line in (out or "").splitlines():
                    parts = line.split(":", 2)
                    if len(parts) < 2:
                        continue
                    name = parts[1].strip().split("@", 1)[0]
                    if name:
                        interfaces.append(name)
        unique = []
        seen = set()
        for name in interfaces:
            if name in seen:
                continue
            seen.add(name)
            unique.append(name)
        return unique

    def refresh_iftop_interfaces(self):
        interfaces = self._collect_iftop_interfaces()
        if hasattr(self, "iftop_interface_combo"):
            try:
                self.iftop_interface_combo.configure(values=interfaces)
            except Exception:
                pass
        preferred = next(
            (name for name in interfaces if name != "lo"),
            interfaces[0] if interfaces else (self.get_default_iface() or ""),
        )
        current = (self.iftop_interface_var.get() or "").strip()
        if preferred and (not current or current not in interfaces):
            self.iftop_interface_var.set(preferred)
        elif not current and preferred:
            self.iftop_interface_var.set(preferred)

    def prepare_iftop_chad_analysis(self):
        text_widget = getattr(self, "iftop_text", None)
        if text_widget is None:
            return
        try:
            snapshot_text = str(text_widget.get("1.0", "end") or "").strip()
        except Exception:
            snapshot_text = ""

        if not snapshot_text:
            self.log("iftop: Keine Snapshot-Ausgabe für Chad Analyse vorhanden.")
            return

        iface = (
            self.iftop_interface_var.get() or ""
        ).strip() or self.get_default_iface()
        duration = (self.iftop_duration_var.get() or "10").strip() or "10"
        analysis_text = "\n".join(
            [
                "iftop Snapshot",
                f"Interface: {iface or '-'}",
                f"Dauer: {duration}s",
                "",
                snapshot_text,
            ]
        )
        self.prepare_chad_analysis("iftop Analyse", analysis_text)

    def clear_iftop_output(self):
        text_widget = getattr(self, "iftop_text", None)
        if text_widget is not None:
            try:
                text_widget.delete("1.0", "end")
            except Exception:
                pass
        summary_var = getattr(self, "iftop_summary_var", None)
        if summary_var is not None:
            try:
                summary_var.set("iftop-Bewertung wurde geleert.")
            except Exception:
                pass
        self.log("iftop: Anzeige geleert.")

    def _iftop_timeout_hint(self, iface: str) -> str:
        iface_name = str(iface or "").strip()
        lowered = iface_name.lower()
        virtual_prefixes = (
            "docker",
            "br-",
            "veth",
            "virbr",
            "zt",
            "tun",
            "tap",
            "wg",
        )
        if (
            iface_name == "lo"
            or lowered.startswith(virtual_prefixes)
            or "docker" in lowered
        ):
            return (
                "Hinweis: Dieses Interface wirkt virtuell, containerbezogen oder nicht direkt angebunden. "
                "Timeouts sind dort haeufig, wenn kaum Verkehr anliegt oder iftop auf dem Interface nichts "
                "Sinnvolles erfassen kann."
            )
        return (
            "Hinweis: Ein Timeout kann auftreten, wenn auf dem Interface waehrend des Snapshots kaum Verkehr "
            "anliegt oder der Mitschnitt lokal verzoegert reagiert."
        )

    def summarize_iftop_output(
        self, iface: str, duration: str, text: str, rc: int
    ) -> str:
        clean_text = str(text or "").strip()
        lines = [
            f"Interface: {iface or '-'}",
            f"Dauer: {duration}s",
        ]

        if rc == 124:
            lines.append("Status: Timeout")
            lines.append(
                "Einordnung: Der Snapshot wurde nicht rechtzeitig abgeschlossen."
            )
            lines.append("")
            lines.append(self._iftop_timeout_hint(iface))
            return "\n".join(lines)

        if not clean_text:
            lines.append("Status: Keine Daten")
            lines.append("Einordnung: iftop hat keine auswertbare Ausgabe geliefert.")
            return "\n".join(lines)

        total_send = ""
        total_recv = ""
        total_peak = ""
        flow_lines = 0
        for raw_line in clean_text.splitlines():
            line = str(raw_line or "").strip()
            lower = line.lower()
            if "total send rate:" in lower:
                total_send = line.split(":", 1)[-1].strip()
            elif "total receive rate:" in lower:
                total_recv = line.split(":", 1)[-1].strip()
            elif "total peak rate:" in lower:
                total_peak = line.split(":", 1)[-1].strip()
            elif "=>" in line or "<=" in line:
                flow_lines += 1

        lines.append("Status: Snapshot vorhanden")
        if total_send or total_recv:
            lines.append(
                "Einordnung: Der Snapshot zeigt erkannte Bandbreitenaktivität auf dem Interface."
            )
        elif flow_lines:
            lines.append(
                "Einordnung: Es wurden Kommunikationszeilen erkannt, aber keine klaren Gesamtraten extrahiert."
            )
        else:
            lines.append(
                "Einordnung: Kaum oder keine klar auswertbare Traffic-Aktivität im Snapshot."
            )
        lines.append("")
        lines.append(f"Erkannte Flow-Zeilen: {flow_lines}")
        lines.append(f"Gesamt Send: {total_send or '-'}")
        lines.append(f"Gesamt Receive: {total_recv or '-'}")
        if total_peak:
            lines.append(f"Peak: {total_peak}")
        return "\n".join(lines)

    def clear_htop_output(self):
        text_widget = getattr(self, "htop_text", None)
        if text_widget is not None:
            try:
                text_widget.delete("1.0", "end")
            except Exception:
                pass
        table_widget = getattr(self, "htop_table", None)
        if table_widget is not None:
            try:
                table_widget.delete(*table_widget.get_children())
            except Exception:
                pass
        self.htop_current_processes = []
        self._set_htop_detail_fields(None)
        summary_var = getattr(self, "htop_summary_var", None)
        if summary_var is not None:
            try:
                summary_var.set("htop-Bewertung wurde geleert.")
            except Exception:
                pass
        self.log("htop: Anzeige geleert.")

    def _set_htop_detail_fields(self, process: dict | None):
        defaults = {
            "htop_detail_pid_var": "keine Auswahl",
            "htop_detail_name_var": "Noch kein Prozess ausgewählt.",
            "htop_detail_user_var": "keine Auswahl",
            "htop_detail_cpu_var": "keine Auswahl",
            "htop_detail_mem_var": "keine Auswahl",
            "htop_detail_status_var": "keine Auswahl",
        }
        if not process:
            for attr_name, value in defaults.items():
                getattr(self, attr_name).set(value)
            return
        self.htop_detail_pid_var.set(str(process.get("pid") or "-"))
        self.htop_detail_name_var.set(str(process.get("name") or "-"))
        self.htop_detail_user_var.set(str(process.get("user") or "-"))
        self.htop_detail_cpu_var.set(f"{process.get('cpu') or '0.0'}%")
        self.htop_detail_mem_var.set(f"{process.get('mem') or '0.0'}%")
        self.htop_detail_status_var.set(str(process.get("status") or "-"))

    def apply_htop_filters(self):
        self.update_htop_table(self.htop_current_processes)

    def clear_htop_filters(self):
        self.htop_name_filter_var.set("")
        self.htop_user_filter_var.set("")
        self.htop_pid_filter_var.set("")
        self.htop_only_active_var.set(False)
        self.update_htop_table(self.htop_current_processes)

    def on_htop_process_select(self, _event=None):
        table_widget = getattr(self, "htop_table", None)
        if table_widget is None:
            return
        selection = table_widget.selection()
        if not selection:
            self._set_htop_detail_fields(None)
            return
        item_id = selection[0]
        values = table_widget.item(item_id, "values") or ()
        if len(values) < 6:
            self._set_htop_detail_fields(None)
            return
        pid = str(values[0])
        process = next(
            (
                item
                for item in self.htop_current_processes
                if str(item.get("pid") or "") == pid
            ),
            None,
        )
        if process is None:
            process = {
                "pid": values[0],
                "name": values[1],
                "user": values[2],
                "cpu": values[3],
                "mem": values[4],
                "status": values[5],
            }
        self._set_htop_detail_fields(process)

    def prepare_htop_chad_analysis(self):
        text_widget = getattr(self, "htop_text", None)
        if text_widget is None:
            return
        try:
            snapshot_text = str(text_widget.get("1.0", "end") or "").strip()
        except Exception:
            snapshot_text = ""
        if not snapshot_text:
            self.log("htop: Keine Snapshot-Ausgabe für Chad Analyse vorhanden.")
            return
        selected_source = (
            getattr(self, "htop_source_var", None).get() or "auto"
        ).strip()
        analysis_text = "\n".join(
            [
                "htop Snapshot",
                f"Quellwahl: {selected_source}",
                "",
                snapshot_text,
            ]
        )
        self.prepare_chad_analysis("htop Analyse", analysis_text)

    def prepare_selected_htop_process_chad_analysis(self):
        table_widget = getattr(self, "htop_table", None)
        if table_widget is None:
            return
        try:
            selection = list(table_widget.selection())
        except Exception:
            selection = []
        if not selection:
            self.log("htop: Kein Prozess für Chad Analyse ausgewählt.")
            return
        item_id = selection[0]
        values = table_widget.item(item_id, "values") or ()
        if len(values) < 6:
            self.log("htop: Auswahl konnte nicht für Chad aufbereitet werden.")
            return
        pid, name, user, cpu, mem, status = values[:6]
        summary_text = ""
        try:
            summary_text = str(self.htop_summary_var.get() or "").strip()
        except Exception:
            summary_text = ""
        analysis_text = "\n".join(
            [
                "htop Prozess Analyse",
                f"PID: {pid}",
                f"Name: {name}",
                f"User: {user}",
                f"%CPU: {cpu}",
                f"%MEM: {mem}",
                f"Status: {status}",
                "",
                "htop Bewertung",
                summary_text or "Keine Bewertung vorhanden.",
            ]
        )
        self.prepare_chad_analysis("htop Prozess Analyse", analysis_text)

    def copy_htop_selection_to_clipboard(self):
        table_widget = getattr(self, "htop_table", None)
        if table_widget is None:
            return
        try:
            selection = list(table_widget.selection())
        except Exception:
            selection = []
        if not selection:
            self.log("htop: Keine Prozessauswahl zum Kopieren vorhanden.")
            return
        self.copy_treeview_selection_to_clipboard(table_widget)
        self.log(
            f"htop: {len(selection)} Prozesszeile(n) in die Zwischenablage kopiert."
        )

    def export_htop_snapshot(self):
        summary_text = ""
        raw_text = ""
        try:
            summary_text = str(self.htop_summary_var.get() or "").strip()
        except Exception:
            summary_text = ""
        text_widget = getattr(self, "htop_text", None)
        if text_widget is not None:
            try:
                raw_text = str(text_widget.get("1.0", "end") or "").strip()
            except Exception:
                raw_text = ""

        processes = list(getattr(self, "htop_current_processes", []) or [])
        if not summary_text and not raw_text and not processes:
            self.log("htop: Kein Snapshot zum Exportieren vorhanden.")
            return

        export_dir = self._security_export_dir()
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        txt_path = os.path.join(export_dir, f"netmon_htop_snapshot_{stamp}.txt")

        try:
            with open(txt_path, "w", encoding="utf-8") as fh:
                fh.write("NetMon htop Snapshot Export\n")
                fh.write(f"Zeit: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n")
                fh.write(
                    f"Quellwahl: {(self.htop_source_var.get() or 'auto').strip() or 'auto'}\n\n"
                )

                fh.write("=== Bewertung ===\n")
                fh.write((summary_text or "Keine Bewertung vorhanden.") + "\n\n")

                fh.write("=== Prozessübersicht ===\n")
                if processes:
                    for idx, process in enumerate(processes, start=1):
                        fh.write(
                            f"[{idx}] PID={process.get('pid', '-')} | "
                            f"Name={process.get('name', '-')} | "
                            f"User={process.get('user', '-')} | "
                            f"%CPU={process.get('cpu', '0.0')} | "
                            f"%MEM={process.get('mem', '0.0')} | "
                            f"Status={process.get('status', '-')}\n"
                        )
                else:
                    fh.write("Keine Prozesse erfasst.\n")
                fh.write("\n")

                fh.write("=== Rohdaten ===\n")
                fh.write((raw_text or "Keine Rohdaten vorhanden.") + "\n")
            self.log(f"htop-Snapshot exportiert: {txt_path}")
        except Exception as exc:
            self.log(f"htop-Export fehlgeschlagen: {exc}")

    def _parse_htop_snapshot_processes(self, text: str, source: str) -> list[dict]:
        clean_text = str(text or "").strip()
        if not clean_text:
            return []

        processes = []
        for raw_line in clean_text.splitlines():
            line = str(raw_line or "").strip()
            if not line:
                continue

            if source == "ps":
                parts = line.split()
                if len(parts) < 11 or parts[1] == "PID" or not parts[1].isdigit():
                    continue
                user = parts[0]
                pid = parts[1]
                cpu = parts[2]
                mem = parts[3]
                status = parts[7]
                name = " ".join(parts[10:])
            else:
                parts = line.split()
                if len(parts) < 12 or not parts[0].isdigit():
                    continue
                pid = parts[0]
                user = parts[1]
                status = parts[7]
                cpu = parts[8]
                mem = parts[9]
                name = " ".join(parts[11:])

            try:
                cpu_value = float(str(cpu).replace(",", "."))
            except Exception:
                cpu_value = 0.0
            try:
                mem_value = float(str(mem).replace(",", "."))
            except Exception:
                mem_value = 0.0

            processes.append(
                {
                    "pid": pid,
                    "user": user,
                    "cpu": cpu,
                    "cpu_value": cpu_value,
                    "mem": mem,
                    "mem_value": mem_value,
                    "status": status,
                    "name": name or "-",
                }
            )
        return processes

    def update_htop_table(self, processes: list[dict]):
        table_widget = getattr(self, "htop_table", None)
        if table_widget is None:
            return
        self.htop_current_processes = list(processes or [])
        try:
            table_widget.delete(*table_widget.get_children())
        except Exception:
            return

        name_filter = (self.htop_name_filter_var.get() or "").strip().lower()
        user_filter = (self.htop_user_filter_var.get() or "").strip().lower()
        pid_filter = (self.htop_pid_filter_var.get() or "").strip()
        only_active = bool(self.htop_only_active_var.get())

        def _sort_key(item: dict):
            return (
                -(item.get("cpu_value") or 0.0),
                -(item.get("mem_value") or 0.0),
                str(item.get("name") or ""),
            )

        visible_processes = []
        for process in sorted(processes or [], key=_sort_key):
            process_name = str(process.get("name") or "").lower()
            process_user = str(process.get("user") or "").lower()
            process_pid = str(process.get("pid") or "")
            process_status = str(process.get("status") or "").upper()
            if name_filter and name_filter not in process_name:
                continue
            if user_filter and user_filter not in process_user:
                continue
            if pid_filter and pid_filter not in process_pid:
                continue
            if only_active and not (
                (process.get("cpu_value") or 0.0) > 0.0
                or "R" in process_status
                or "D" in process_status
            ):
                continue
            visible_processes.append(process)
            try:
                table_widget.insert(
                    "",
                    "end",
                    values=(
                        process.get("pid") or "-",
                        process.get("name") or "-",
                        process.get("user") or "-",
                        process.get("cpu") or "0.0",
                        process.get("mem") or "0.0",
                        process.get("status") or "-",
                    ),
                )
            except Exception:
                continue
        self._set_htop_detail_fields(
            visible_processes[0] if visible_processes else None
        )

    def summarize_htop_output(self, text: str, source: str, rc: int) -> str:
        clean_text = str(text or "").strip()
        if not clean_text:
            return (
                f"Quelle: {source}\n"
                "Status: Keine Daten\n"
                "Einordnung: Es wurde keine auswertbare Prozessausgabe geliefert."
            )

        cpu_lines = []
        mem_lines = []
        state_markers = {"zombie": 0, "stopped": 0, "d_state": 0}
        for raw_line in clean_text.splitlines():
            line = str(raw_line or "").strip()
            lower = line.lower()
            if (
                lower.startswith("%cpu")
                or lower.startswith("cpu(s):")
                or lower.startswith("cpu:")
            ):
                cpu_lines.append(line)
            elif (
                lower.startswith("mem")
                or lower.startswith("mi b mem")
                or lower.startswith("kib mem")
            ):
                mem_lines.append(line)
        processes = self._parse_htop_snapshot_processes(clean_text, source)
        for process in processes:
            status_text = str(process.get("status") or "").upper()
            if "Z" in status_text:
                state_markers["zombie"] += 1
            if "T" in status_text:
                state_markers["stopped"] += 1
            if "D" in status_text:
                state_markers["d_state"] += 1

        status = "Snapshot vorhanden" if rc == 0 else f"Quelle {source} mit rc={rc}"
        if rc != 0:
            assessment = "Die Prozessquelle hat geantwortet, aber nicht erfolgreich abgeschlossen."
        elif state_markers["zombie"] or state_markers["d_state"]:
            assessment = "Auffällige Prozesszustände erkannt. Bitte die markierten Prozesse genauer prüfen."
        elif processes:
            top_cpu_value = max((item["cpu_value"] for item in processes), default=0.0)
            top_mem_value = max((item["mem_value"] for item in processes), default=0.0)
            if top_cpu_value >= 50.0 or top_mem_value >= 20.0:
                assessment = "Erhöhte Last durch einzelne Prozesse erkennbar."
            else:
                assessment = "Momentaufnahme der laufenden Prozesse und Systemlast ist verfügbar."
        else:
            assessment = (
                "Die Ausgabe enthält nur wenig strukturierte Last- oder Prozessdaten."
            )

        top_cpu_process = max(
            processes, key=lambda item: item["cpu_value"], default=None
        )
        top_mem_process = max(
            processes, key=lambda item: item["mem_value"], default=None
        )

        lines = [
            f"Quelle: {source}",
            f"Status: {status}",
            f"Einordnung: {assessment}",
            "",
            f"Erkannte Prozesse: {len(processes)}",
        ]
        if top_cpu_process is not None:
            lines.append(
                "Top CPU-Prozess: "
                f"{top_cpu_process['name']} (PID {top_cpu_process['pid']}, {top_cpu_process['cpu']}%)"
            )
        if top_mem_process is not None:
            lines.append(
                "Top RAM-Prozess: "
                f"{top_mem_process['name']} (PID {top_mem_process['pid']}, {top_mem_process['mem']}%)"
            )
        state_hints = []
        if state_markers["zombie"]:
            state_hints.append(f"Zombie: {state_markers['zombie']}")
        if state_markers["stopped"]:
            state_hints.append(f"Stopped: {state_markers['stopped']}")
        if state_markers["d_state"]:
            state_hints.append(f"D-State: {state_markers['d_state']}")
        if state_hints:
            lines.append("Prozesshinweise: " + " | ".join(state_hints))
        if cpu_lines:
            lines.append(f"CPU-Hinweis: {cpu_lines[0]}")
        if mem_lines:
            lines.append(f"RAM-Hinweis: {mem_lines[0]}")
        return "\n".join(lines)

    def _run_nmap_with_timeout(self, cmd, timeout):
        self.nmap_cancel_requested = False
        self.nmap_active_process = None
        try:
            proc = subprocess.Popen(
                cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
            )
            self.nmap_active_process = proc
            try:
                out, _ = proc.communicate(timeout=timeout)
                rc = proc.returncode
                if self.nmap_cancel_requested:
                    return (
                        130,
                        out
                        or self.tr("nmap_output_scan_cancelled", "Scan abgebrochen."),
                        "cancelled",
                    )
                return rc, out or "", "ok"
            except subprocess.TimeoutExpired:
                try:
                    proc.terminate()
                    out, _ = proc.communicate(timeout=3)
                except Exception:
                    try:
                        proc.kill()
                    except Exception:
                        pass
                    out = ""
                return (
                    124,
                    out
                    or self.tr("nmap_output_command_timed_out", "Command timed out"),
                    "timeout",
                )
        except FileNotFoundError:
            return (
                127,
                self.tr("nmap_output_not_found", "nmap nicht gefunden."),
                "error",
            )
        except Exception as exc:
            return (
                1,
                self.tr(
                    "nmap_output_start_failed",
                    "Nmap-Start fehlgeschlagen: {error}",
                ).format(error=exc),
                "error",
            )
        finally:
            self.nmap_active_process = None

    def nmap_async(self):
        if self.nmap_running:
            self.log(self.tr("nmap_log_already_running", "Nmap-Scan läuft bereits."))
            return

        if not has_cmd("nmap"):
            self.log(
                self.tr("nmap_log_missing", "nmap fehlt (sudo apt install -y nmap).")
            )
            return

        manual_target = (self.nmap_manual_target_var.get() or "").strip()
        combo_target = (self.nmap_target.get() or "").strip()
        target = manual_target or combo_target
        preset = (self.nmap_preset.get() or "quick").strip().lower().replace(" ", "_")
        if not target:
            self.log(
                self.tr(
                    "nmap_log_enter_target",
                    "Bitte Zielnetz/Zielhost für nmap eingeben.",
                )
            )
            return
        if not is_safe_nmap_target(target):
            self.log(self.tr("nmap_log_invalid_target", "nmap-Ziel ungültig/unsicher."))
            return

        preset_map = {
            "quick": (["-Pn", "-sT", "--top-ports", "100"], 90),
            "service": (["-Pn", "-sT", "-sV", "--top-ports", "500"], 420),
            "quick_service": (["-Pn", "-sT", "-sV", "--top-ports", "500"], 420),
            "aggressive": (["-Pn", "-sT", "-A", "--top-ports", "500"], 720),
            "ping_scan": (["-sn"], 90),
            "udp_basis": (["-Pn", "-sU", "--top-ports", "30"], 360),
        }
        preset_label_map = {
            "quick": "quick",
            "service": "service",
            "quick_service": "quick service",
            "aggressive": "aggressive",
            "ping_scan": "ping scan",
            "udp_basis": "udp basis",
        }
        preset_label = preset_label_map.get(preset, preset)
        args, timeout = preset_map.get(preset, preset_map["quick"])
        requires_sudo = preset in {"udp_basis", "aggressive"}

        if requires_sudo and not self.ensure_sudo_session(
            f"Nmap {preset_label} ausführen"
        ):
            self._set_nmap_running_state(
                False, status_text="bereit", error_text="sudo fehlt"
            )
            if hasattr(self, "nmap_summary_var"):
                self.nmap_summary_var.set(
                    f"Ziel: {target}\nProfil: {preset_label}\nEinordnung: Dieser Scan benötigt Root-Rechte und wurde nicht gestartet."
                )
            return

        self._set_nmap_running_state(
            True,
            status_text=f"läuft ({preset_label})",
            error_text="",
        )
        if hasattr(self, "nmap_summary_var"):
            self.nmap_summary_var.set(
                f"Ziel: {target}\nProfil: {preset_label}\nEinordnung: Nmap wird gerade ausgeführt und danach automatisch zusammengefasst."
            )

        def job():
            try:
                cmd = (
                    ["sudo", "-n", "nmap", *args, target]
                    if requires_sudo
                    else [
                        "nmap",
                        *args,
                        target,
                    ]
                )
                rc, out, state = self._run_nmap_with_timeout(cmd, timeout=timeout)
                open_ports = parse_nmap_open_tcp_ports(out) if rc == 0 else []
            except Exception as exc:
                rc, out, state = (
                    1,
                    self.tr(
                        "nmap_output_worker_error",
                        "Nmap-Worker-Fehler: {error}",
                    ).format(error=exc),
                    "error",
                )
                open_ports = []

            def show():
                self._select_tools_tab(self.tab_nmap)
                if out.strip():
                    display_text = out
                elif state == "timeout":
                    display_text = self.tr(
                        "nmap_output_timeout",
                        "Nmap-Scan abgebrochen: Timeout.",
                    )
                elif state == "cancelled":
                    display_text = self.tr(
                        "nmap_output_cancelled",
                        "Nmap-Scan wurde abgebrochen.",
                    )
                else:
                    display_text = self.tr(
                        "nmap_output_none",
                        "Keine nmap-Ausgabe erhalten.",
                    )
                self.update_nmap_output(display_text)
                if hasattr(self, "nmap_summary_var"):
                    self.nmap_summary_var.set(
                        self.summarize_nmap_output(target, display_text, preset_label)
                    )

                if state == "timeout":
                    self.nmap_error_var.set("Timeout")
                    self.nmap_status_var.set("bereit")
                    self.log(
                        self.tr(
                            "nmap_log_timeout",
                            "Nmap-Timeout ({preset}) für {target} nach {timeout}s.",
                        ).format(preset=preset_label, target=target, timeout=timeout)
                    )
                elif state == "cancelled":
                    self.nmap_error_var.set("Abgebrochen")
                    self.nmap_status_var.set("bereit")
                    self.log(
                        self.tr(
                            "nmap_log_cancelled",
                            "Nmap-Scan abgebrochen ({preset}) für {target}.",
                        ).format(preset=preset_label, target=target)
                    )
                else:
                    self.nmap_error_var.set("" if rc == 0 else f"Fehler rc={rc}")
                    self.nmap_status_var.set("bereit")
                    if rc != 0:
                        self.log(
                            self.tr(
                                "nmap_log_error_rc",
                                "Nmap-Fehler ({preset}) für {target}: rc={rc}.",
                            ).format(preset=preset_label, target=target, rc=rc)
                        )

                if rc == 0 and open_ports:
                    self._run_port_reality_checks_async(
                        target,
                        open_ports,
                        source_label="nmap-auto",
                    )

                self._set_nmap_running_state(False)
                self.nmap_cancel_requested = False
                self.nmap_active_process = None

            self.after(0, show)

        threading.Thread(target=job, daemon=True).start()

    # ---------- iftop ----------
    def iftop_async(self):
        if not has_cmd("iftop"):
            self.log(
                self.tr("iftop_log_missing", "iftop fehlt (sudo apt install -y iftop).")
            )
            return

        iface = (
            self.iftop_interface_var.get() or ""
        ).strip() or self.get_default_iface()
        duration = (self.iftop_duration_var.get() or "10").strip()
        if duration not in {"10", "20", "30"}:
            duration = "10"
        if not iface:
            self.log("iftop: Kein Interface ausgewählt.")
            if hasattr(self, "iftop_text"):
                self.iftop_text.delete("1.0", "end")
                self.iftop_text.insert(
                    "end",
                    "iftop konnte nicht gestartet werden: Kein Interface ausgewählt.\n",
                )
            return
        if not self.ensure_sudo_session(f"iftop Snapshot auf {iface}"):
            if hasattr(self, "iftop_text"):
                self._select_tools_tab(self.tab_iftop)
                self.iftop_text.delete("1.0", "end")
                self.iftop_text.insert(
                    "end",
                    "iftop benötigt Root-Rechte für Paketmitschnitt auf diesem Interface.\n"
                    "Der Snapshot wurde nicht gestartet, weil keine gültige sudo-Session vorhanden ist.\n",
                )
                self.iftop_text.see("1.0")
            return

        def job():
            rc, out = run_cmd(
                [
                    "sudo",
                    "-n",
                    "iftop",
                    "-t",
                    "-n",
                    "-N",
                    "-P",
                    "-s",
                    duration,
                    "-L",
                    "25",
                    "-i",
                    iface,
                ],
                timeout=max(40, int(duration) + 30),
            )

            def show():
                self._select_tools_tab(self.tab_iftop)
                self.iftop_text.delete("1.0", "end")
                if out.strip():
                    self.iftop_text.insert("end", out)
                    if rc == 124:
                        self.iftop_text.insert(
                            "end",
                            "\n\n" + self._iftop_timeout_hint(iface) + "\n",
                        )
                else:
                    self.iftop_text.insert(
                        "end",
                        self.tr(
                            "iftop_output_none",
                            "Keine iftop-Ausgabe erhalten (Root/NOPASSWD ggf. erforderlich).",
                        ),
                    )
                    if rc == 124:
                        self.iftop_text.insert(
                            "end",
                            "\n\n" + self._iftop_timeout_hint(iface) + "\n",
                        )
                self.iftop_text.see("1.0")
                if hasattr(self, "iftop_summary_var"):
                    self.iftop_summary_var.set(
                        self.summarize_iftop_output(iface, duration, out, rc)
                    )
                self.log(
                    self.tr(
                        "iftop_log_finished_rc",
                        "iftop Snapshot für {iface} abgeschlossen (rc={rc}).",
                    ).format(iface=iface, rc=rc)
                )

            self.after(0, show)

        threading.Thread(target=job, daemon=True).start()

    # ---------- htop ----------
    def htop_async(self):
        requested_source = (
            self.htop_source_var.get() or "auto"
        ).strip().lower() or "auto"
        if requested_source not in {"auto", "htop", "top", "ps"}:
            requested_source = "auto"

        if requested_source == "htop" and not has_cmd("htop"):
            self.log(
                self.tr("htop_log_missing", "htop fehlt (sudo apt install -y htop).")
            )
            return
        if requested_source == "top" and not has_cmd("top"):
            self.log("htop: top ist auf diesem System nicht verfügbar.")
            return
        if requested_source == "ps" and not has_cmd("ps"):
            self.log("htop: ps ist auf diesem System nicht verfügbar.")
            return
        if requested_source == "auto" and not any(
            has_cmd(cmd_name) for cmd_name in ("htop", "top", "ps")
        ):
            self.log("htop: Keine Prozessquelle verfügbar (htop/top/ps).")
            return

        def job():
            source = requested_source
            rc = 127
            out = ""

            def run_source(selected_source: str):
                if selected_source == "htop":
                    return run_cmd(["htop", "-b", "-n", "1"], timeout=20)
                if selected_source == "top":
                    return run_cmd(["top", "-b", "-n", "1"], timeout=20)
                return run_cmd(["ps", "aux", "--sort=-pcpu,-pmem"], timeout=20)

            if requested_source == "auto":
                for candidate in ("htop", "top", "ps"):
                    if not has_cmd(candidate):
                        continue
                    rc, out = run_source(candidate)
                    source = candidate
                    if candidate != "htop" or (
                        rc == 0 and "invalid option" not in (out or "").lower()
                    ):
                        break
            else:
                rc, out = run_source(requested_source)
                source = requested_source
                if (
                    requested_source == "htop"
                    and (rc != 0 or "invalid option" in (out or "").lower())
                    and has_cmd("top")
                ):
                    rc, out = run_source("top")
                    source = "top"
                elif (
                    requested_source == "htop"
                    and (rc != 0 or "invalid option" in (out or "").lower())
                    and has_cmd("ps")
                ):
                    rc, out = run_source("ps")
                    source = "ps"

            def show():
                self._select_tools_tab(self.tab_htop)
                self.htop_text.delete("1.0", "end")
                if out.strip():
                    self.htop_text.insert("end", out)
                else:
                    self.htop_text.insert(
                        "end",
                        self.tr(
                            "htop_output_none",
                            "Keine Prozessausgabe erhalten (htop/top/ps).",
                        ),
                    )
                self.update_htop_table(self._parse_htop_snapshot_processes(out, source))
                self.htop_text.see("1.0")
                if hasattr(self, "htop_summary_var"):
                    self.htop_summary_var.set(
                        self.summarize_htop_output(out, source, rc)
                    )
                self.log(
                    self.tr(
                        "htop_log_finished_rc",
                        "htop Snapshot abgeschlossen via {source} (rc={rc}).",
                    ).format(source=source, rc=rc)
                )

            self.after(0, show)

        threading.Thread(target=job, daemon=True).start()

    def vscode_async(self):
        launch_dir = os.environ.get("VSCODE_PROJECT_PATH", "").strip()
        if not launch_dir:
            repo_root = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
            for candidate in (repo_root, os.getcwd(), os.path.expanduser("~")):
                if candidate and os.path.isdir(candidate):
                    launch_dir = candidate
                    break

        def _start_proc(args, note):
            try:
                proc = subprocess.Popen(
                    args,
                    cwd=launch_dir or None,
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                )
                self.log(
                    self.tr(
                        "vscode_log_started",
                        "VS Code gestartet ({note}, PID {pid}).",
                    ).format(note=note, pid=proc.pid)
                )
                return True
            except Exception as e:
                self.log(
                    self.tr(
                        "vscode_log_start_failed",
                        "VS Code Start fehlgeschlagen ({note}): {error}",
                    ).format(note=note, error=e)
                )
                return False

        starter = os.environ.get("VSCODE_STARTER", "").strip()
        if starter:
            starter_args = shlex.split(starter)
            allowed_starters = {"code", "codium", "code-insiders", "gtk-launch"}
            starter_bin = os.path.basename(starter_args[0]) if starter_args else ""
            if starter_args and starter_bin in allowed_starters:
                if _start_proc(starter_args, "VSCODE_STARTER"):
                    return
            else:
                self.log_debug("VSCODE_STARTER ignoriert (nicht auf Allowlist).")

        desktop_file = self._find_vscode_desktop_file()
        if desktop_file:
            desktop_id = os.path.splitext(os.path.basename(desktop_file))[0]
            if has_cmd("gtk-launch") and _start_proc(
                ["gtk-launch", desktop_id], f"gtk-launch:{desktop_id}"
            ):
                return

            desktop_exec = self._desktop_exec_command(desktop_file)
            if desktop_exec and _start_proc(
                desktop_exec, f"Exec aus {os.path.basename(desktop_file)}"
            ):
                return

        for cmd in (
            ["code", "--new-window", launch_dir] if launch_dir else ["code"],
            ["codium", "--new-window", launch_dir] if launch_dir else ["codium"],
            (
                ["code-insiders", "--new-window", launch_dir]
                if launch_dir
                else ["code-insiders"]
            ),
        ):
            if has_cmd(cmd[0]) and _start_proc(cmd, cmd[0]):
                return

        self.log(
            "VS Code Starter nicht gefunden. Setze VSCODE_STARTER oder installiere code/codium."
        )

    # ---------- Whoami / Egress info ----------
    def whoami_async(self, force=False):
        if not force and not self.auto_external_checks.get():
            return

        def job():
            rc, out = run_cmd(
                ["curl", "-s", "--max-time", "4", "https://1.1.1.1/cdn-cgi/trace"],
                timeout=6,
            )
            info = parse_cf_trace(out)

            def show():
                self.nb.select(self.tab_log)
                if rc != 0 or not info:
                    self.log("Whoami: fehlgeschlagen (curl/Netz?).")
                    if out:
                        self.log(out)
                    self.update_vpn_status_text()
                    return
                keys = ["ip", "loc", "colo", "warp", "tls", "http"]
                nice = " | ".join([f"{k.upper()}={info.get(k,'-')}" for k in keys])
                self.log(f"Whoami (Egress): {nice}")
                self.update_vpn_status_text()

            self.after(0, show)

        threading.Thread(target=job, daemon=True).start()

    # ---------- Connections (PID/program -> remote) ----------
    def connections_async(self):
        if not has_cmd("ss"):
            self.log("Verbindungen: 'ss' fehlt (iproute2).")
            return

        def job():
            rc, out = run_cmd(["sudo", "-n", "ss", "-H", "-tunap"], timeout=8)
            if rc != 0 or not out.strip():
                rc, out = run_cmd(["ss", "-H", "-tunap"], timeout=8)

            conns = parse_ss_lines(out)

            def fill():
                self.nb.select(self.tab_conn)
                self._conn_rows_cache = conns

                for item in self.conn_table.get_children():
                    self.conn_table.delete(item)

                for c in conns:
                    self.conn_table.insert(
                        "",
                        "end",
                        values=(
                            c["proto"],
                            c["state"],
                            c["local"],
                            c["remote"],
                            c["pid"],
                            c["proc"],
                        ),
                    )

                self.connections_summary_var.set(self.summarize_connections_rows(conns))

                self.log(
                    f"Verbindungen aktualisiert: {len(conns)} Zeilen (PID/Proc ggf. nur mit sudo sichtbar)."
                )

            self.after(0, fill)

        threading.Thread(target=job, daemon=True).start()

    def arp_async(self):
        self.nb.select(self.tab_conn)

        def job():
            rc, out = run_cmd(["arp", "-a"], timeout=8)
            rows = []

            if rc == 0 and out:
                for line in out.splitlines():
                    row = self.parse_arp_line(line.strip())
                    if row:
                        rows.append(row)

            self.after(0, lambda data=rows: self.update_arp_table(data))

        threading.Thread(target=job, daemon=True).start()

    def parse_arp_line(self, line):
        pattern = (
            r"^(?P<host>\S+)\s+\((?P<ip>[^)]+)\)\s+"
            r"(?:auf|at)\s+(?P<mac>\S+)\s+\[(?P<type>[^\]]+)\]\s+"
            r"(?:auf|on)\s+(?P<iface>\S+)"
        )
        match = re.search(pattern, line or "")
        if not match:
            return None

        return {
            "host": match.group("host"),
            "ip": match.group("ip"),
            "mac": match.group("mac"),
            "type": match.group("type"),
            "iface": match.group("iface"),
        }

    def update_arp_table(self, rows):
        self._arp_rows_cache = list(rows or [])

        arp_table = self.__dict__.get("arp_table")
        if arp_table is not None:
            for item in arp_table.get_children():
                arp_table.delete(item)

            for row in self._arp_rows_cache:
                arp_table.insert(
                    "",
                    "end",
                    values=(
                        row.get("host", ""),
                        row.get("ip", ""),
                        row.get("mac", ""),
                        row.get("iface", ""),
                        row.get("type", ""),
                    ),
                )

        status_var = self.__dict__.get("arp_status_var")
        if status_var is not None:
            status_var.set(
                self.tr("connections_arp_status_count", "ARP: {count} Einträge").format(
                    count=len(self._arp_rows_cache)
                )
            )
        self._refresh_connections_summary()

    def route_async(self):
        try:
            self.nb.select(self.tab_conn)
        except Exception:
            pass

        def job():
            rc, out = run_cmd(["ip", "route"], timeout=8)
            rows = []

            if rc == 0 and out:
                for line in out.splitlines():
                    row = self.parse_route_line(line.strip())
                    if row:
                        rows.append(row)

            self.after(
                0, lambda data=rows, ok=(rc == 0): self.update_route_table(data, ok=ok)
            )

        threading.Thread(target=job, daemon=True).start()

    def parse_route_line(self, line):
        parts = (line or "").split()
        if not parts:
            return None

        row = {
            "dst": parts[0],
            "gateway": "",
            "iface": "",
            "src": "",
            "metric": "",
            "raw": line,
        }

        if parts[0] == "default":
            row["dst"] = "default"

        for idx, token in enumerate(parts):
            if token == "via" and idx + 1 < len(parts):
                row["gateway"] = parts[idx + 1]
            elif token == "dev" and idx + 1 < len(parts):
                row["iface"] = parts[idx + 1]
            elif token == "src" and idx + 1 < len(parts):
                row["src"] = parts[idx + 1]
            elif token == "metric" and idx + 1 < len(parts):
                row["metric"] = parts[idx + 1]

        return row

    def update_route_table(self, rows, ok=True):
        self._route_rows_cache = list(rows or [])

        route_table = self.__dict__.get("route_table")
        if route_table is not None:
            for item in route_table.get_children():
                route_table.delete(item)

            for row in self._route_rows_cache:
                route_table.insert(
                    "",
                    "end",
                    values=(
                        row.get("dst", ""),
                        row.get("gateway", ""),
                        row.get("iface", ""),
                        row.get("src", ""),
                        row.get("metric", ""),
                    ),
                )

        status_var = self.__dict__.get("route_status_var")
        if status_var is not None:
            if ok:
                status_var.set(
                    self.tr(
                        "connections_route_status_count",
                        "Routing: {count} Einträge",
                    ).format(count=len(self._route_rows_cache))
                )
            else:
                status_var.set(
                    self.tr(
                        "connections_route_status_error",
                        "Routing: Fehler beim Laden",
                    )
                )
        self._refresh_connections_summary()

    def summarize_connections_rows(self, rows) -> str:
        items = list(rows or [])
        if not items:
            return (
                "Status: Keine Verbindungen\n"
                "Einordnung: Aktuell sind keine auswertbaren Verbindungsdaten geladen."
            )

        established = 0
        listen = 0
        external = 0
        with_pid = 0
        for item in items:
            state = str(item.get("state") or "").upper()
            remote = str(item.get("remote") or "").strip()
            pid = str(item.get("pid") or "").strip()
            if state == "ESTAB" or state == "ESTABLISHED":
                established += 1
            if state == "LISTEN":
                listen += 1
            if pid:
                with_pid += 1
            if remote and not remote.startswith(("127.", "[::1]", "::1", "*")):
                external += 1

        if external > 0:
            assessment = (
                "Es sind aktive oder potenziell externe Netzwerkverbindungen sichtbar."
            )
        elif listen > 0:
            assessment = "Der Fokus liegt aktuell eher auf lokalen Listenern als auf externen Zielen."
        else:
            assessment = (
                "Momentaufnahme der lokalen Verbindungen und Prozesse ist verfügbar."
            )

        return "\n".join(
            [
                f"Aktive Verbindungen: {len(items)}",
                f"ESTABLISHED: {established}",
                f"LISTEN: {listen}",
                f"Externe Ziele: {external}",
                f"Mit PID erkannt: {with_pid}",
                f"ARP Einträge: {len(getattr(self, '_arp_rows_cache', []) or [])}",
                f"Routen: {len(getattr(self, '_route_rows_cache', []) or [])}",
                "",
                f"Einordnung: {assessment}",
            ]
        )

    def _refresh_connections_summary(self):
        try:
            self.connections_summary_var.set(
                self.summarize_connections_rows(getattr(self, "_conn_rows_cache", []))
            )
        except Exception:
            pass

    def clear_connections_view(self):
        for table_name in ("conn_table", "arp_table", "route_table"):
            table_widget = self.__dict__.get(table_name)
            if table_widget is None:
                continue
            try:
                table_widget.delete(*table_widget.get_children())
            except Exception:
                pass
        self._conn_rows_cache = []
        self._arp_rows_cache = []
        self._route_rows_cache = []
        self._set_connection_detail_fields(None)
        try:
            self.arp_status_var.set("ARP: Anzeige geleert")
        except Exception:
            pass
        try:
            self.route_status_var.set("Routing: Anzeige geleert")
        except Exception:
            pass
        try:
            self.connections_summary_var.set("Verbindungen-Bewertung wurde geleert.")
        except Exception:
            pass
        self.log("Verbindungen: Anzeige geleert.")

    def refresh_all_connections_views(self):
        self.connections_async()
        self.arp_async()
        self.route_async()
        self.log("Verbindungen: Alle Ansichten werden aktualisiert.")

    def _set_connection_detail_fields(self, row=None):
        defaults = {
            "conn_detail_proto_var": "keine Auswahl",
            "conn_detail_state_var": "keine Auswahl",
            "conn_detail_pid_var": "keine Auswahl",
            "conn_detail_local_var": "Noch keine Verbindung ausgewählt.",
            "conn_detail_remote_var": "keine Auswahl",
            "conn_detail_proc_var": "keine Auswahl",
        }
        if not row:
            for attr_name, value in defaults.items():
                getattr(self, attr_name).set(value)
            return
        self.conn_detail_proto_var.set(str(row.get("proto") or "-"))
        self.conn_detail_state_var.set(str(row.get("state") or "-"))
        self.conn_detail_pid_var.set(str(row.get("pid") or "-"))
        self.conn_detail_local_var.set(str(row.get("local") or "-"))
        self.conn_detail_remote_var.set(str(row.get("remote") or "-"))
        self.conn_detail_proc_var.set(str(row.get("proc") or "-"))

    def on_connection_select(self, _event=None):
        table = self.__dict__.get("conn_table")
        if table is None:
            return
        try:
            selection = list(table.selection())
        except Exception:
            selection = []
        if not selection:
            self._set_connection_detail_fields(None)
            return
        item_id = selection[0]
        try:
            values = list(table.item(item_id, "values") or [])
        except Exception:
            values = []
        if len(values) < 6:
            self._set_connection_detail_fields(None)
            return
        row = {
            "proto": values[0],
            "state": values[1],
            "local": values[2],
            "remote": values[3],
            "pid": values[4],
            "proc": values[5],
        }
        self._set_connection_detail_fields(row)

    def clear_conn_filters(self):
        self.conn_filter.set("")
        self.conn_process_filter_var.set("")
        self.conn_pid_filter_var.set("")
        self.conn_state_filter_var.set("")
        self.conn_only_external_var.set(False)
        self.conn_only_established_var.set(False)
        self.apply_conn_filter()

    def _connection_matches_filters(
        self,
        row,
        *,
        text_filter,
        process_filter,
        pid_filter,
        state_filter,
        only_external,
        only_established,
    ):
        proto = str(row.get("proto") or "")
        state = str(row.get("state") or "")
        local = str(row.get("local") or "")
        remote = str(row.get("remote") or "")
        pid = str(row.get("pid") or "")
        proc = str(row.get("proc") or "")

        blob = f"{proto} {state} {local} {remote} {pid} {proc}".lower()
        if text_filter and text_filter not in blob:
            return False
        if process_filter and process_filter not in proc.lower():
            return False
        if pid_filter and pid_filter not in pid:
            return False
        if state_filter and state_filter not in state.lower():
            return False
        if only_established and state.upper() not in {"ESTAB", "ESTABLISHED"}:
            return False
        if only_external:
            remote_host = remote
            if remote_host.startswith("[") and "]:" in remote_host:
                remote_host = remote_host[1:].split("]:", 1)[0]
            elif ":" in remote_host:
                remote_host = remote_host.rsplit(":", 1)[0]
            remote_host = remote_host.strip()
            if not remote_host or remote_host == "*" or is_local_or_lan_ip(remote_host):
                return False
        return True

    def apply_conn_filter(self):
        q = (self.conn_filter.get() or "").strip().lower()
        process_filter = (self.conn_process_filter_var.get() or "").strip().lower()
        pid_filter = (self.conn_pid_filter_var.get() or "").strip()
        state_filter = (self.conn_state_filter_var.get() or "").strip().lower()
        only_external = bool(self.conn_only_external_var.get())
        only_established = bool(self.conn_only_established_var.get())
        rows = self._conn_rows_cache

        for item in self.conn_table.get_children():
            self.conn_table.delete(item)

        if not any(
            (
                q,
                process_filter,
                pid_filter,
                state_filter,
                only_external,
                only_established,
            )
        ):
            for c in rows:
                self.conn_table.insert(
                    "",
                    "end",
                    values=(
                        c["proto"],
                        c["state"],
                        c["local"],
                        c["remote"],
                        c["pid"],
                        c["proc"],
                    ),
                )
            self._set_connection_detail_fields(rows[0] if rows else None)
            return

        visible_rows = []
        for c in rows:
            if not self._connection_matches_filters(
                c,
                text_filter=q,
                process_filter=process_filter,
                pid_filter=pid_filter,
                state_filter=state_filter,
                only_external=only_external,
                only_established=only_established,
            ):
                continue
            visible_rows.append(c)
            self.conn_table.insert(
                "",
                "end",
                values=(
                    c["proto"],
                    c["state"],
                    c["local"],
                    c["remote"],
                    c["pid"],
                    c["proc"],
                ),
            )
        self._set_connection_detail_fields(visible_rows[0] if visible_rows else None)

    def _format_connection_values(self, values) -> str:
        cols = [str(value or "").strip() for value in values]
        while len(cols) < 6:
            cols.append("")
        return (
            f"Proto: {cols[0]} | State: {cols[1]} | Local: {cols[2]} | "
            f"Remote: {cols[3]} | PID: {cols[4]} | Process: {cols[5]}"
        )

    def _selected_connection_row(self):
        table = self.__dict__.get("conn_table")
        if table is None:
            return None
        try:
            selection = list(table.selection())
        except Exception:
            selection = []
        if not selection:
            return None
        try:
            values = list(table.item(selection[0], "values") or [])
        except Exception:
            values = []
        if len(values) < 6:
            return None
        return {
            "proto": values[0],
            "state": values[1],
            "local": values[2],
            "remote": values[3],
            "pid": values[4],
            "proc": values[5],
        }

    def _extract_connection_remote_host(self, remote: str) -> str:
        value = str(remote or "").strip()
        if not value or value == "*":
            return ""
        if value.startswith("[") and "]:" in value:
            return value[1:].split("]:", 1)[0].strip()
        if value.count(":") >= 2 and not value.startswith("["):
            return value.strip()
        if ":" in value:
            return value.rsplit(":", 1)[0].strip()
        return value

    def send_selected_connection_to_trace(self):
        row = self._selected_connection_row()
        if not row:
            self.log("Verbindungen: Keine Auswahl für Trace-Übergabe vorhanden.")
            return
        remote_host = self._extract_connection_remote_host(row.get("remote", ""))
        if not remote_host or not is_safe_trace_target(remote_host):
            self.log(
                "Verbindungen: Remote-Ziel konnte nicht sauber an Trace übergeben werden."
            )
            return
        self.trace_manual_target_var.set(remote_host)
        trace_entry = self.__dict__.get("trace_manual_target_entry")
        if trace_entry is not None:
            try:
                trace_entry.delete(0, "end")
                trace_entry.insert(0, remote_host)
            except Exception:
                pass
        nb = self.__dict__.get("nb")
        if nb is not None:
            try:
                nb.select(self.tab_trace)
            except Exception:
                pass
        self.log(f"Verbindungen: Remote-Ziel an Trace übergeben: {remote_host}")

    def send_selected_connection_to_nmap(self):
        row = self._selected_connection_row()
        if not row:
            self.log("Verbindungen: Keine Auswahl für Nmap-Übergabe vorhanden.")
            return
        remote_host = self._extract_connection_remote_host(row.get("remote", ""))
        if not remote_host or not is_safe_trace_target(remote_host):
            self.log(
                "Verbindungen: Remote-Ziel konnte nicht sauber an Nmap übergeben werden."
            )
            return
        self.nmap_manual_target_var.set(remote_host)
        self._select_tools_tab(self.tab_nmap)
        self.log(f"Verbindungen: Remote-Ziel an Nmap übergeben: {remote_host}")

