    # ---------- DNS Status ----------
    def _detect_dnssec_mode(self, raw_text: str) -> str:
        service = self._dns_control_service()
        if service is not None:
            return service.detect_dnssec_mode(raw_text)
        lower_text = (raw_text or "").lower()
        if "dnssec=yes" in lower_text or "dnssec setting: yes" in lower_text:
            return "yes"
        if (
            "dnssec=allow-downgrade" in lower_text
            or "dnssec setting: allow-downgrade" in lower_text
        ):
            return "allow-downgrade"
        if "dnssec=no" in lower_text or "dnssec setting: no" in lower_text:
            return "no"
        return "unknown"

    def dnssec_strict_mode_warning_text(self) -> str:
        return (
            "DNSSEC Strict Mode kann bei inkompatiblen Netzwerken oder Resolvern "
            "DNS-Probleme verursachen.\n"
            "Nur aktivieren, wenn der verwendete DNS-Anbieter DNSSEC zuverlässig unterstützt."
        )

    def get_preferred_dnssec_mode(self) -> str:
        mode_var = self.__dict__.get("var_dnssec_mode")
        if mode_var is not None:
            try:
                configured = str(mode_var.get() or "standard")
            except Exception:
                configured = "standard"
        else:
            settings = self.__dict__.get("settings", {}) or {}
            configured = str(settings.get("dnssec_mode", "standard") or "standard")
        configured = configured.strip().lower()
        return "strict" if configured == "strict" else "standard"

    def _dnssec_preferred_mode_label(self, mode: str) -> str:
        return "Strict" if mode == "strict" else "Standard"

    def _dnssec_system_mode_label(self, mode: str) -> str:
        if mode == "yes":
            return "Strict Mode"
        if mode == "allow-downgrade":
            return "Fallback möglich"
        if mode == "no":
            return "deaktiviert"
        return "unbekannt"

    def update_dnssec_mode_status_labels(self, system_mode: str | None = None):
        target_var = self.__dict__.get("dnssec_target_mode_var")
        if target_var is not None:
            try:
                target_var.set(
                    "DNSSEC Zielmodus: "
                    + self._dnssec_preferred_mode_label(
                        self.get_preferred_dnssec_mode()
                    )
                )
            except Exception:
                pass
        system_var = self.__dict__.get("dnssec_system_mode_var")
        if system_var is not None and system_mode is not None:
            try:
                system_var.set(
                    "DNSSEC Systemmodus: " + self._dnssec_system_mode_label(system_mode)
                )
            except Exception:
                pass

    def confirm_dnssec_mode_activation(self, action_name="DNSSEC Strict Mode") -> bool:
        if self.get_preferred_dnssec_mode() != "strict":
            return True
        message = (
            self.dnssec_strict_mode_warning_text()
            + "\n\n"
            + f"Fortfahren mit: {action_name}?"
        )
        return messagebox.askyesno(
            "DNSSEC Strict Mode",
            message,
            parent=self,
        )

    def on_dnssec_mode_changed(self):
        mode_var = self.__dict__.get("var_dnssec_mode")
        if mode_var is None:
            return
        try:
            mode = str(mode_var.get() or "standard").strip().lower() or "standard"
        except Exception:
            mode = "standard"
        normalized = "strict" if mode == "strict" else "standard"
        try:
            mode_var.set(normalized)
        except Exception:
            pass
        settings = self.__dict__.setdefault("settings", {})
        if isinstance(settings, dict):
            settings["dnssec_mode"] = normalized
        self.update_dnssec_mode_status_labels()
        if normalized == "strict":
            self.log_safe(
                "DNSSEC Strict Mode vorbereitet. Aktivierung erfolgt erst nach expliziter Umsetzung."
            )

    def _render_dnssec_mode_dropin(
        self, dropin_text: str, mode: str | None = None
    ) -> str:
        text = (dropin_text or "").strip("\n")
        if not text:
            return ""
        desired = (
            "yes"
            if (mode or self.get_preferred_dnssec_mode()) == "strict"
            else "allow-downgrade"
        )
        lines = text.splitlines()
        new_lines = []
        replaced = False
        inserted = False
        for raw_line in lines:
            stripped = raw_line.strip()
            lower = stripped.lower()
            if lower.startswith("dnssec="):
                new_lines.append(f"DNSSEC={desired}")
                replaced = True
                continue
            new_lines.append(raw_line)
            if not inserted and lower.startswith("dnsovertls="):
                if not replaced:
                    new_lines.append(f"DNSSEC={desired}")
                inserted = True
        if not replaced and not inserted:
            appended = False
            final_lines = []
            for raw_line in new_lines:
                final_lines.append(raw_line)
                if not appended and raw_line.strip() == "[Resolve]":
                    final_lines.append(f"DNSSEC={desired}")
                    appended = True
            new_lines = final_lines
        return "\n".join(new_lines).strip() + "\n"

    def apply_dnssec_mode_async(self):
        self._record_diagnostic_action(
            "DNSSEC-Modus anwenden",
            "dns",
            details={
                "preferred_mode": str(self.get_preferred_dnssec_mode() or ""),
            },
        )
        self.nb.select(self.tab_dns)
        if not self.confirm_dnssec_mode_activation("DNSSEC-Modus anwenden"):
            self.update_dns_output(
                "=== DNSSEC-Modus anwenden ===\n"
                "Status: abgebrochen\n"
                "Grund: DNSSEC Strict Mode wurde nicht bestätigt."
            )
            self.log_safe(
                "DNSSEC-Modus anwenden abgebrochen: DNSSEC Strict Mode nicht bestätigt"
            )
            return
        if not self.ensure_sudo_session("DNSSEC-Modus anwenden"):
            return

        self.update_dns_output(
            "=== DNSSEC-Modus anwenden ===\nStatus: Anwendung läuft\n",
            append=False,
        )
        self.log_safe("DNSSEC-Modus anwenden gestartet")

        def job():
            previous_dropin = self._read_dot_dropin()
            desired_mode = self.get_preferred_dnssec_mode()
            settings = self.__dict__.setdefault("settings", {})
            if isinstance(settings, dict):
                settings["dnssec_mode"] = desired_mode
            if not previous_dropin.strip():
                system_mode, _raw = self.check_dnssec_status()
                self.update_dnssec_mode_status_labels(system_mode)
                result = (
                    "=== DNSSEC-Modus anwenden ===\n"
                    f"Zielmodus: {self._dnssec_preferred_mode_label(desired_mode)}\n"
                    f"Systemmodus: {self._dnssec_system_mode_label(system_mode)}\n\n"
                    "[System]\n"
                    "○ Keine NetMon DNS-/DoT-Konfiguration aktiv\n\n"
                    "=== Ergebnis ===\n"
                    "○ Modus vorgemerkt\n"
                    "○ Der gewählte Modus wird beim nächsten DNS-/DoT-Anwenden übernommen"
                )
            elif "# Managed by NetMon" not in previous_dropin:
                system_mode, _raw = self.check_dnssec_status()
                self.update_dnssec_mode_status_labels(system_mode)
                result = (
                    "=== DNSSEC-Modus anwenden ===\n"
                    f"Zielmodus: {self._dnssec_preferred_mode_label(desired_mode)}\n"
                    f"Systemmodus: {self._dnssec_system_mode_label(system_mode)}\n\n"
                    "[System]\n"
                    "✖ Keine von NetMon verwaltete DNS-/DoT-Konfiguration gefunden\n\n"
                    "=== Ergebnis ===\n"
                    "✖ DNSSEC-Modus nicht angewendet"
                )
            else:
                new_dropin = self._render_dnssec_mode_dropin(
                    previous_dropin, desired_mode
                )
                write_ok, write_detail = self._write_dot_dropin_text(new_dropin)
                restart_ok = False
                restart_detail = ""
                rollback_ok = True
                rollback_detail = ""
                if write_ok:
                    restart_ok, restart_detail = self._restart_resolved_for_dns_policy()
                if write_ok and restart_ok:
                    system_mode, _raw = self.check_dnssec_status()
                    self.update_dnssec_mode_status_labels(system_mode)
                    result = (
                        "=== DNSSEC-Modus anwenden ===\n"
                        f"Zielmodus: {self._dnssec_preferred_mode_label(desired_mode)}\n"
                        f"Systemmodus: {self._dnssec_system_mode_label(system_mode)}\n\n"
                        "[System]\n"
                        "✔ NetMon DNS-/DoT-Konfiguration erkannt\n"
                        "✔ DNSSEC-Modus geschrieben\n"
                        "✔ systemd-resolved neu gestartet\n\n"
                        "=== Ergebnis ===\n"
                        "✔ DNSSEC-Modus angewendet"
                    )
                else:
                    rollback_ok, rollback_detail = self._restore_dot_dropin_backup(
                        previous_dropin
                    )
                    self._restart_resolved_for_dns_policy()
                    system_mode, _raw = self.check_dnssec_status()
                    self.update_dnssec_mode_status_labels(system_mode)
                    reason = write_detail if not write_ok else restart_detail
                    result = (
                        "=== DNSSEC-Modus anwenden ===\n"
                        f"Zielmodus: {self._dnssec_preferred_mode_label(desired_mode)}\n"
                        f"Systemmodus: {self._dnssec_system_mode_label(system_mode)}\n\n"
                        "[System]\n"
                        "✖ DNSSEC-Modus konnte nicht geschrieben werden\n"
                        f"✖ Fehler: {reason or 'unbekannter Fehler'}\n\n"
                        "=== Ergebnis ===\n"
                        "✖ DNSSEC-Modus nicht angewendet"
                    )
                    if rollback_ok:
                        result += (
                            "\n✔ Rollback: vorherige Konfiguration wiederhergestellt"
                        )
                    else:
                        result += "\n✖ Rollback: fehlgeschlagen" + (
                            f" ({rollback_detail})" if rollback_detail else ""
                        )

            def show():
                self.nb.select(self.tab_dns)
                self.update_dns_output(result, append=False)
                try:
                    self.save_settings(log_success=False)
                except Exception:
                    pass
                self.log_safe("DNSSEC-Modus anwenden abgeschlossen")

            self.after(0, show)

        threading.Thread(target=job, daemon=True).start()

    def check_dnssec_status(self):
        if not has_cmd("resolvectl"):
            return "unknown", "resolvectl nicht verfügbar"

        code, out = run_cmd(["resolvectl", "status"], timeout=5)
        if code != 0:
            return "unknown", out.strip() or "resolvectl nicht verfügbar"

        dnssec_lines = [
            line.strip()
            for line in (out or "").splitlines()
            if "dnssec" in line.lower()
        ]
        dnssec_text = "\n".join(dnssec_lines).strip() or out
        return self._detect_dnssec_mode(dnssec_text), dnssec_text

    def _format_dnssec_result_text(self, *, mode, valid, msg):
        lines = ["=== DNSSEC Prüfung ===", ""]

        if valid:
            lines.append("✔ Gesamtstatus: OK")
        else:
            lines.append("✖ Gesamtstatus: FEHLER")

        if mode == "yes":
            lines.append("✔ DNSSEC-Validierung aktiv")
            lines.append("✔ Manipulationsschutz: aktiv (Strict Mode)")
        elif mode == "allow-downgrade":
            lines.append("✔ DNSSEC-Validierung aktiv")
            lines.append("○ Manipulationsschutz: aktiv (Fallback möglich)")
        elif mode == "no":
            lines.append("✖ DNSSEC-Validierung fehlgeschlagen")
            lines.append("✖ Manipulationsschutz: deaktiviert")
        elif valid:
            lines.append("✔ DNSSEC-Validierung aktiv")
            lines.append("○ Manipulationsschutz: Status nicht eindeutig")
        else:
            lines.append("✖ DNSSEC-Validierung fehlgeschlagen")
            lines.append("✖ Manipulationsschutz nicht aktiv")

        lines.extend(["", "=== Ergebnis ===", f"{'✔' if valid else '✖'} {msg}"])
        return "\n".join(lines)

    def test_dnssec_validation(self):
        if has_cmd("resolvectl"):
            code, out = run_cmd(["resolvectl", "query", "dnssec-failed.org"], timeout=6)
            lower_out = (out or "").lower()
            if code != 0 and (
                "dnssec validation failed" in lower_out
                or "resolve call failed" in lower_out
                or "failed to resolve" in lower_out
                or "no appropriate name servers" in lower_out
            ):
                return (
                    True,
                    "DNSSEC funktioniert korrekt (Manipulation erkannt über systemd-resolved).",
                )
            if code == 0 and out.strip():
                return (
                    False,
                    "DNSSEC-Test fehlgeschlagen: dnssec-failed.org wurde trotzdem aufgelöst.",
                )

        if not has_cmd("dig"):
            return False, "DNSSEC-Test nicht möglich: dig ist nicht verfügbar."

        code, out = run_cmd(
            ["dig", "+dnssec", "+comments", "dnssec-failed.org"], timeout=6
        )
        lower_out = (out or "").lower()
        if code != 0 and not out.strip():
            return (
                False,
                "DNSSEC-Test fehlgeschlagen: dig konnte nicht ausgeführt werden.",
            )

        if "status: servfail" in lower_out:
            return True, "DNSSEC funktioniert korrekt (Manipulation erkannt)"

        if "status: noerror" in lower_out or "status: nxdomain" in lower_out:
            return (
                False,
                "DNSSEC-Test fehlgeschlagen: dnssec-failed.org wurde nicht geblockt.",
            )

        return False, "DNSSEC-Test uneindeutig. Resolver-Antwort bitte prüfen."

    def run_dnssec_check(self):
        self.nb.select(self.tab_dns)
        self.log(self.tr("dns_log_dnssec_started", "DNSSEC-Prüfung gestartet"))

        def job():
            mode, _raw = self.check_dnssec_status()
            valid, msg = self.test_dnssec_validation()
            self.update_dnssec_mode_status_labels(mode)
            result = self._format_dnssec_result_text(
                mode=mode,
                valid=valid,
                msg=msg,
            )

            def show():
                self.nb.select(self.tab_dns)
                self.update_dns_output(result)
                self.log(
                    self.tr(
                        "dns_log_dnssec_finished",
                        "DNSSEC-Prüfung abgeschlossen",
                    )
                )

            self.after(0, show)

        threading.Thread(target=job, daemon=True).start()

    def analyze_dns_health_output(self, out: str) -> str:
        service = self._dns_control_service()
        if service is None:
            return "=== DNS Health Check ===\n\nDNS-Control-Service nicht verfügbar."
        return service.build_dns_health_report(out or "")

    def run_dns_health_check(self):
        self.nb.select(self.tab_dns)
        self.log(self.tr("dns_log_health_started", "DNS Health Check gestartet"))

        def job():
            code, out = run_cmd(["resolvectl", "status"], timeout=8)

            if code != 0:
                result = (
                    "=== DNS Health Check ===\n"
                    "\n"
                    "✖ Gesamtstatus: FEHLER\n"
                    "✖ Resolverstatus konnte nicht gelesen werden\n"
                    "\n"
                    "=== Ergebnis ===\n"
                    "✖ DNS-Health-Prüfung fehlgeschlagen"
                )
            else:
                result = self.analyze_dns_health_output(out)

            def show():
                self.nb.select(self.tab_dns)
                self.update_dns_output(result, append=True)
                self.log(
                    self.tr(
                        "dns_log_health_finished",
                        "DNS Health Check abgeschlossen",
                    )
                )

            self.after(0, show)

        threading.Thread(target=job, daemon=True).start()

    def get_public_ip(self):
        code, out = run_cmd(["curl", "-s", "https://api.ipify.org"], timeout=6)
        if code == 0:
            return (out or "").strip() or "unbekannt"
        return "unbekannt"

    def get_active_dns_servers(self):
        service = self._dns_control_service()
        if service is None:
            return []
        code, out = service.read_resolvectl_status(timeout=6)
        if code != 0:
            return []
        return service.parse_active_dns_servers(out)

    def _parse_active_dns_servers(self, resolvectl_output: str):
        service = self._dns_control_service()
        if service is None:
            return []
        return service.parse_active_dns_servers(resolvectl_output)

    def detect_vpn_active(self, resolvectl_output: str) -> bool:
        service = self._dns_control_service()
        if service is None:
            text = (resolvectl_output or "").lower()
            return any(
                token in text for token in ("proton", "wg", "wireguard", "tun", "vpn")
            )
        return service.detect_vpn_active(resolvectl_output)

    def _dns_leak_is_private_or_local_dns(self, dns_server: str) -> bool:
        service = self._dns_control_service()
        if service is None:
            value = (dns_server or "").strip().strip("[]")
            if not value:
                return False
            if "%" in value:
                value = value.split("%", 1)[0]
            try:
                addr = ipaddress.ip_address(value)
            except ValueError:
                return False
            return addr.is_private or addr.is_loopback or addr.is_link_local
        return service.dns_server_is_private_or_local(dns_server)

    def build_dns_leak_check_result(
        self,
        resolvectl_output: str,
        dns_servers: list[str],
        public_ip: str,
    ) -> str:
        service = self._dns_control_service()
        if service is None:
            return "=== DNS Leak Check ===\n\nDNS-Control-Service nicht verfügbar."
        return service.build_dns_leak_check_result(
            resolvectl_output=resolvectl_output,
            dns_servers=dns_servers,
            public_ip=public_ip,
        )

    def run_dns_leak_check(self, quiet: bool = False):
        if not quiet:
            self.nb.select(self.tab_dns)
            self.log(self.tr("dns_log_leak_started", "DNS Leak Check gestartet"))

        def job():
            code, out = run_cmd(["resolvectl", "status"], timeout=6)
            resolvectl_output = out or ""
            if code == 0:
                dns_servers = self._parse_active_dns_servers(resolvectl_output)
            else:
                dns_servers = []
                resolvectl_output = (
                    resolvectl_output.strip()
                    or "resolvectl status konnte nicht gelesen werden."
                )

            public_ip = self.get_public_ip()
            result = self.build_dns_leak_check_result(
                resolvectl_output=resolvectl_output,
                dns_servers=dns_servers,
                public_ip=public_ip,
            )
            self.last_dns_leak_result = result

            if code != 0:
                result = (
                    result
                    + "\n\nHinweis:\n"
                    + "- resolvectl status konnte nicht gelesen werden; VPN-Erkennung ist eingeschränkt.\n"
                    + f"\nDetails:\n{resolvectl_output}"
                )

            def show():
                if not quiet:
                    self.nb.select(self.tab_dns)
                    self.update_dns_output(result, append=True)
                    self.log(
                        self.tr(
                            "dns_log_leak_finished",
                            "DNS Leak Check abgeschlossen",
                        )
                    )

            if quiet:
                return
            self.after(0, show)

        threading.Thread(target=job, daemon=True).start()

    def find_vpn_dns_servers(self):
        service = self._dns_control_service()
        if service is None:
            return "", [], "DNS-Control-Service nicht verfügbar."
        code, out = service.read_resolvectl_status(timeout=8)
        if code != 0:
            return "", [], out
        vpn_iface, vpn_dns = service.find_vpn_dns_servers(out)
        return vpn_iface, vpn_dns, out

    def capture_dns_state(self):
        code, out = run_cmd(["resolvectl", "status"], timeout=8)
        return {
            "timestamp": datetime.now().isoformat(),
            "resolvectl_status": out if code == 0 else "",
        }

    def _show_dns_repair_message(self, title: str, text: str):
        self.update_dns_output(text, append=True)
        self.chad_analysis_status_var.set(title)

    def dns_leak_repair_async(self):
        self.nb.select(self.tab_dns)
        self.log(self.tr("dns_log_leak_repair_prepared", "DNS Leak Repair vorbereitet"))

        def find_job():
            vpn_iface, vpn_dns, raw = self.find_vpn_dns_servers()

            def ask_or_report():
                if not vpn_dns or not vpn_iface:
                    result = (
                        "=== DNS Leak Repair ===\n\n"
                        "Status: abgebrochen\n"
                        "Grund: Kein VPN-DNS gefunden.\n\n"
                        "Hinweis: Es wurden keine DNS-Server auf einem VPN-Link "
                        "(proton/wg/wireguard/tun/vpn) erkannt."
                    )
                    self._show_dns_repair_message("DNS Leak Repair", result)
                    return

                msg = self.tr(
                    "dns_leak_repair_confirm_message",
                    "DNS Leak Repair versucht, öffentliche DNS-Server zu entfernen "
                    "und VPN-DNS zu bevorzugen.\n\n"
                    "VPN-Interface: {vpn_iface}\n"
                    "Gefundene VPN-DNS:\n{vpn_dns}\n\n"
                    "Fortfahren?",
                ).format(vpn_iface=vpn_iface, vpn_dns=", ".join(vpn_dns))
                ok = messagebox.askyesno(
                    self.tr("dns_leak_repair_title", "DNS Leak Repair"),
                    msg,
                    parent=self,
                )
                if not ok:
                    self.chad_analysis_status_var.set(
                        self.tr(
                            "dns_leak_repair_status_cancelled",
                            "DNS Leak Repair abgebrochen.",
                        )
                    )
                    self.log(
                        self.tr(
                            "dns_leak_repair_log_cancelled",
                            "DNS Leak Repair abgebrochen",
                        )
                    )
                    return
                if not self.ensure_sudo_session("DNS Leak Repair"):
                    result = (
                        "=== DNS Leak Repair ===\n\n"
                        "Status: abgebrochen\n"
                        "Grund: sudo-Freigabe fehlt."
                    )
                    self._show_dns_repair_message("DNS Leak Repair", result)
                    return

                threading.Thread(
                    target=self.dns_leak_repair,
                    args=(vpn_iface, vpn_dns, raw),
                    daemon=True,
                ).start()

            self.after(0, ask_or_report)

        threading.Thread(target=find_job, daemon=True).start()

    def dns_leak_repair(self, vpn_iface: str, vpn_dns: list[str], raw: str = ""):
        self.last_dns_repair_state = self.capture_dns_state()

        code, route_out = run_cmd(["ip", "route", "show", "default"], timeout=5)
        main_iface = ""
        if code == 0:
            parts = route_out.split()
            if "dev" in parts:
                try:
                    main_iface = parts[parts.index("dev") + 1]
                except Exception:
                    main_iface = ""

        actions = []
        errors = []

        if main_iface and main_iface != vpn_iface:
            rc, out = run_cmd(
                ["sudo", "-n", "resolvectl", "revert", main_iface],
                timeout=10,
            )
            actions.append(f"resolvectl revert {main_iface}: rc={rc}")
            if rc != 0:
                errors.append(out or f"revert {main_iface} fehlgeschlagen")

        rc, out = run_cmd(
            ["sudo", "-n", "resolvectl", "dns", vpn_iface, *vpn_dns],
            timeout=10,
        )
        actions.append(f"resolvectl dns {vpn_iface} {' '.join(vpn_dns)}: rc={rc}")
        if rc != 0:
            errors.append(out or f"resolvectl dns {vpn_iface} fehlgeschlagen")

        rc, out = run_cmd(
            ["sudo", "-n", "systemctl", "restart", "systemd-resolved"],
            timeout=15,
        )
        actions.append(f"restart systemd-resolved: rc={rc}")
        if rc != 0:
            errors.append(out or "systemd-resolved restart fehlgeschlagen")

        result = (
            "=== DNS Leak Repair ===\n\n"
            f"VPN-Interface: {vpn_iface}\n"
            f"VPN-DNS: {', '.join(vpn_dns)}\n"
            f"Vorheriger DNS-Zustand gesichert: {'JA' if self.last_dns_repair_state else 'NEIN'}\n\n"
            "Aktionen:\n- " + "\n- ".join(actions)
        )

        if errors:
            result += "\n\nFehler:\n- " + "\n- ".join(str(err) for err in errors)

        def show():
            self._show_dns_repair_message("DNS Leak Repair", result)
            self.run_dns_leak_check()

        self.after(0, show)

